    "ALTER TABLE invites ADD COLUMN invite_type TEXT DEFAULT 'link'",
    "ALTER TABLE invites ADD COLUMN reward_voice INTEGER DEFAULT 0",
    "ALTER TABLE packages ADD COLUMN star_price INTEGER DEFAULT 0",
    "ALTER TABLE prompt_modes ADD COLUMN group_prompt TEXT",
