    // migration: add user_id and importance to the old archive table
    "ALTER TABLE archive ADD COLUMN user_id INTEGER",
    "ALTER TABLE archive ADD COLUMN importance INTEGER DEFAULT 0",
    // migration: chat_config
    "ALTER TABLE chat_config ADD COLUMN web_search INTEGER DEFAULT NULL",
    "ALTER TABLE chat_config ADD COLUMN importance_scoring INTEGER DEFAULT NULL",
    "ALTER TABLE chat_config ADD COLUMN memory_enabled INTEGER DEFAULT NULL",
