async function getGC(db) {
  if (_gcCache && (Date.now() - _gcCacheAt) < 60_000) return _gcCache;
  const rows = await db.prepare("SELECT key,value FROM global_config").all();
  const m = {};
  for (const r of (rows.results||[])) { try{m[r.key]=JSON.parse(r.value);}catch{m[r.key]=r.value;} }
  _gcCache = {
    defaultMsgLimit:      m.defaultMsgLimit      ?? C.DEF_MSG,
    defaultImgLimit:      m.defaultImgLimit      ?? C.DEF_IMG,
    defaultDailyMsgLimit: m.defaultDailyMsgLimit ?? C.DEF_DAY_MSG,
    defaultDailyImgLimit: m.defaultDailyImgLimit ?? C.DEF_DAY_IMG,
    defaultGroupMsgLimit: m.defaultGroupMsgLimit ?? C.DEF_GRP_MSG,
    defaultGroupImgLimit: m.defaultGroupImgLimit ?? C.DEF_GRP_IMG,
    defaultGroupDailyMsg: m.defaultGroupDailyMsg ?? C.DEF_GRP_DAY_MSG,
    defaultGroupDailyImg: m.defaultGroupDailyImg ?? C.DEF_GRP_DAY_IMG,
    welcomeMsgLimit:      m.welcomeMsgLimit      ?? 0,
    welcomeImgLimit:      m.welcomeImgLimit      ?? 0,
    inviteRewardMsg:      m.inviteRewardMsg      ?? 5,
    inviteRewardImg:      m.inviteRewardImg      ?? 2,
    inviteRewardVoice:    m.inviteRewardVoice    ?? 0,
    inviteeRewardMsg:     m.inviteeRewardMsg     ?? 10,
    inviteeRewardImg:     m.inviteeRewardImg     ?? 5,
    inviteeRewardVoice:   m.inviteeRewardVoice   ?? 0,
    botUsername:          m.botUsername          ?? "",
    adminPanelPassword:   m.adminPanelPassword   ?? "",
    defaultGroupPrompt1:   m.defaultGroupPrompt1   ?? "",
    defaultGroupPrompt2:   m.defaultGroupPrompt2   ?? "",
    defaultPrivatePrompt1: m.defaultPrivatePrompt1 ?? "",
    defaultPrivatePrompt2: m.defaultPrivatePrompt2 ?? "",
    // ─── external Chat API (see § 4d/handleApiChat) ───────────────
    // fallback system prompt used when a 3rd-party caller doesn't send its own
    apiDefaultPrompt:      m.apiDefaultPrompt      ?? "",
    // how many past turns (per external api user) get fed back as memory
    apiMaxHistory:         m.apiMaxHistory         ?? C.API_MAX_HISTORY,
    multiPhotoPrivate:     m.multiPhotoPrivate      ?? C.DEF_MULTI_PHOTO_PRIV,
    multiPhotoGroup:       m.multiPhotoGroup        ?? C.DEF_MULTI_PHOTO_GRP,
    // hard clamp: doesn't matter what's stored in the DB, it will never exceed the absolute cap
    // and will never go below 1
    maxMultiPhoto:         Math.min(C.HARD_CAP_MULTI_PHOTO, Math.max(1, m.maxMultiPhoto ?? C.MAX_MULTI_PHOTO)),
    // ─── new features (global defaults) ───────────────────────
    globalWebSearch:        m.globalWebSearch ?? true,          // true by default (limits still apply)
    globalImportanceScore:  m.globalImportanceScore  ?? true,   // true by default
    globalMemoryEnabled:    m.globalMemoryEnabled     ?? true,   // true by default
    globalSearchLimit:      m.globalSearchLimit       ?? C.DEF_SEARCH_LIMIT,
    globalGrpSearchLimit:   m.globalGrpSearchLimit    ?? C.DEF_GRP_SEARCH_LIMIT,
    // ─── bot language (bilingual support) ───────────────────────
    // "en" or "fa". Per-chat config can override this via chatCfg.lang.
    defaultLang:            m.defaultLang             ?? C.DEF_LANG,
    // Language the AI replies in: "auto" = match each user (default), or force "en" / "fa"
    replyLang:              ["auto","en","fa"].includes(m.replyLang) ? m.replyLang : "auto",
    // System-prompt modes the admin switched OFF (2..5; mode 1 is always on). Default [] = all on.
    disabledModes:          Array.isArray(m.disabledModes) ? m.disabledModes.map(Number).filter(x => [2,3,4,5].includes(x)) : [],
    // ─── voice/TTS generation (§ 8b VoiceGen) ────────────────────
    // ON by default (admin can switch it off in Config → Voice). New users get a small
    // voice allowance — see defaultVoiceLimit / defaultDailyVoiceLimit below.
    voiceEnabled:          m.voiceEnabled !== false,
    // ─── Mini App feature switches (all on by default) ───────────
    ...Object.fromEntries(MINI_APP_FEATURES.map(f => [f.key, m[f.key] ?? true])),
    // per-chat daily caps by chat type (0 = unlimited) — see consumeUserLimit
    dailyCaps: {
      private: { msg: Number(m.dailyCaps?.private?.msg) || 0, img: Number(m.dailyCaps?.private?.img) || 0, voice: Number(m.dailyCaps?.private?.voice) || 0 },
      group:   { msg: Number(m.dailyCaps?.group?.msg)   || 0, img: Number(m.dailyCaps?.group?.img)   || 0, voice: Number(m.dailyCaps?.group?.voice)   || 0 },
    },
    welcomeTextPrivate: typeof m.welcomeTextPrivate === "string" ? m.welcomeTextPrivate : "",
    welcomeTextGroup:   typeof m.welcomeTextGroup   === "string" ? m.welcomeTextGroup   : "",
    // master switch for every greeting (/start text, group activation text, new-member greeting)
    welcomeEnabled:     m.welcomeEnabled !== false,
    // display name users see (Mini App, greetings, how the bot introduces itself). "" = default "Niki"/"نیکی".
    botName:            typeof m.botName === "string" ? m.botName : "",
    // ── voice (TTS) engine, chosen in Config → Voice ──
    ttsProvider: m.ttsProvider === "cloudflare" ? "cloudflare" : "google",
    ttsModel:    typeof m.ttsModel === "string" && /^[A-Za-z0-9._\-]{1,80}$/.test(m.ttsModel.trim()) && m.ttsModel.trim() ? m.ttsModel.trim() : GEMINI_TTS_DEFAULT_MODEL,
    ttsVoice:    GEMINI_TTS_VOICE_NAMES.includes(m.ttsVoice) ? m.ttsVoice : GEMINI_TTS_DEFAULT_VOICE,
    ttsCharacter: VOICE_CHARACTERS.some(c => c.id === m.ttsCharacter) ? m.ttsCharacter : "",
    triggerWords: typeof m.triggerWords === "string" ? m.triggerWords.slice(0, 200) : "",
    ttsStyle:    typeof m.ttsStyle === "string" ? m.ttsStyle.replace(/[<>\u0000]/g, "").trim().slice(0, 200) : "",
    // ── Gemini Live (real-time voice conversation in the Mini App) ──
    liveEnabled: m.liveEnabled !== false,
    ttsFallback: m.ttsFallback !== false,
    ttsAutoStyle: m.ttsAutoStyle !== false,
    liveModel:   typeof m.liveModel === "string" && /^[A-Za-z0-9._\-]{1,80}$/.test(m.liveModel.trim()) && m.liveModel.trim() ? m.liveModel.trim() : GEMINI_LIVE_DEFAULT_MODEL,
    liveVoice:   GEMINI_TTS_VOICE_NAMES.includes(m.liveVoice) ? m.liveVoice : GEMINI_TTS_DEFAULT_VOICE,
    // admin-chosen default language model ("" = built-in default)
    defaultModel:       typeof m.defaultModel === "string" && /^[A-Za-z0-9._\-\/:]{1,80}$/.test(m.defaultModel.trim()) ? m.defaultModel.trim() : "",
    superIds: Array.isArray(m.superIds) ? m.superIds.map(String).filter(x => /^\d{1,15}$/.test(x)).slice(0, 30) : [],
    maintenanceMode: Boolean(m.maintenanceMode),
    maintenanceText: typeof m.maintenanceText === "string" ? m.maintenanceText : "",
    disabledPrivate: Array.isArray(m.disabledPrivate) ? m.disabledPrivate : [],
    disabledGroup:   Array.isArray(m.disabledGroup)   ? m.disabledGroup   : [],
    defaultVoiceLimit:     m.defaultVoiceLimit      ?? 5,  // new users: 5 permanent voices…
    defaultDailyVoiceLimit:m.defaultDailyVoiceLimit ?? 2,  // …plus 2 per day
    welcomeVoiceLimit:     m.welcomeVoiceLimit      ?? 0,
    defaultGroupVoiceLimit:    m.defaultGroupVoiceLimit    ?? 0,
    defaultGroupDailyVoice:    m.defaultGroupDailyVoice    ?? 0,
  };
  _extraSuperIds = new Set(_gcCache.superIds);
  _activeGeminiModel = _gcCache.defaultModel || DEFAULT_GEMINI_MODEL;
  _applyTrigger(_gcCache.botName, _gcCache.triggerWords);
  _voiceEnglishOnly = _gcCache.ttsProvider === "cloudflare";
  _voiceAutoStyle = _gcCache.ttsAutoStyle !== false;
  _gcCacheAt = Date.now(); // CF Workers: setTimeout doesn't survive across requests; use TTL check on read
  return _gcCache;
}
async function setGC(db, cfg) {
  _gcCache = null;
  const s = Object.entries(cfg).map(([k,v]) =>
    db.prepare("INSERT OR REPLACE INTO global_config(key,value) VALUES(?,?)").bind(k,JSON.stringify(v)));
  if (s.length) await db.batch(s);
}

// ══════════════════════════════════════════════════════════════
// § 4c  CHAT CONFIG + IMPORTANCE SCORING
// ══════════════════════════════════════════════════════════════
// @FILE-SPLIT → src/webhook.js, EXCEPT the history CRUD, which is
// src/memory.js instead. This section holds several things that grew
// together over time:
//   → webhook.js: getChatConfig/setChatConfig/resolveFeat,
//     consumeSearchLimit, scoreImportance, needsWebSearch, flags (F.*),
//     await-prompt state, GROUPS crud/approve/revoke, group limits, and
//     user limits (_buildUserLimits/getUserLimits + quota consumption
//     further below) — all "core per-message settings", same reasoning as
//     § 4's schema/global-config: every update touches these.
//   → memory.js: loadHistory/appendHistory/clearHistory (further below in
//     this section) — these are the actual conversation transcript, so
//     they belong with archiveMsg/long-term recall in § 4b, not here.
// Depends on: C, log(), kv, today().

// _ccCache: per-Worker in-memory cache with timestamp-based TTL (60 s).
// CF Workers don't support cross-request timers, so we use a timestamp check
// the same way _gcCache does — avoids stale config lingering indefinitely.
const _ccCache    = new Map(); // chatId -> { cfg, at }
const _CC_TTL_MS  = 60_000;

async function getChatConfig(db, chatId) {
  const cached = _ccCache.get(chatId);
  if (cached && (Date.now() - cached.at) < _CC_TTL_MS) return cached.cfg;
  const r = await db.prepare(
    `SELECT web_search,importance_scoring,memory_enabled,search_limit,lang,extra FROM chat_config WHERE chat_id=?`
  ).bind(chatId).first();
  const cfg = {
    webSearch:         r?.web_search         ?? null,
    importanceScoring: r?.importance_scoring ?? null,
    memoryEnabled:     r?.memory_enabled     ?? null,
    searchLimit:       r?.search_limit       ?? null,
    lang:              r?.lang               ?? null, // null = follow global defaultLang
    extra: (() => { try { return JSON.parse(r?.extra||"{}"); } catch { return {}; } })(),
  };
  _ccCache.set(chatId, { cfg, at: Date.now() });
  return cfg;
}

async function setChatConfig(db, chatId, patch) {
  _ccCache.delete(chatId);
  const fields = [], vals = [];
  if ("webSearch"         in patch) { fields.push("web_search=?");         vals.push(patch.webSearch===null?null:patch.webSearch?1:0); }
  if ("importanceScoring" in patch) { fields.push("importance_scoring=?"); vals.push(patch.importanceScoring===null?null:patch.importanceScoring?1:0); }
  if ("memoryEnabled"     in patch) { fields.push("memory_enabled=?");     vals.push(patch.memoryEnabled===null?null:patch.memoryEnabled?1:0); }
  if ("searchLimit"       in patch) { fields.push("search_limit=?");       vals.push(patch.searchLimit===null?null:(Number.isFinite(Number(patch.searchLimit))?Number(patch.searchLimit):10)); }
  if ("lang"              in patch) { fields.push("lang=?");               vals.push(patch.lang===null?null:(C.SUPPORTED_LANGS.includes(patch.lang)?patch.lang:null)); }
  if ("extra"             in patch) { fields.push("extra=?");              vals.push(JSON.stringify(patch.extra)); }
  if (!fields.length) return;
  await db.prepare(`INSERT INTO chat_config(chat_id) VALUES(?) ON CONFLICT(chat_id) DO NOTHING`).bind(chatId).run();
  await db.prepare(`UPDATE chat_config SET ${fields.join(",")} WHERE chat_id=?`).bind(...vals,chatId).run();
}

/** null = follow global, true/false = override */
function resolveFeat(perChat, globalVal) { return perChat === null ? globalVal : Boolean(perChat); }

// ─── Web Search Usage (per user/group per day) ────────────────
// ─── _searchUsageKey — build a consistent daily key for search usage ──
function _searchUsageKey(chatId, userId, isGroup, day) {
  return isGroup ? `grp_${chatId}_${day}` : `usr_${userId}_${day}`;
}

async function consumeSearchLimit(db, gc, chatCfg, chatId, userId, isGroup) {
  const day   = today();
  const key   = _searchUsageKey(chatId, userId, isGroup, day);
  const limit = isGroup
    ? (chatCfg.searchLimit ?? gc.globalGrpSearchLimit)
    : (chatCfg.searchLimit ?? gc.globalSearchLimit);
  if (limit <= 0) return { allowed: true }; // 0 = unlimited

  // ── atomic: ensure today's row exists, then increment only when under limit ──
  // This is the same pattern as consumeUserLimit / consumeGroupLimit —
  // two concurrent requests can never both consume the last remaining slot.
  await db.prepare(`
    INSERT INTO search_usage(id,chat_id,user_id,day,count) VALUES(?,?,?,?,0)
    ON CONFLICT(id) DO NOTHING
  `).bind(key, chatId||null, userId||null, day).run();

  const upd = await db.prepare(`
    UPDATE search_usage SET count=count+1 WHERE id=? AND count<?
  `).bind(key, limit).run();

  if ((upd.meta?.changes ?? 0) > 0) {
    // read back the new count for reporting (best-effort, not used for enforcement)
    const row = await db.prepare(`SELECT count FROM search_usage WHERE id=?`).bind(key).first();
    return { allowed: true, used: row?.count ?? 1, limit };
  }
  const row = await db.prepare(`SELECT count FROM search_usage WHERE id=?`).bind(key).first();
  return { allowed: false, used: row?.count ?? limit, limit };
}

// ─── Importance Scoring ───────────────────────────────────────
const IMP_PATTERNS = [
  [/(?:اسمم|نامم|بهم بگو|صدام کن|من .{0,10} هستم)/i,  9],
  [/(?:متولد|تولدم|زادروز|سالگرد)/i,                    8],
  [/(?:شغلم|کارم|دانشجو|دانشگاه|مدرسه)/i,              8],
  [/(?:زندگی می‌?کنم|ساکنم|شهرم|کشورم)/i,              8],
  [/(?:ازدواج|نامزد|همسر|شوهر|خانواده)/i,               7],
  [/(?:یادت باشه|فراموش نکن|مهمه که)/i,                 9],
  [/(?:دوست دارم|دوست ندارم|علاقه|متنفرم)/i,            7],
  [/(?:چطور|چگونه|آموزش|راهنما)/i,                      5],
];

function scoreImportance(text, mediaType=null) {
  let score = 1;
  const t = String(text||"");
  const wc = t.trim().split(/\s+/).length;
  if (wc > 30) score += 2; else if (wc > 10) score += 1;
  for (const [pat, pts] of IMP_PATTERNS) { if (pat.test(t)) { score += pts; break; } }
  if (mediaType === "image") score += 4;
  else if (mediaType === "audio" || mediaType === "video") score += 3;
  return Math.min(score, 10);
}

// ─── needsWebSearch — smart detection of search intent ──────────────
function needsWebSearch(text) {
  if (!text?.trim()) return false;
  return C.WEB_SEARCH_TRIGGERS.test(text);
}

// ─── Flags ─────────────────────────────────────────────────────
async function getFlag(env, db, scope) {
  const c = await kv.getFlag(env, scope);
  if (c !== null) return c;
  const r = await db.prepare("SELECT value FROM flags WHERE scope=?").bind(scope).first();
  const v = r?.value === "1";
  await kv.setFlag(env, scope, v);
  return v;
}
async function setFlag(env, db, scope, on) {
  await db.prepare("INSERT OR REPLACE INTO flags(scope,value) VALUES(?,?)").bind(scope,on?"1":"0").run();
  await kv.setFlag(env, scope, on);
}
async function toggleFlag(env, db, scope) {
  const cur = await getFlag(env, db, scope);
  await setFlag(env, db, scope, !cur);
  return !cur;
}

// ─── Await-prompt state (Mode 3) ───────────────────────────────────────
// Distinct from the boolean flags above: this needs to remember an actual
// string ("group" / "private" / "custom"), not just on/off. It used to be
// stored via setFlag/getFlag, but those coerce whatever's passed into
// "1"/"0" — so the chosen scope ("group"/"private") was always silently
// discarded and every Mode 3 prompt landed as a plain custom prompt,
// regardless of what the admin actually selected. Uses its own KV prefix
// (awaitp:) so it can't collide with the boolean flag cache.
async function setAwaitPrompt(env, db, chatId, userId, mode) {
  const scope = `await_prompt_${chatId}_${userId}`;
  await db.prepare("INSERT OR REPLACE INTO flags(scope,value) VALUES(?,?)").bind(scope, mode).run();
  await kv.set(env, `awaitp:${scope}`, mode);
}
async function getAwaitPrompt(env, db, chatId, userId) {
  const scope = `await_prompt_${chatId}_${userId}`;
  const cached = await kv.get(env, `awaitp:${scope}`);
  if (cached !== null) return cached || null;
  const r = await db.prepare("SELECT value FROM flags WHERE scope=?").bind(scope).first();
  await kv.set(env, `awaitp:${scope}`, r?.value || "");
  return r?.value || null;
}
async function clearAwaitPrompt(env, db, chatId, userId) {
  const scope = `await_prompt_${chatId}_${userId}`;
  await db.prepare("DELETE FROM flags WHERE scope=?").bind(scope).run();
  await kv.del(env, `awaitp:${scope}`);
}

const F = {
  silent:      (env,db,id)    => getFlag(env,db,`silent_${id}`),
  alwaysOn:    (env,db,id)    => getFlag(env,db,`alwayson_${id}`),
  lockdown:    (env,db,id)    => getFlag(env,db,`lockdown_${id}`),
  muted:       (env,db,cid,u) => getFlag(env,db,`muted_${cid}_${norm(u)}`),
  banned:      (env,db,cid,u) => getFlag(env,db,`banned_${cid}_${norm(u)}`),

  toggleSilent:      (env,db,id)       => toggleFlag(env,db,`silent_${id}`),
  toggleAlwaysOn:    (env,db,id)       => toggleFlag(env,db,`alwayson_${id}`),
  toggleLockdown:    (env,db,id)       => toggleFlag(env,db,`lockdown_${id}`),
  enableAlwaysOn:    (env,db,id)       => setFlag(env,db,`alwayson_${id}`,true),
  setAlwaysOn:       (env,db,id,on)    => setFlag(env,db,`alwayson_${id}`,on),
  setMuted:          (env,db,cid,u,on) => setFlag(env,db,`muted_${cid}_${norm(u)}`,on),
  setBanned:         (env,db,cid,u,on) => setFlag(env,db,`banned_${cid}_${norm(u)}`,on),
};

// ─── Groups ────────────────────────────────────────────────────
/**
 * isGroupApproved — gatekeeper called on every group message.
 *
 * As a side effect, stamps `last_activity` for approved groups so the
 * broadcast engine's recipient priority (most recently active first, see
 * fetchBroadcastPage in § 4e) stays accurate. Private chats short-circuit
 * before touching the database — their activity is stamped separately by
 * registerUser().
 *
 * @param {object} env
 * @param {object} db
 * @param {number} chatId
 * @returns {Promise<boolean>} whether this group is approved
 */
async function isGroupApproved(env, db, chatId) {
  if (chatId > 0) return true;
  const r = await db.prepare("SELECT approved FROM groups WHERE chat_id=?").bind(chatId).first();
  if (r?.approved === 1) {
    // best-effort — never block the request on this
    db.prepare("UPDATE groups SET last_activity=? WHERE chat_id=?")
      .bind(new Date().toISOString(), chatId).run().catch(() => {});
    return true;
  }
  return false;
}

async function approveGroup(env, db, chatId, groupName, approvedBy) {
  const gc = await getGC(db);
  const ex = await db.prepare("SELECT msg_limit,img_limit,daily_msg_limit,daily_img_limit,voice_limit,daily_voice_limit FROM groups WHERE chat_id=?").bind(chatId).first();
  const ml = ex?.msg_limit ?? gc.defaultGroupMsgLimit;
  const il = ex?.img_limit ?? gc.defaultGroupImgLimit;
  const dm = ex?.daily_msg_limit ?? gc.defaultGroupDailyMsg;
  const di = ex?.daily_img_limit ?? gc.defaultGroupDailyImg;
  const vl = ex?.voice_limit ?? gc.defaultGroupVoiceLimit;
  const dv = ex?.daily_voice_limit ?? gc.defaultGroupDailyVoice;
  await db.prepare(`
    INSERT INTO groups(chat_id,group_name,approved,approved_by,approved_at,pending,
      msg_limit,img_limit,remaining_msg,remaining_img,daily_msg_limit,daily_img_limit,total_msg,total_img,
      voice_limit,remaining_voice,daily_voice_limit,total_voice)
    VALUES(?,?,1,?,?,0,?,?,?,?,?,?,0,0,?,?,?,0)
    ON CONFLICT(chat_id) DO UPDATE SET
      approved=1,approved_by=excluded.approved_by,approved_at=excluded.approved_at,
      group_name=excluded.group_name,pending=0,
      remaining_msg=COALESCE(groups.remaining_msg,excluded.remaining_msg),
      remaining_img=COALESCE(groups.remaining_img,excluded.remaining_img),
      remaining_voice=COALESCE(groups.remaining_voice,excluded.remaining_voice)
  `).bind(chatId,groupName||String(chatId),approvedBy,new Date().toISOString(),ml,il,ml,il,dm,di,vl,vl,dv).run();
  await F.enableAlwaysOn(env,db,chatId);
}

async function revokeGroup(env, db, chatId) {
  await db.prepare("UPDATE groups SET approved=0 WHERE chat_id=?").bind(chatId).run();
}

async function addPendingGroup(db, chatId, groupName, reqBy, reqById) {
  const gc = await getGC(db);
  await db.prepare(`
    INSERT INTO groups(chat_id,group_name,approved,pending,requested_by,requested_by_user_id,requested_at,
      msg_limit,img_limit,remaining_msg,remaining_img,daily_msg_limit,daily_img_limit,
      voice_limit,remaining_voice,daily_voice_limit)
    VALUES(?,?,0,1,?,?,?,?,?,?,?,?,?,?,?,?)
    ON CONFLICT(chat_id) DO UPDATE SET
      group_name=excluded.group_name,pending=1,
      requested_by=excluded.requested_by,
      requested_by_user_id=excluded.requested_by_user_id,
      requested_at=excluded.requested_at
  `).bind(
    chatId,groupName||String(chatId),reqBy,reqById,new Date().toISOString(),
    gc.defaultGroupMsgLimit,gc.defaultGroupImgLimit,
    gc.defaultGroupMsgLimit,gc.defaultGroupImgLimit,
    gc.defaultGroupDailyMsg,gc.defaultGroupDailyImg,
    gc.defaultGroupVoiceLimit,gc.defaultGroupVoiceLimit,gc.defaultGroupDailyVoice
  ).run();
}

async function resetGroupRemaining(env, db, chatId) {
  await db.prepare("UPDATE groups SET remaining_msg=msg_limit,remaining_img=img_limit WHERE chat_id=?").bind(chatId).run();
}

// ─── _recordGroupUsage — increment daily usage counter for a group ──
async function _recordGroupUsage(db, chatId, day, ucol) {
  await db.prepare(
    `INSERT INTO group_usage(chat_id,day,${ucol}) VALUES(?,?,1)
     ON CONFLICT(chat_id,day) DO UPDATE SET ${ucol}=${ucol}+1`
  ).bind(chatId, day).run();
}

// ─── _consumePermanentGroupQuota — atomic decrement of permanent balance ──
async function _consumePermanentGroupQuota(db, chatId, day, col, tcol, ucol) {
  const res = await db.prepare(
    `UPDATE groups SET ${col}=MAX(0,${col}-1),${tcol}=${tcol}+1 WHERE chat_id=? AND ${col}>0`
  ).bind(chatId).run();
  if ((res.meta?.changes ?? 0) > 0) {
    _recordGroupUsage(db, chatId, day, ucol).catch(()=>{}); // stats-only — don't block the reply on it
    return true;
  }
  return false;
}

// ─── _consumeDailyGroupQuota — atomic check+increment of daily quota ──
async function _consumeDailyGroupQuota(db, chatId, day, dcol, tcol, ucol) {
  const row = await db.prepare(`SELECT ${dcol} FROM groups WHERE chat_id=?`).bind(chatId).first();
  if (!row) return { allowed: true }; // group not registered = no restriction

  const dailyLimit = row[dcol] ?? 0;
  if (dailyLimit <= 0) return { allowed: false, reason: "total" };

  // one round-trip instead of two — see _consumeDailyUserQuota for why this is safe
  const upd = await db.prepare(
    `INSERT INTO group_usage(chat_id,day,${ucol}) VALUES(?,?,1)
     ON CONFLICT(chat_id,day) DO UPDATE SET ${ucol}=${ucol}+1 WHERE ${ucol}<?`
  ).bind(chatId, day, dailyLimit).run();

  if ((upd.meta?.changes ?? 0) > 0) {
    // lifetime "total" counter is a display stat only — don't block on it
    db.prepare(`UPDATE groups SET ${tcol}=${tcol}+1 WHERE chat_id=?`).bind(chatId).run().catch(()=>{});
    return { allowed: true };
  }
  return { allowed: false, reason: "daily" };
}

// ─── Group Limits ──────────────────────────────────────────────
async function consumeGroupLimit(env, db, chatId, type) {
  if (chatId > 0) return { allowed: true };
  const day  = today();
  const col  = type === "img" ? "remaining_img"   : type === "voice" ? "remaining_voice"   : "remaining_msg";
  const dcol = type === "img" ? "daily_img_limit" : type === "voice" ? "daily_voice_limit" : "daily_msg_limit";
  const tcol = type === "img" ? "total_img"       : type === "voice" ? "total_voice"       : "total_msg";
  const ucol = type === "img" ? "img"             : type === "voice" ? "voice"             : "msg";

  // step 0: time-limited package bundles take priority (soonest-expiry first)
  // Voice isn't part of the packages feature (yet).
  if (type !== "voice") {
    const pkg = await consumeChatPackages(db, chatId, type);
    if (pkg.allowed) {
      _recordGroupUsage(db, chatId, day, ucol).catch(()=>{}); // stats-only — don't block the reply on it
      return { allowed: true, source: "package" };
    }
  }

  // step 1: permanent balance
  if (await _consumePermanentGroupQuota(db, chatId, day, col, tcol, ucol)) {
    return { allowed: true };
  }

  // step 2: daily quota
  return _consumeDailyGroupQuota(db, chatId, day, dcol, tcol, ucol);
}

// ─── User Limits ───────────────────────────────────────────────
// Manages each user's daily/total message & image quota, with a short-TTL KV cache
// on top of D1. consumeLimit must stay atomic (a single UPDATE, not a separate
// read-then-write) otherwise concurrent load can corrupt the quota count.
// ─── _buildUserLimits — map a DB row + gc defaults to the limits object ──
function _buildUserLimits(row, gc) {
  if (row) return {
    msgLimit:      row.msg_limit       ?? gc.defaultMsgLimit,
    imgLimit:      row.img_limit       ?? gc.defaultImgLimit,
    voiceLimit:    row.voice_limit     ?? gc.defaultVoiceLimit,
    dailyMsgLimit: row.daily_msg_limit ?? gc.defaultDailyMsgLimit,
    dailyImgLimit: row.daily_img_limit ?? gc.defaultDailyImgLimit,
    dailyVoiceLimit: row.daily_voice_limit ?? gc.defaultDailyVoiceLimit,
    remainingMsg:  row.remaining_msg   ?? (row.msg_limit ?? gc.defaultMsgLimit),
    remainingImg:  row.remaining_img   ?? (row.img_limit ?? gc.defaultImgLimit),
    remainingVoice: row.remaining_voice ?? (row.voice_limit ?? gc.defaultVoiceLimit),
    bonusMsg:      row.bonus_msg       ?? 0,
    bonusImg:      row.bonus_img       ?? 0,
    bonusVoice:    row.bonus_voice     ?? 0,
    inviteCount:   row.invite_count    ?? 0,
    totalMsg:      row.total_msg       ?? 0,
    totalImg:      row.total_img       ?? 0,
    totalVoice:    row.total_voice     ?? 0,
    username:      row.username        ?? null,
    displayName:   row.display_name    ?? null,
    notes:         row.notes           ?? "",
    welcomed:      row.welcomed        ?? 0,
    inviteCode:    row.invite_code     ?? null,
    referredBy:    row.referred_by     ?? null,
    createdAt:     row.created_at      ?? new Date().toISOString(),
  };
  return {
    msgLimit: gc.defaultMsgLimit, imgLimit: gc.defaultImgLimit, voiceLimit: gc.defaultVoiceLimit,
    dailyMsgLimit: gc.defaultDailyMsgLimit, dailyImgLimit: gc.defaultDailyImgLimit,
    dailyVoiceLimit: gc.defaultDailyVoiceLimit,
    remainingMsg: gc.defaultMsgLimit, remainingImg: gc.defaultImgLimit, remainingVoice: gc.defaultVoiceLimit,
    bonusMsg:0, bonusImg:0, bonusVoice:0, inviteCount:0, totalMsg:0, totalImg:0, totalVoice:0,
    username:null, displayName:null, notes:"", welcomed:0,
    inviteCode:null, referredBy:null, createdAt:new Date().toISOString(),
  };
}

async function getUserLimits(env, db, userId) {
  const cached = await kv.getLimits(env, userId);
  if (cached) return cached;
  const [gc, row] = await Promise.all([
    getGC(db),
    db.prepare("SELECT * FROM users WHERE user_id=?").bind(userId).first(),
  ]);
  const lim = _buildUserLimits(row, gc);
  await kv.setLimits(env, userId, lim);
  return lim;
}

/**
 * registerUser — upserts the inbound sender and stamps `last_activity`.
 *
 * Runs on *every* incoming message, so this is a single UPSERT (not a
 * separate INSERT OR IGNORE + UPDATE) to save a round-trip to D1.
 *
 * `last_activity` is the sort key the broadcast engine uses to prioritize
 * delivery (see fetchBroadcastPage in § 4e) — recently active users always
 * receive a broadcast before inactive ones, without ever physically
 * reordering the `users` table.
 *
 * @param {object} env    - Worker environment bindings
 * @param {object} db     - D1 database handle
 * @param {number} userId - Telegram user id
 * @param {string} username - Telegram username or display name
 * @returns {Promise<void>}
 */
async function registerUser(env, db, userId, username) {
  const gc  = await getGC(db);
  const now = new Date().toISOString();
  await db.prepare(`
    INSERT INTO users(user_id,username,msg_limit,img_limit,voice_limit,
      daily_msg_limit,daily_img_limit,daily_voice_limit,remaining_msg,remaining_img,remaining_voice,
      bonus_msg,bonus_img,bonus_voice,invite_count,total_msg,total_img,total_voice,notes,
      created_at,welcomed,last_activity)
    VALUES(?,?,?,?,?,?,?,?,?,?,?,0,0,0,0,0,0,0,'',?,0,?)
    ON CONFLICT(user_id) DO UPDATE SET
      username=excluded.username,
      last_activity=excluded.last_activity
  `).bind(
    userId, norm(username),
    gc.defaultMsgLimit, gc.defaultImgLimit, gc.defaultVoiceLimit,
    gc.defaultDailyMsgLimit, gc.defaultDailyImgLimit, gc.defaultDailyVoiceLimit,
    gc.defaultMsgLimit, gc.defaultImgLimit, gc.defaultVoiceLimit,
    now, now,
  ).run();
  await kv.delLimits(env, userId);
}

async function setDisplayName(env, db, userId, name) {
  await db.prepare("UPDATE users SET display_name=? WHERE user_id=?").bind(name.trim(), userId).run();
  await kv.delLimits(env, userId);
}

async function getDisplayName(db, userId) {
  const r = await db.prepare("SELECT display_name,username FROM users WHERE user_id=?").bind(userId).first();
  return r?.display_name || r?.username || null;
}

// ─── _recordUserUsage — increment per-user daily usage counter ───
async function _recordUserUsage(db, userId, day, ucol) {
  await db.prepare(
    `INSERT INTO usage(user_id,day,${ucol}) VALUES(?,?,1)
     ON CONFLICT(user_id,day) DO UPDATE SET ${ucol}=${ucol}+1`
  ).bind(userId, day).run();
}

// ─── _consumePermanentUserQuota — atomic decrement of permanent user balance ──
async function _consumePermanentUserQuota(db, env, userId, day, cr, ct, ucol) {
  const res = await db.prepare(
    `UPDATE users SET ${cr}=MAX(0,${cr}-1),${ct}=${ct}+1 WHERE user_id=? AND ${cr}>0`
  ).bind(userId).run();
  if ((res.meta?.changes ?? 0) > 0) {
    _recordUserUsage(db, userId, day, ucol).catch(()=>{}); // stats-only — don't block the reply on it
    await kv.delLimits(env, userId);
    return true;
  }
  return false;
}

// ─── _consumeDailyUserQuota — atomic check+increment of daily user quota ──
async function _consumeDailyUserQuota(db, env, userId, day, cd, ct, ucol) {
  const row = await db.prepare(`SELECT ${cd} FROM users WHERE user_id=?`).bind(userId).first();
  const dailyLimit = row?.[cd] ?? 0;
  if (dailyLimit <= 0) return { allowed: false, reason: "total" };

  // One round-trip instead of two: insert today's row at 1 if this is the
  // first use today (the ON CONFLICT WHERE guard doesn't apply to a fresh
  // insert, which is safe since dailyLimit>0 was already confirmed above);
  // otherwise atomically increment only while still under the limit.
  const upd = await db.prepare(
    `INSERT INTO usage(user_id,day,${ucol}) VALUES(?,?,1)
     ON CONFLICT(user_id,day) DO UPDATE SET ${ucol}=${ucol}+1 WHERE ${ucol}<?`
  ).bind(userId, day, dailyLimit).run();

  if ((upd.meta?.changes ?? 0) > 0) {
    // lifetime "total" counter is a display stat only, not gating — don't
    // make the reply wait on it
    db.prepare(`UPDATE users SET ${ct}=${ct}+1 WHERE user_id=?`).bind(userId).run().catch(()=>{});
    await kv.delLimits(env, userId);
    return { allowed: true, source: "daily" };
  }
  return { allowed: false, reason: "daily" };
}

async function consumeUserLimit(env, db, userId, username, type, chatId=null) {
  // Admin-panel daily cap per chat (private chat / each group), by feature.
  if (!isSuperId(userId)) {
    const capKind = type === "img" ? "img" : type === "voice" ? "voice" : "msg";
    const capChat = chatId ?? userId;
    let capLimit = 0;
    try { capLimit = (await getGC(db)).dailyCaps?.[capChat < 0 ? "group" : "private"]?.[capKind] || 0; } catch {}
    if (capLimit > 0) {
      const day = today();
      const row = await db.prepare("SELECT n FROM chat_caps WHERE day=? AND chat_id=? AND kind=?").bind(day, capChat, capKind).first().catch(()=>null);
      if ((row?.n || 0) >= capLimit) return { allowed: false, reason: "cap" };
      const res = await _consumeUserLimitInner(env, db, userId, username, type, chatId);
      if (res.allowed) {
        await db.prepare("INSERT INTO chat_caps(day,chat_id,kind,n) VALUES(?,?,?,1) ON CONFLICT(day,chat_id,kind) DO UPDATE SET n=n+1").bind(day, capChat, capKind).run().catch(()=>{});
      }
      return res;
    }
  }
  return _consumeUserLimitInner(env, db, userId, username, type, chatId);
}
async function _consumeUserLimitInner(env, db, userId, username, type, chatId=null) {
  if (isSuperId(userId)) return { allowed: true, remaining: 9999 };

  const cr   = type==="img" ? "remaining_img"   : type==="voice" ? "remaining_voice"   : "remaining_msg";
  const ct   = type==="img" ? "total_img"       : type==="voice" ? "total_voice"       : "total_msg";
  const cd   = type==="img" ? "daily_img_limit" : type==="voice" ? "daily_voice_limit" : "daily_msg_limit";
  const ucol = type==="img" ? "img"             : type==="voice" ? "voice"             : "msg";
  const day  = today();

  // step 0: time-limited package bundles (private chat_id === user_id in Telegram)
  // Voice isn't part of the packages feature (yet) — skip straight to steps 1/2.
  if (type !== "voice") {
    const pkgChatId = chatId ?? userId;
    const pkg = await consumeChatPackages(db, pkgChatId, type);
    if (pkg.allowed) {
      _recordUserUsage(db, userId, day, ucol).catch(()=>{}); // stats-only — don't block the reply on it
      return { allowed: true, source: "package" };
    }
  }

  // step 1: permanent balance
  if (await _consumePermanentUserQuota(db, env, userId, day, cr, ct, ucol)) {
    return { allowed: true, source: "permanent" };
  }

  // step 2: daily quota
  return _consumeDailyUserQuota(db, env, userId, day, cd, ct, ucol);
}

async function applyWelcomeBonus(env, db, userId) {
  const row = await db.prepare("SELECT welcomed FROM users WHERE user_id=?").bind(userId).first();
  if (row?.welcomed) return false;
  const gc = await getGC(db);
  if ((gc.disabledPrivate || []).includes("feature:welcomereward")) return false;
  if (gc.welcomeMsgLimit > 0 || gc.welcomeImgLimit > 0 || gc.welcomeVoiceLimit > 0) {
    await db.prepare(`
      UPDATE users SET bonus_msg=bonus_msg+?,bonus_img=bonus_img+?,bonus_voice=bonus_voice+?,
        remaining_msg=remaining_msg+?,remaining_img=remaining_img+?,remaining_voice=remaining_voice+?,welcomed=1
      WHERE user_id=?`
    ).bind(gc.welcomeMsgLimit,gc.welcomeImgLimit,gc.welcomeVoiceLimit,gc.welcomeMsgLimit,gc.welcomeImgLimit,gc.welcomeVoiceLimit,userId).run();
  } else {
    await db.prepare("UPDATE users SET welcomed=1 WHERE user_id=?").bind(userId).run();
  }
  await kv.delLimits(env, userId);
  return true;
}

// ─── Admins ─────────────────────────────────────────────────────
async function getAdmins(db, cid) {
  const r = await db.prepare("SELECT username FROM admins WHERE chat_id=? AND is_leader=0").bind(cid).all();
  return (r.results||[]).map(x=>x.username);
}
async function getLeader(db, cid) {
  const r = await db.prepare("SELECT username FROM admins WHERE chat_id=? AND is_leader=1").bind(cid).first();
  return r?.username||null;
}
async function saveLeader(db, cid, username) {
  const u = norm(username);
  await db.batch([
    db.prepare("UPDATE admins SET is_leader=0 WHERE chat_id=?").bind(cid),
    db.prepare("INSERT INTO admins(chat_id,username,is_leader) VALUES(?,?,1) ON CONFLICT(chat_id,username) DO UPDATE SET is_leader=1").bind(cid,u),
  ]);
}
async function addAdmin(db, cid, username) {
  const u = norm(username);
  const ex = await db.prepare("SELECT username FROM admins WHERE chat_id=? AND username=?").bind(cid,u).first();
  if (ex) return false;
  await db.prepare("INSERT OR IGNORE INTO admins(chat_id,username,is_leader) VALUES(?,?,0)").bind(cid,u).run();
  return true;
}
async function removeAdmin(db, cid, username) {
  const u = norm(username);
  const ex = await db.prepare("SELECT username FROM admins WHERE chat_id=? AND username=? AND is_leader=0").bind(cid,u).first();
  if (!ex) return false;
  await db.prepare("DELETE FROM admins WHERE chat_id=? AND username=? AND is_leader=0").bind(cid,u).run();
  return true;
}

// ─── History ────────────────────────────────────────────────────
// @FILE-SPLIT → src/memory.js (not webhook.js — see the § 4c section note
// above for why this one function group is the exception).
async function loadHistory(db, cid) {
  const r = await db.prepare(`
    SELECT role,username,content,media_type,msg_id,created_at
    FROM history WHERE chat_id=? ORDER BY id DESC LIMIT ?
  `).bind(cid, C.MAX_HISTORY*3).all();
  return (r.results||[]).reverse().map(row=>({
    user:row.role==="model"?"AI":row.username,
    text:row.content, mediaType:row.media_type,
    msgId:row.msg_id, ts:row.created_at,
  }));
}
async function appendHistory(db, cid, entry) {
  const role = entry.user==="AI"?"model":"user";
  await db.batch([
    db.prepare(`INSERT INTO history(chat_id,role,username,content,media_type,msg_id,created_at) VALUES(?,?,?,?,?,?,?)`
    ).bind(cid,role,entry.user,entry.text,entry.mediaType||null,entry.msgId||null,entry.ts||new Date().toISOString()),
    db.prepare(`DELETE FROM history WHERE chat_id=? AND id NOT IN(SELECT id FROM history WHERE chat_id=? ORDER BY id DESC LIMIT ?)`
    ).bind(cid,cid,C.MAX_HISTORY*3),
  ]);
}
async function clearHistory(db, cid) {
  await db.prepare("DELETE FROM history WHERE chat_id=?").bind(cid).run();
}

// ─── bulkDeleteMessages — shared engine behind delete_last_messages and
// cleanup_chat (model function calls, see § 1 tool declarations + § 14
// dispatch). Pulls the most recent `limit` tracked messages for this chat,
// tries to delete each one for real on Telegram, then always drops them
// from history/archive regardless of whether the Telegram-side delete
// succeeded (an old message outside Telegram's deletable window still
// shouldn't linger in the bot's own memory). ─────────────────────────────
async function bulkDeleteMessages(env, db, chatId, limit, excludeMsgId=null) {
  limit = Math.max(1, Math.min(Number(limit)||1, C.MAX_BULK_DELETE));
  const rows = await db.prepare(
    `SELECT id,msg_id FROM history WHERE chat_id=? AND msg_id IS NOT NULL AND msg_id!=? ORDER BY id DESC LIMIT ?`
  ).bind(chatId, excludeMsgId||0, limit).all();
  const list = rows.results || [];
  let deleted = 0;
  for (const row of list) {
    if (await deleteMsg(env, chatId, row.msg_id)) deleted++;
    // 60ms (~16/sec) was well past Telegram's per-chat flood limit and could
    // trigger a 429 penalty that then blocked the bot's *next* reply in this
    // same chat too. ~350ms (~3/sec) stays comfortably under it.
    await sleep(350);
  }
  if (list.length) {
    const ids = list.map(r=>r.id);
    await db.batch([
      db.prepare(`DELETE FROM history WHERE id IN (${ids.map(()=>"?").join(",")})`).bind(...ids),
      db.prepare(`DELETE FROM archive WHERE chat_id=? AND msg_id IN (${list.map(()=>"?").join(",")})`).bind(chatId, ...list.map(r=>r.msg_id)),
    ]);
  }
  return { attempted: list.length, deleted };
}

// ═══════════════════════════════════════════════════════════════
// § 4g  PACKAGES  (time-limited bundles — "internet package" style)
// ═══════════════════════════════════════════════════════════════
// @FILE-SPLIT → src/admin.js (packages are created/managed from the admin
// panel, grouped there with api-keys/broadcast/external-chat-api as
// "admin-managed features")
// Fully self-contained CRUD + consumption engine for the packages/
// chat_packages tables. No external deps beyond `db`.
// Two layers:
//  1. packages       — reusable templates an admin defines once (name, msg/img
//                       volume, duration in days, optional price note).
//  2. chat_packages   — actual bundles running on a specific chat (private or
//                       group). Each one is its own self-contained quota: it
//                       carries msg_remaining/img_remaining AND its own
//                       expires_at. Whichever hits zero first ends it — exactly
//                       like a mobile data package. Editing/deleting a template
//                       afterwards never touches bundles already activated from it,
//                       because name/amounts are snapshotted onto the chat_packages row.
//
// Consumption order (see consumeChatPackages below): among all ACTIVE,
// NOT-YET-EXPIRED bundles for a chat, the one expiring soonest is drained
// first. Only once every bundle is either expired or fully drained does the
// caller fall back to the chat's permanent/daily limit (existing behavior,
// unchanged).

// ─── Templates ───────────────────────────────────────────────────
async function createPackageTemplate(db, { nameFa, nameEn, msgAmount, imgAmount, durationDays, priceNote, starPrice }) {
  const r = await db.prepare(`
    INSERT INTO packages(name_fa,name_en,msg_amount,img_amount,duration_days,price_note,star_price,active,created_at)
    VALUES(?,?,?,?,?,?,?,1,?)
  `).bind(
    String(nameFa||"").trim(), String(nameEn||"").trim(),
    Math.max(0, Number(msgAmount)||0), Math.max(0, Number(imgAmount)||0),
    Math.max(1, Number(durationDays)||30), String(priceNote||"").trim(),
    Math.max(0, Number(starPrice)||0),
    new Date().toISOString()
  ).run();
  return r.meta?.last_row_id;
}
async function updatePackageTemplate(db, id, { nameFa, nameEn, msgAmount, imgAmount, durationDays, priceNote, starPrice, active }) {
  await db.prepare(`
    UPDATE packages SET name_fa=?,name_en=?,msg_amount=?,img_amount=?,duration_days=?,price_note=?,star_price=?,active=?
    WHERE id=?
  `).bind(
    String(nameFa||"").trim(), String(nameEn||"").trim(),
    Math.max(0, Number(msgAmount)||0), Math.max(0, Number(imgAmount)||0),
    Math.max(1, Number(durationDays)||30), String(priceNote||"").trim(),
    Math.max(0, Number(starPrice)||0),
    active?1:0, Number(id)
  ).run();
}
async function deletePackageTemplate(db, id) {
  // templates are only definitions — deleting one never touches bundles
  // already activated from it (chat_packages rows are independent snapshots).
  await db.prepare("DELETE FROM packages WHERE id=?").bind(Number(id)).run();
}
async function listPackageTemplates(db, activeOnly=false) {
  const q = activeOnly ? "SELECT * FROM packages WHERE active=1 ORDER BY id DESC" : "SELECT * FROM packages ORDER BY id DESC";
  const r = await db.prepare(q).all();
  return r.results||[];
}
async function getPackageTemplate(db, id) {
  return db.prepare("SELECT * FROM packages WHERE id=?").bind(Number(id)).first();
}

// ─── Activation (template-based or fully custom) on a specific chat ──────
async function activatePackageOnChat(db, chatId, { packageId=null, nameFa, nameEn, msgAmount, imgAmount, durationDays, activatedBy="" }) {
  const now = new Date();
  const expires = new Date(now.getTime() + Math.max(1, Number(durationDays)||30)*86400000);
  const r = await db.prepare(`
    INSERT INTO chat_packages(chat_id,package_id,name_fa,name_en,msg_total,img_total,msg_remaining,img_remaining,started_at,expires_at,active,activated_by,created_at)
    VALUES(?,?,?,?,?,?,?,?,?,?,1,?,?)
  `).bind(
    Number(chatId), packageId?Number(packageId):null,
    String(nameFa||"").trim(), String(nameEn||"").trim(),
    Math.max(0, Number(msgAmount)||0), Math.max(0, Number(imgAmount)||0),
    Math.max(0, Number(msgAmount)||0), Math.max(0, Number(imgAmount)||0),
    now.toISOString(), expires.toISOString(), String(activatedBy||""), now.toISOString()
  ).run();
  return r.meta?.last_row_id;
}
async function activateTemplateOnChat(db, chatId, templateId, activatedBy="") {
  const tpl = await getPackageTemplate(db, templateId);
  if (!tpl) return null;
  return activatePackageOnChat(db, chatId, {
    packageId: tpl.id, nameFa: tpl.name_fa, nameEn: tpl.name_en,
    msgAmount: tpl.msg_amount, imgAmount: tpl.img_amount, durationDays: tpl.duration_days,
    activatedBy,
  });
}

// ─── Editing / removing an already-active bundle (admin has full control) ──
async function editChatPackage(db, id, { msgRemaining, imgRemaining, expiresAt }) {
  const fields=[], vals=[];
  if (msgRemaining !== undefined) { fields.push("msg_remaining=?"); vals.push(Math.max(0, Number(msgRemaining)||0)); }
  if (imgRemaining !== undefined) { fields.push("img_remaining=?"); vals.push(Math.max(0, Number(imgRemaining)||0)); }
  if (expiresAt !== undefined)    { fields.push("expires_at=?");    vals.push(expiresAt); }
  if (!fields.length) return;
  await db.prepare(`UPDATE chat_packages SET ${fields.join(",")} WHERE id=?`).bind(...vals, Number(id)).run();
}
async function deactivateChatPackage(db, id) {
  await db.prepare("UPDATE chat_packages SET active=0 WHERE id=?").bind(Number(id)).run();
}
async function deleteChatPackage(db, id) {
  await db.prepare("DELETE FROM chat_packages WHERE id=?").bind(Number(id)).run();
}

// ─── Reading bundle state for a chat ──────────────────────────────────────
// "live" = active flag set AND not expired AND at least 1 unit of msg OR img left
// (a bundle that's out of messages but still has images left, or vice versa, is
// still live — each resource is drained independently, see consumeChatPackages).
function isBundleLive(b) {
  if (!b.active) return false;
  if (Date.parse(b.expires_at) <= Date.now()) return false;
  return (b.msg_remaining > 0 || b.img_remaining > 0);
}
async function getChatPackages(db, chatId, liveOnly=false) {
  const r = await db.prepare(
    "SELECT * FROM chat_packages WHERE chat_id=? ORDER BY expires_at ASC"
  ).bind(Number(chatId)).all();
  const rows = r.results||[];
  return liveOnly ? rows.filter(isBundleLive) : rows;
}

// ─── The consumption engine ────────────────────────────────────────────────
// Tries to take 1 unit of `type` ("msg"|"img") from the chat's time-limited
// bundles before anything else. Bundles are tried in order of soonest expiry
// first (so a near-expiring one is used up before a longer one, just like
// stacked mobile data packages). Returns {allowed:true, source:"package", id}
// on success, or {allowed:false} if no live bundle has that resource left —
// the caller should then fall through to the permanent/daily limit check.
async function consumeChatPackages(db, chatId, type) {
  const col = type === "img" ? "img_remaining" : "msg_remaining";
  const bundles = await getChatPackages(db, chatId, true); // already sorted by expires_at ASC
  for (const b of bundles) {
    if (b[col] <= 0) continue; // this bundle is out of this particular resource — try the next one
    // atomic decrement guarded by the same conditions, so concurrent requests
    // can't both consume the bundle's last remaining unit.
    const upd = await db.prepare(
      `UPDATE chat_packages SET ${col}=${col}-1 WHERE id=? AND ${col}>0 AND active=1 AND expires_at>?`
    ).bind(b.id, new Date().toISOString()).run();
    if ((upd.meta?.changes ?? 0) > 0) {
      return { allowed: true, source: "package", packageRowId: b.id };
    }
    // lost the race to another concurrent request — try the next bundle instead of failing outright
  }
  return { allowed: false };
}

// housekeeping: flip `active` off for bundles that have visibly expired or
// drained, so dashboard views don't have to re-derive this on every render.
// Safe to call opportunistically; not required for correctness (isBundleLive
// already re-checks expiry/remaining live).
async function sweepExpiredPackages(db, chatId=null) {
  const nowIso = new Date().toISOString();
  const q = chatId
    ? `UPDATE chat_packages SET active=0 WHERE active=1 AND (expires_at<=? OR (msg_remaining<=0 AND img_remaining<=0)) AND chat_id=?`
    : `UPDATE chat_packages SET active=0 WHERE active=1 AND (expires_at<=? OR (msg_remaining<=0 AND img_remaining<=0))`;
  const binds = chatId ? [nowIso, Number(chatId)] : [nowIso];
  try { await db.prepare(q).bind(...binds).run(); } catch {}
}

// ═══════════════════════════════════════════════════════════════
// § 4d  API KEYS  (external API access, issued from the admin panel)
// ═══════════════════════════════════════════════════════════════
// @FILE-SPLIT → src/admin.js (issued/managed entirely from the admin panel)
// Self-contained: generateApiKey/sha256Hex/createApiKey/listApiKeys/
// setApiKeyActive/deleteApiKey/updateApiKeyLimits/checkAndConsumeApiKey/
// getApiKeyFromRequest. No deps beyond `db` and the Web Crypto global.
// Keys are generated as `nk_<32 random hex chars>`. Only the SHA-256 hash is
// stored in the DB — the raw key is shown to the admin exactly once at creation
// time and can never be retrieved again (same model as most API providers).
// Each key has its own lifetime msg/img pool (0=unlimited) — this is the
// "admin" budget for that whole 3rd-party app. Actual consumption (atomic,
// shared with each api_user's own sub-limit) happens in § 4f / consumeApiQuota.

const API_KEY_PREFIX = "nk_";
// request-size guards for the public API (413 / 400 instead of burning model calls on junk)
const API_MAX_MESSAGE_CHARS = 20000;
const API_MAX_PROMPT_CHARS  = 8000;
const API_MAX_MEDIA_B64     = 14_000_000; // ≈ 10 MB of raw bytes

function generateApiKey() {
  const bytes = crypto.getRandomValues(new Uint8Array(24));
  const raw = Array.from(bytes, b => b.toString(16).padStart(2, "0")).join("");
  return `${API_KEY_PREFIX}${raw}`;
}

async function sha256Hex(text) {
  const buf = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(text));
  return Array.from(new Uint8Array(buf), b => b.toString(16).padStart(2, "0")).join("");
}

// creates a new key, returns the RAW key once (caller must show it to the admin and discard it)
async function createApiKey(db, { label = "", msgLimit = 0, imgLimit = 0, expiresAt = null } = {}) {
  const raw  = generateApiKey();
  const hash = await sha256Hex(raw);
  const prefix = raw.slice(0, API_KEY_PREFIX.length + 6); // e.g. nk_ab12cd — shown in lists for identification
  await db.prepare(`
    INSERT INTO api_keys(key_hash,key_prefix,label,active,msg_limit,img_limit,msg_used,img_used,created_at,expires_at)
    VALUES(?,?,?,1,?,?,0,0,?,?)
  `).bind(hash, prefix, label||"", Number(msgLimit)||0, Number(imgLimit)||0, new Date().toISOString(), expiresAt||null).run();
  return { raw, prefix };
}

async function listApiKeys(db) {
  const r = await db.prepare(`SELECT id,key_prefix,label,active,cors_enabled,msg_limit,img_limit,msg_used,img_used,created_at,last_used_at,expires_at FROM api_keys ORDER BY id DESC`).all();
  return r.results || [];
}

async function setApiKeyActive(db, id, active) {
  await db.prepare("UPDATE api_keys SET active=? WHERE id=?").bind(active?1:0, id).run();
}

// ─── setApiKeyCors — per-key toggle for cross-origin (browser) access to
// the external API. Independent of `active`: a disabled-CORS key still
// works fine for server-to-server calls, it just won't carry the
// Access-Control-* headers a browser needs to read the response. ─────────
async function setApiKeyCors(db, id, enabled) {
  await db.prepare("UPDATE api_keys SET cors_enabled=? WHERE id=?").bind(enabled?1:0, id).run();
}

async function deleteApiKey(db, id) {
  await db.prepare(`DELETE FROM api_messages WHERE api_user_id IN (SELECT id FROM api_users WHERE key_id=?)`).bind(id).run();
  await db.batch([
    db.prepare("DELETE FROM api_users WHERE key_id=?").bind(id),
    db.prepare("DELETE FROM api_keys WHERE id=?").bind(id),
  ]);
}

// admin-panel only — sets the KEY's own pool. Never exposed to the public API
// (a 3rd-party app must not be able to grant itself more overall quota).
async function updateApiKeyLimits(db, id, { msgLimit, imgLimit } = {}) {
  const cur = await db.prepare("SELECT msg_limit,img_limit FROM api_keys WHERE id=?").bind(id).first();
  if (!cur) return false;
  const ml = msgLimit !== undefined ? Number(msgLimit)||0 : cur.msg_limit;
  const il = imgLimit !== undefined ? Number(imgLimit)||0 : cur.img_limit;
  await db.prepare("UPDATE api_keys SET msg_limit=?,img_limit=? WHERE id=?").bind(ml, il, id).run();
  return true;
}

// validates a raw API key — auth only (active/expired). Quota is checked
// separately per call-type by consumeApiQuota (§ 4f), since msg/img pools
// are tracked per-type and shared between the key and its api_users.
async function checkAndConsumeApiKey(db, rawKey) {
  if (!rawKey) return { ok:false, error:"missing api key", status:401, corsEnabled:true };
  const hash = await sha256Hex(rawKey.trim());
  const row  = await db.prepare(`SELECT id,active,expires_at,cors_enabled FROM api_keys WHERE key_hash=?`).bind(hash).first();
  if (!row)        return { ok:false, error:"invalid api key", status:401, corsEnabled:true };
  // default true for legacy rows created before the column existed (D1's
  // ALTER TABLE ... DEFAULT 1 backfills existing rows too, but this keeps
  // the check safe even if cors_enabled ever comes back NULL/undefined).
  const corsEnabled = row.cors_enabled !== 0;
  if (!row.active) return { ok:false, error:"api key disabled", status:403, corsEnabled };
  if (row.expires_at && new Date(row.expires_at).getTime() < Date.now())
    return { ok:false, error:"api key expired", status:403, corsEnabled };
  await db.prepare("UPDATE api_keys SET last_used_at=? WHERE id=?").bind(new Date().toISOString(), row.id).run();
  return { ok:true, keyId: row.id, corsEnabled };
}

function getApiKeyFromRequest(request, url) {
  const header = request.headers.get("X-API-Key") || request.headers.get("x-api-key");
  if (header) return header.trim();
  const auth = request.headers.get("Authorization") || "";
  const m = auth.match(/^Bearer\s+(.+)$/i);
  if (m) return m[1].trim();
  return url.searchParams.get("api_key") || url.searchParams.get("key") || null;
}

// ═══════════════════════════════════════════════════════════════
// § 4e  BROADCAST ENGINE  (resumable, lock-protected mass messaging)
// ═══════════════════════════════════════════════════════════════
// @FILE-SPLIT → src/admin.js (started/monitored entirely from the admin
// panel — see handleAdminBroadcast further below in this same section)
// Needs: C/sleep/log from config.js, and (for the actual send step further
// down) the Telegram-sending helpers from webhook.js.
//
// Replaces the old fire-and-forget broadcast (which fanned a payload out to
// every target inside a single Worker invocation — fine for a handful of
// users, but guaranteed to hit the Worker's execution-time limit once the
// audience reaches a few hundred recipients).
//
// Design
// ──────
// 1. The admin panel only ever *creates a mission* (broadcast_send). No
//    message is sent at creation time — see createBroadcastMission().
// 2. Every incoming Telegram webhook, AFTER it has fully handled the
//    sender's own request, calls tickBroadcastMission() once. That call:
//      a. acquires a single-flight lock on the active mission (atomic D1
//         UPDATE — see acquireMissionLock), so two webhooks arriving back
//         to back never double-process the same batch;
//      b. pulls one page of recipients ordered by last_activity DESC
//         (fetchBroadcastPage) starting at the mission's saved offset;
//      c. sends to each recipient one at a time, recording the per-chat
//         result the instant it's known (sendAndRecordOne) — nothing is
//         buffered in memory, so the function's footprint stays flat
//         regardless of audience size;
//      d. persists the new offset after the batch so a killed Worker
//         resumes exactly where it left off on the next webhook;
//      e. stops early, well before the Worker's execution budget runs out,
//         to avoid the in-flight Telegram request itself timing out.
// 3. registerUser() (and isGroupApproved() for groups) stamp
//    `last_activity` on every inbound message, so the most recently active
//    recipients are always delivered to first without ever physically
//    moving rows around in `users`/`groups`.
// 4. The admin panel can pause, resume, cancel, or permanently delete a
//    mission at any point — see handleAdminBroadcast() below.
//
// Concurrency & locking
// ──────────────────────
// Two layers guard against duplicate delivery:
//   • acquireMissionLock() — an atomic `UPDATE ... WHERE locked_by IS NULL
//     OR locked_at < <stale threshold>` claims the mission for this Worker
//     invocation. D1 serializes writes, so exactly one concurrent caller
//     can ever flip that row; everyone else's UPDATE affects zero rows and
//     they back off immediately. This needs no external lock service.
//   • broadcast_sent (mission_id, chat_id) PRIMARY KEY — belt-and-braces
//     de-duplication ledger. Even if a stale lock were somehow reused, an
//     `INSERT OR IGNORE` here makes re-delivery to an already-attempted
//     recipient a guaranteed no-op.
//
// Within one batch, BROADCAST_CONCURRENCY recipients are processed in
// parallel via a small worker-pool (see runConcurrentStream) — each
// in-flight slot picks up the next pending chat id as soon as it frees up,
// and writes its own result to D1 immediately rather than collecting into
// an array first.
// ═══════════════════════════════════════════════════════════════

/** Recipients sent to per webhook tick. */
const BROADCAST_BATCH_SIZE = 100;
/** Recipients in flight at once within a batch. */
const BROADCAST_CONCURRENCY = 10;
/** Stop starting new work once less than this much of the Worker's budget remains. */
const BROADCAST_DEADLINE_BUFFER_MS = 5_000;
/** Assumed total execution budget available to this Worker invocation. */
const BROADCAST_WORKER_BUDGET_MS = 25_000;
/** A lock older than this is treated as abandoned (Worker died mid-batch) and may be reclaimed. */
const BROADCAST_LOCK_STALE_SECONDS = 35;
/** Completed/cancelled missions older than this many most-recent are pruned, along with their ledger rows. */
const BROADCAST_KEEP_FINISHED_MISSIONS = 5;
/**
 * Telegram 429 (Too Many Requests) responses include `parameters.retry_after`
 * (seconds). We honor it but cap the wait so one rate-limited recipient can
 * never eat the whole Worker budget — anything above this is still capped
 * and the recipient is simply left to be retried on the *next* tick instead.
 */
const BROADCAST_RATE_LIMIT_MAX_WAIT_MS = 8_000;

/**
 * Pauses every concurrent lane until `rateState.until` has passed. All lanes
 * within one batch share the same `rateState` object, so the moment any lane
 * hits a Telegram 429, the rest back off too instead of independently
 * hammering the API and racking up more 429s of their own.
 *
 * @param {{until: number}} rateState - mutable, shared across one batch
 * @returns {Promise<void>}
 */
async function respectBroadcastRateLimit(rateState) {
  const waitMs = rateState.until - Date.now();
  if (waitMs > 0) await sleep(Math.min(waitMs, BROADCAST_RATE_LIMIT_MAX_WAIT_MS));
}

// ───────────────────────────────────────────────────────────────
// Mission lifecycle — D1 persistence helpers
// ───────────────────────────────────────────────────────────────

/**
 * Returns the single in-progress mission, if any (pending/running/paused).
 * Only one mission may be active at a time by design — see broadcast_send.
 *
 * @param {object} db - D1 database handle
 * @returns {Promise<object|null>}
 */
async function getActiveMission(db) {
  return db.prepare(`
    SELECT * FROM broadcast_missions
    WHERE status IN ('pending','running','paused')
    ORDER BY priority DESC, id ASC LIMIT 1
  `).first();
}

/**
 * Creates a new broadcast mission. Does not send anything — delivery is
 * driven entirely by tickBroadcastMission() on subsequent webhooks.
 *
 * @param {object} db
 * @param {object} params
 * @param {string} params.target      - 'users' | 'groups' | 'all' | 'single'
 * @param {number|null} params.chatId - required when target === 'single'
 * @param {object} params.payload     - { mediaType, text, caption, fileBase64, mimeType, fileName }
 * @param {number} params.totalCount  - resolved recipient count at creation time
 * @returns {Promise<number>} the new mission's id
 */
async function createBroadcastMission(db, { target, chatId = null, payload, totalCount, priority = 0 }) {
  const now = new Date().toISOString();
  const result = await db.prepare(`
    INSERT INTO broadcast_missions
      (target, chat_id, payload_json, status, offset, total_count,
       sent, failed, priority, locked_by, locked_at, created_at, updated_at)
    VALUES (?,?,?,'pending',0,?,0,0,?,NULL,NULL,?,?)
  `).bind(
    target,
    chatId ? Number(chatId) : null,
    JSON.stringify(payload),
    Number(totalCount),
    Number(priority) || 0,
    now, now,
  ).run();
  return result.meta?.last_row_id;
}

/**
 * Atomically claims the mission for this Worker invocation.
 *
 * A single UPDATE both checks and sets ownership, so it is race-free even
 * when several Worker instances call tickBroadcastMission() concurrently
 * (Telegram can deliver more than one webhook in parallel). The condition
 * also reclaims locks left behind by a Worker that was killed mid-batch.
 *
 * @param {object} db
 * @param {number} missionId
 * @param {string} ownerId - a value unique to this invocation (crypto.randomUUID())
 * @returns {Promise<boolean>} true if the lock was acquired
 */
async function acquireMissionLock(db, missionId, ownerId) {
  const staleBefore = new Date(Date.now() - BROADCAST_LOCK_STALE_SECONDS * 1000).toISOString();
  const result = await db.prepare(`
    UPDATE broadcast_missions
    SET locked_by=?, locked_at=?, status='running', updated_at=?
    WHERE id=?
      AND status IN ('pending','running')
      AND (locked_by IS NULL OR locked_by=? OR locked_at<?)
  `).bind(
    ownerId, new Date().toISOString(), new Date().toISOString(),
    missionId,
    ownerId, staleBefore,
  ).run();
  return (result.meta?.changes ?? 0) > 0;
}

/**
 * Releases the lock, but only if it is still held by `ownerId` — prevents
 * one invocation from accidentally releasing a lock another invocation has
 * since (re)acquired.
 *
 * @param {object} db
 * @param {number} missionId
 * @param {string} ownerId
 * @returns {Promise<void>}
 */
async function releaseMissionLock(db, missionId, ownerId) {
  try {
    await db.prepare(`
      UPDATE broadcast_missions
      SET locked_by=NULL, locked_at=NULL, updated_at=?
      WHERE id=? AND locked_by=?
    `).bind(new Date().toISOString(), missionId, ownerId).run();
  } catch { /* best-effort */ }
}

/**
 * Persists progress after a batch without touching the lock — the caller
 * releases the lock separately once it decides whether to keep going.
 *
 * @param {object} db
 * @param {number} missionId
 * @param {number} newOffset
 * @param {number} sentDelta
 * @param {number} failedDelta
 * @returns {Promise<void>}
 */
async function saveMissionProgress(db, missionId, newOffset, sentDelta, failedDelta) {
  await db.prepare(`
    UPDATE broadcast_missions
    SET offset=?, sent=sent+?, failed=failed+?, updated_at=?
    WHERE id=?
  `).bind(newOffset, sentDelta, failedDelta, new Date().toISOString(), missionId).run();
}

/**
 * Marks a mission completed and releases its lock.
 *
 * @param {object} db
 * @param {number} missionId
 * @param {number} [sentDelta]
 * @param {number} [failedDelta]
 * @returns {Promise<void>}
 */
async function completeMission(db, missionId, sentDelta = 0, failedDelta = 0) {
  await db.prepare(`
    UPDATE broadcast_missions
    SET status='completed', locked_by=NULL, locked_at=NULL,
        sent=sent+?, failed=failed+?, updated_at=?
    WHERE id=?
  `).bind(sentDelta, failedDelta, new Date().toISOString(), missionId).run();
}

/**
 * Sets a mission's status (used for pause/cancel) and releases its lock,
 * so a paused/cancelled mission can never block the lock for anyone else.
 *
 * @param {object} db
 * @param {number} missionId
 * @param {string} status - 'paused' | 'cancelled' | 'pending' (resume)
 * @returns {Promise<void>}
 */
async function setMissionStatus(db, missionId, status) {
  await db.prepare(`
    UPDATE broadcast_missions
    SET status=?, locked_by=NULL, locked_at=NULL, updated_at=?
    WHERE id=?
  `).bind(status, new Date().toISOString(), missionId).run();
}

/**
 * Permanently deletes a mission and its delivery ledger, regardless of
 * status. Used by the admin panel's "delete" action — distinct from
 * cancel, which just stops delivery but keeps the row for history.
 *
 * @param {object} db
 * @param {number} missionId
 * @returns {Promise<void>}
 */
async function deleteMission(db, missionId) {
  await db.batch([
    db.prepare(`DELETE FROM broadcast_missions WHERE id=?`).bind(Number(missionId)),
    db.prepare(`DELETE FROM broadcast_sent WHERE mission_id=?`).bind(Number(missionId)),
  ]);
}

/**
 * Prunes old finished missions (and their ledger rows) so the schema does
 * not grow unbounded. Keeps the most recent BROADCAST_KEEP_FINISHED_MISSIONS
 * completed/cancelled missions for the admin panel's history view. Called
 * after a mission finishes, is cancelled, or is deleted — never on the hot
 * per-message path.
 *
 * @param {object} db
 * @returns {Promise<void>}
 */
async function pruneFinishedMissions(db) {
  try {
    const recent = await db.prepare(`
      SELECT id FROM broadcast_missions
      WHERE status IN ('completed','cancelled')
      ORDER BY id DESC LIMIT ?
    `).bind(BROADCAST_KEEP_FINISHED_MISSIONS).all();
    const recentIds = (recent.results || []).map(r => r.id);
    if (recentIds.length < BROADCAST_KEEP_FINISHED_MISSIONS) return;

    const cutoffId = Math.min(...recentIds);
    await db.prepare(`
      DELETE FROM broadcast_sent WHERE mission_id IN (
        SELECT id FROM broadcast_missions
        WHERE status IN ('completed','cancelled') AND id<?
      )
    `).bind(cutoffId).run();
    await db.prepare(`
      DELETE FROM broadcast_missions
      WHERE status IN ('completed','cancelled') AND id<?
    `).bind(cutoffId).run();
  } catch (e) {
    console.warn("[Broadcast] pruneFinishedMissions:", e.message);
  }
}

// ───────────────────────────────────────────────────────────────
// Recipient resolution — priority-ordered, paginated
// ───────────────────────────────────────────────────────────────

/**
 * Counts how many recipients a target resolves to, at mission-creation
 * time (used to show progress as sent/total in the admin panel).
 *
 * @param {object} db
 * @param {string} target - 'users' | 'groups' | 'all' | 'single'
 * @returns {Promise<number>}
 */
async function countBroadcastTargets(db, target) {
  if (target === "users") {
    const r = await db.prepare(`SELECT COUNT(*) AS c FROM users`).first();
    return r?.c ?? 0;
  }
  if (target === "groups") {
    const r = await db.prepare(`SELECT COUNT(*) AS c FROM groups WHERE approved=1`).first();
    return r?.c ?? 0;
  }
  if (target === "all") {
    const [u, g] = await Promise.all([
      db.prepare(`SELECT COUNT(*) AS c FROM users`).first(),
      db.prepare(`SELECT COUNT(*) AS c FROM groups WHERE approved=1`).first(),
    ]);
    return (u?.c ?? 0) + (g?.c ?? 0);
  }
  return 1; // 'single'
}

/**
 * Fetches one page of recipient chat ids, ordered by last_activity DESC
 * (most recently active first) so active users always receive a broadcast
 * before inactive ones — without ever physically reordering `users` or
 * `groups`. Only `chat_id` is selected to keep each page's memory
 * footprint minimal.
 *
 * @param {object} db
 * @param {string} target          - 'users' | 'groups' | 'all' | 'single'
 * @param {number|null} singleChatId - used only when target === 'single'
 * @param {number} offset          - resume cursor (mission.offset)
 * @param {number} limit           - page size
 * @returns {Promise<number[]>} chat ids for this page, in priority order
 */
async function fetchBroadcastPage(db, target, singleChatId, offset, limit) {
  if (target === "single") {
    return singleChatId ? [Number(singleChatId)] : [];
  }
  if (target === "users") {
    const r = await db.prepare(`
      SELECT user_id AS chat_id FROM users
      ORDER BY COALESCE(last_activity,'1970-01-01') DESC
      LIMIT ? OFFSET ?
    `).bind(limit, offset).all();
    return (r.results || []).map(row => row.chat_id);
  }
  if (target === "groups") {
    const r = await db.prepare(`
      SELECT chat_id FROM groups WHERE approved=1
      ORDER BY COALESCE(last_activity,'1970-01-01') DESC
      LIMIT ? OFFSET ?
    `).bind(limit, offset).all();
    return (r.results || []).map(row => row.chat_id);
  }
  // 'all': union users + approved groups, kept in one global priority order
  const r = await db.prepare(`
    SELECT chat_id FROM (
      SELECT user_id AS chat_id, COALESCE(last_activity,'1970-01-01') AS la FROM users
      UNION ALL
      SELECT chat_id, COALESCE(last_activity,'1970-01-01') AS la FROM groups WHERE approved=1
    )
    ORDER BY la DESC
    LIMIT ? OFFSET ?
  `).bind(limit, offset).all();
  return (r.results || []).map(row => row.chat_id);
}

// ───────────────────────────────────────────────────────────────
// Telegram delivery
// ───────────────────────────────────────────────────────────────

/**
 * Sends a (possibly multi-chunk) text message and reports per-chunk
 * success/failure, unlike sendMsg() which only logs and swallows errors —
 * the broadcast engine needs a real result to record in broadcast_sent.
 *
 * @param {object} env
 * @param {number} chatId
 * @param {string} text
 * @param {{until: number}|null} [rateState] - shared backoff clock; updated on 429
 * @returns {Promise<{ok: boolean, error?: string, rateLimited?: boolean, retryAfter?: number}>}
 */
async function sendBroadcastText(env, chatId, text, rateState = null) {
  const chunks = splitMsg(text.trim());
  for (const chunk of chunks) {
    try {
      const res = await fetchWithTimeout(tgUrl(env, "sendMessage"), {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ chat_id: chatId, text: chunk, parse_mode: "HTML" }),
      });
      if (res.status === 429) {
        const d = await res.json().catch(() => ({}));
        const retryAfter = d?.parameters?.retry_after ?? 1;
        if (rateState) rateState.until = Date.now() + retryAfter * 1000;
        return { ok: false, error: `rate limited (retry_after=${retryAfter}s)`, rateLimited: true, retryAfter };
      }
      if (!res.ok) {
        const d = await res.json().catch(() => ({}));
        return { ok: false, error: d.description || `HTTP ${res.status}` };
      }
    } catch (e) {
      return { ok: false, error: e.message };
    }
    if (chunks.length > 1) await sleep(400);
  }
  return { ok: true };
}

/**
 * Sends one broadcast payload (text/photo/voice/document) to a single chat.
 *
 * @param {object} env
 * @param {number} chatId
 * @param {object} payload
 * @param {string} payload.mediaType - 'text' | 'photo' | 'voice' | 'document'
 * @param {string} [payload.text]
 * @param {string} [payload.caption]
 * @param {string|null} [payload.fileBase64]
 * @param {string|null} [payload.mimeType]
 * @param {string|null} [payload.fileName]
 * @param {object} imgGen - ImageGen instance (used for photo delivery)
 * @param {{until: number}|null} [rateState] - shared backoff clock; updated on 429
 * @returns {Promise<{ok: boolean, error?: string, rateLimited?: boolean, retryAfter?: number}>}
 */
async function sendBroadcastToChat(env, chatId, payload, imgGen, rateState = null) {
  const {
    mediaType = "text", text = "", fileBase64 = null,
    mimeType = null, fileName = null, caption = "",
  } = payload;
  try {
    if (mediaType === "text" || !fileBase64) {
      if (!text?.trim()) return { ok: false, error: "empty text" };
      return await sendBroadcastText(env, chatId, text, rateState);
    }

    const binary = atob(fileBase64);
    const bytes  = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    const buffer  = bytes.buffer;
    const caption_ = (caption || text || "").trim();

    if (mediaType === "photo") {
      const ext = (mimeType || "").includes("png") ? "png" : "jpg";
      const r = await imgGen.sendPhoto(env, chatId, buffer, mimeType || "image/jpeg", ext, caption_ || null, null);
      if (r.retryAfter != null && rateState) rateState.until = Date.now() + r.retryAfter * 1000;
      return r;
    }

    if (mediaType === "voice") {
      const form = new FormData();
      form.append("chat_id", String(chatId));
      form.append("voice", new Blob([buffer], { type: mimeType || "audio/ogg" }), fileName || "voice.ogg");
      if (caption_) { form.append("caption", caption_); form.append("parse_mode", "HTML"); }
      const res = await fetchWithTimeout(tgUrl(env, "sendVoice"), { method: "POST", body: form }, 20_000);
      if (res.status === 429) {
        const d = await res.json().catch(() => ({}));
        const retryAfter = d?.parameters?.retry_after ?? 1;
        if (rateState) rateState.until = Date.now() + retryAfter * 1000;
        return { ok: false, error: `rate limited (retry_after=${retryAfter}s)`, rateLimited: true, retryAfter };
      }
      const d = await res.json();
      return res.ok ? { ok: true } : { ok: false, error: d.description || `HTTP ${res.status}` };
    }

    // Fallback: generic document (covers any other file type)
    const form = new FormData();
    form.append("chat_id", String(chatId));
    form.append("document", new Blob([buffer], { type: mimeType || "application/octet-stream" }), fileName || "file");
    if (caption_) { form.append("caption", caption_); form.append("parse_mode", "HTML"); }
    const res = await fetchWithTimeout(tgUrl(env, "sendDocument"), { method: "POST", body: form }, 20_000);
    if (res.status === 429) {
      const d = await res.json().catch(() => ({}));
      const retryAfter = d?.parameters?.retry_after ?? 1;
      if (rateState) rateState.until = Date.now() + retryAfter * 1000;
      return { ok: false, error: `rate limited (retry_after=${retryAfter}s)`, rateLimited: true, retryAfter };
    }
    const d = await res.json();
    return res.ok ? { ok: true } : { ok: false, error: d.description || `HTTP ${res.status}` };
  } catch (e) {
    return { ok: false, error: e.message };
  }
}

// ───────────────────────────────────────────────────────────────
// One-by-one send + record — zero in-memory result buffering
// ───────────────────────────────────────────────────────────────

/**
 * Sends to exactly one recipient and persists the outcome before
 * returning. The INSERT OR IGNORE acts as the de-duplication guard: if
 * this (mission_id, chat_id) pair was already recorded by an earlier,
 * interrupted attempt, the insert is a no-op and delivery is skipped
 * entirely — guaranteeing each recipient is messaged at most once per
 * mission even across Worker restarts.
 *
 * If Telegram responds 429, the shared `rateState` clock is updated (so
 * every other concurrent lane backs off too) and this recipient gets one
 * immediate retry after the backoff — rather than being permanently marked
 * failed just because of a transient rate limit.
 *
 * @param {object} db
 * @param {object} env
 * @param {number} missionId
 * @param {number} chatId
 * @param {object} payload
 * @param {object} imgGen
 * @param {{until: number}} rateState - shared backoff clock for this batch
 * @returns {Promise<'sent'|'failed'|'skipped'>}
 */
async function sendAndRecordOne(db, env, missionId, chatId, payload, imgGen, rateState) {
  let claimed = false;
  try {
    const insert = await db.prepare(`
      INSERT OR IGNORE INTO broadcast_sent(mission_id, chat_id, sent, error, created_at)
      VALUES (?,?,0,NULL,?)
    `).bind(missionId, chatId, new Date().toISOString()).run();
    claimed = (insert.meta?.changes ?? 0) > 0;
  } catch {
    claimed = true; // ledger unavailable — proceed rather than stall delivery
  }
  if (!claimed) return "skipped";

  await respectBroadcastRateLimit(rateState);
  let result = await sendBroadcastToChat(env, chatId, payload, imgGen, rateState);

  if (result.rateLimited) {
    // back off (rateState.until was just set) then retry this same
    // recipient once before giving up — a 429 isn't this user's fault.
    await respectBroadcastRateLimit(rateState);
    result = await sendBroadcastToChat(env, chatId, payload, imgGen, rateState);
  }

  try {
    if (result.ok) {
      await db.prepare(`UPDATE broadcast_sent SET sent=1 WHERE mission_id=? AND chat_id=?`)
        .bind(missionId, chatId).run();
    } else {
      await db.prepare(`UPDATE broadcast_sent SET sent=0, error=? WHERE mission_id=? AND chat_id=?`)
        .bind((result.error || "unknown").slice(0, 200), missionId, chatId).run();
      console.warn(`[Broadcast] mission=${missionId} chatId=${chatId} error=${result.error}`);
    }
  } catch { /* delivery already happened — a ledger write failure must not be reported as send failure */ }

  return result.ok ? "sent" : "failed";
}

/**
 * Runs sendAndRecordOne() over `chatIds` with at most `concurrency` in
 * flight at once. Each worker lane immediately persists its own result
 * (inside sendAndRecordOne) and moves on to the next id — no results array
 * is ever accumulated, so memory use stays O(1) regardless of batch size.
 *
 * @param {number[]} chatIds
 * @param {number} concurrency
 * @param {(chatId: number) => Promise<'sent'|'failed'|'skipped'>} sendOne
 * @returns {Promise<{sent: number, failed: number, skipped: number}>}
 */
async function runConcurrentStream(chatIds, concurrency, sendOne) {
  let cursor = 0;
  let sent = 0, failed = 0, skipped = 0;

  async function lane() {
    while (true) {
      const i = cursor++;
      if (i >= chatIds.length) return;
      const outcome = await sendOne(chatIds[i]);
      if (outcome === "sent") sent++;
      else if (outcome === "skipped") skipped++;
      else failed++;
    }
  }

  const lanes = Array.from({ length: Math.min(concurrency, chatIds.length) }, lane);
  await Promise.all(lanes);
  return { sent, failed, skipped };
}

// ───────────────────────────────────────────────────────────────
// tickBroadcastMission — the engine's heartbeat
// ───────────────────────────────────────────────────────────────

/**
 * Advances the active broadcast mission by one batch. Intended to be
 * called exactly once per incoming Telegram webhook, after that webhook's
 * own user-facing work is already complete — see the call site in the
 * fetch handler (§ 14).
 *
 * No-ops quickly (and cheaply) whenever there is nothing to do: no active
 * mission, mission is paused, insufficient time remains in this Worker
 * invocation's budget, or another invocation currently holds the lock.
 *
 * @param {object} env      - Worker environment bindings
 * @param {object} db       - D1 database handle
 * @param {object} imgGen   - ImageGen instance
 * @param {number} startMs  - Date.now() captured at the top of this request
 * @returns {Promise<void>}
 */
async function tickBroadcastMission(env, db, imgGen, startMs) {
  if (Date.now() - startMs > BROADCAST_WORKER_BUDGET_MS - BROADCAST_DEADLINE_BUFFER_MS) return;

  let mission;
  try { mission = await getActiveMission(db); } catch { return; }
  if (!mission || mission.status === "paused") return;

  const ownerId = crypto.randomUUID();
  const locked  = await acquireMissionLock(db, mission.id, ownerId);
  if (!locked) return; // another invocation owns this mission right now

  try {
    const payload = JSON.parse(mission.payload_json);
    // Shared across every recipient processed in this tick (single target or
    // a whole batch) so a 429 from any one of them backs *everyone* off.
    const rateState = { until: 0 };

    if (mission.target === "single") {
      if (mission.chat_id) {
        const outcome = await sendAndRecordOne(db, env, mission.id, mission.chat_id, payload, imgGen, rateState);
        await completeMission(db, mission.id, outcome === "sent" ? 1 : 0, outcome === "failed" ? 1 : 0);
        await logBroadcastSummary(db, mission, outcome === "sent" ? 1 : 0, outcome === "failed" ? 1 : 0);
      } else {
        await completeMission(db, mission.id);
      }
      await pruneFinishedMissions(db);
      return;
    }

    let chatIds;
    try {
      chatIds = await fetchBroadcastPage(db, mission.target, mission.chat_id, mission.offset, BROADCAST_BATCH_SIZE);
    } catch (e) {
      console.error("[Broadcast] fetchBroadcastPage:", e.message);
      await releaseMissionLock(db, mission.id, ownerId);
      return;
    }

    if (!chatIds.length) {
      await completeMission(db, mission.id);
      await logBroadcastSummary(db, mission, mission.sent, mission.failed);
      await pruneFinishedMissions(db);
      return;
    }

    const { sent, failed } = await runConcurrentStream(
      chatIds, BROADCAST_CONCURRENCY,
      (chatId) => sendAndRecordOne(db, env, mission.id, chatId, payload, imgGen, rateState),
    );

    const newOffset = mission.offset + chatIds.length;
    const isFinished = newOffset >= mission.total_count || chatIds.length < BROADCAST_BATCH_SIZE;

    if (isFinished) {
      await completeMission(db, mission.id, sent, failed);
      await logBroadcastSummary(db, mission, mission.sent + sent, mission.failed + failed);
      await pruneFinishedMissions(db);
    } else {
      await saveMissionProgress(db, mission.id, newOffset, sent, failed);
      await releaseMissionLock(db, mission.id, ownerId);
    }
  } catch (e) {
    console.error("[Broadcast] tick error:", e.message);
    await releaseMissionLock(db, mission.id, ownerId);
  }
}

/**
 * Writes a summary row to the legacy `broadcasts` history table so the
 * admin panel's existing history view keeps working unchanged.
 *
 * @param {object} db
 * @param {object} mission
 * @param {number} totalSent
 * @param {number} totalFailed
 * @returns {Promise<void>}
 */
async function logBroadcastSummary(db, mission, totalSent, totalFailed) {
  try {
    const payload = JSON.parse(mission.payload_json);
    await db.prepare(`
      INSERT INTO broadcasts(target, media_type, caption, total, sent, failed, created_at)
      VALUES (?,?,?,?,?,?,?)
    `).bind(
      mission.target,
      payload.mediaType || "text",
      (payload.caption || payload.text || "").slice(0, 200),
      mission.total_count,
      totalSent,
      totalFailed,
      new Date().toISOString(),
    ).run();
  } catch { /* history logging is best-effort */ }
}

// ───────────────────────────────────────────────────────────────
// Admin panel actions
// ───────────────────────────────────────────────────────────────

/**
 * Dispatches every broadcast-related admin action. Called from
 * handleAdmin() (§ 15) with the parsed POST body.
 *
 * Actions:
 *   broadcast_send      - create a mission (does not send anything yet)
 *   broadcast_status     - poll the active mission's live progress
 *   broadcast_pause       - suspend delivery, releasing the lock
 *   broadcast_resume      - re-queue a paused mission
 *   broadcast_cancel      - stop delivery permanently (row kept for history)
 *   broadcast_delete      - permanently remove a mission + its ledger
 *   broadcast_history     - legacy completed-broadcast summaries
 *   broadcast_missions    - recent missions of any status
 *
 * @param {object} env
 * @param {object} db
 * @param {string} action
 * @param {object} body
 * @returns {Promise<Response>}
 */
async function handleAdminBroadcast(env, db, action, body) {
  if (action === "broadcast_send") {
    const { target, chatId: explicitChatId, mediaType, text, caption, fileBase64, mimeType, fileName, priority } = body;

    if (!["users", "groups", "all", "single"].includes(target))
      return jr({ ok: false, error: "invalid target" });
    if (target === "single" && !explicitChatId)
      return jr({ ok: false, error: "missing chatId" });
    if ((mediaType === "text" || !mediaType) && !text?.trim())
      return jr({ ok: false, error: "empty text" });
    if (mediaType && mediaType !== "text" && !fileBase64)
      return jr({ ok: false, error: "missing file" });

    // Missions used to be blocked entirely while one was already active —
    // now a new mission just joins the queue instead. getActiveMission()
    // always picks the single highest-priority (then oldest) pending/
    // running/paused row, so several missions created back-to-back run one
    // at a time, in that order, with zero extra wiring needed here.
    const existing = await getActiveMission(db);

    const totalCount = target === "single" ? 1 : await countBroadcastTargets(db, target);
    if (totalCount === 0) return jr({ ok: false, error: "هیچ مخاطبی یافت نشد." });

    const missionId = await createBroadcastMission(db, {
      target,
      chatId: explicitChatId || null,
      payload: {
        mediaType:  mediaType  || "text",
        text:       text       || "",
        caption:    caption    || "",
        fileBase64: fileBase64 || null,
        mimeType:   mimeType   || null,
        fileName:   fileName   || null,
      },
      totalCount,
      priority: Number(priority) || 0,
    });

    await log(db, {
      action: "broadcast_mission_created",
      level:  "admin",
      detail: `target=${target} total=${totalCount} missionId=${missionId} priority=${Number(priority)||0}`,
    });

    // Kick off the first batch immediately instead of waiting for the next
    // inbound Telegram webhook (or the cron heartbeat) to piggyback on —
    // the admin gets instant feedback that the mission is actually moving.
    // Bounded to one batch (tickBroadcastMission's own time/size budget),
    // so this can't turn mission creation into a long-hanging request. If
    // another mission is already active/running ahead of this one in the
    // queue, this tick just advances THAT one as usual — harmless, and the
    // new mission's own turn comes once it's actually first in line.
    try {
      await tickBroadcastMission(env, db, new ImageGen(env), Date.now());
    } catch (e) { console.error("[broadcast_send] initial tick failed:", e.message); }
    const freshMission = await db.prepare(`SELECT offset,sent,failed,status,total_count FROM broadcast_missions WHERE id=?`).bind(missionId).first();
    // If it's still sitting at 'pending' with nothing sent after the tick
    // above, something else in the queue outranked it (higher priority, or
    // equal priority but older) — otherwise it just ran its first batch.
    const isQueued = freshMission?.status === "pending" && !freshMission?.sent && !freshMission?.failed;
    const aheadMission = isQueued ? existing : null;
    const queueMsg = aheadMission && aheadMission.id !== missionId
      ? ` نوبتش بعد از Mission #${aheadMission.id} می‌رسه.`
      : isQueued ? " در صف قرار گرفت." : " و همین الان شروع شد.";

    return jr({
      ok: true,
      missionId,
      totalCount,
      sentSoFar: freshMission?.sent ?? 0,
      status: freshMission?.status ?? "pending",
      message: `✅ Mission #${missionId} ایجاد شد (${totalCount} گیرنده)${queueMsg} تا اینجا ${freshMission?.sent ?? 0} تا ارسال شده، بقیه به‌تدریج ادامه پیدا می‌کنه.`,
    });
  }

  if (action === "broadcast_status") {
    const mission = await getActiveMission(db);
    if (!mission) return jr({ ok: true, active: false });
    const progressPct = mission.total_count > 0
      ? Math.round((mission.offset / mission.total_count) * 100)
      : 0;
    return jr({
      ok: true, active: true,
      mission: {
        id: mission.id, target: mission.target, status: mission.status,
        offset: mission.offset, totalCount: mission.total_count,
        sent: mission.sent, failed: mission.failed, progressPct,
        lockedBy: mission.locked_by, lockedAt: mission.locked_at,
        createdAt: mission.created_at, updatedAt: mission.updated_at,
      },
    });
  }

  if (action === "broadcast_pause") {
    const mission = await getActiveMission(db);
    if (!mission) return jr({ ok: false, error: "هیچ Mission فعالی وجود ندارد." });
    if (mission.status === "paused") return jr({ ok: false, error: "Mission از قبل متوقف است." });
    await setMissionStatus(db, mission.id, "paused");
    await log(db, { action: "broadcast_paused", level: "admin", detail: `missionId=${mission.id}` });
    return jr({ ok: true, paused: true, missionId: mission.id });
  }

  if (action === "broadcast_resume") {
    const mission = await db.prepare(`
      SELECT * FROM broadcast_missions WHERE status='paused' ORDER BY id ASC LIMIT 1
    `).first();
    if (!mission) return jr({ ok: false, error: "هیچ Mission متوقفی وجود ندارد." });
    await setMissionStatus(db, mission.id, "pending");
    await log(db, {
      action: "broadcast_resumed", level: "admin",
      detail: `missionId=${mission.id} offset=${mission.offset}`,
    });
    return jr({ ok: true, resumed: true, missionId: mission.id, offset: mission.offset });
  }

  if (action === "broadcast_cancel") {
    const mission = await getActiveMission(db);
    if (!mission) return jr({ ok: false, error: "هیچ Mission فعالی وجود ندارد." });
    await setMissionStatus(db, mission.id, "cancelled");
    await log(db, {
      action: "broadcast_cancelled", level: "admin",
      detail: `missionId=${mission.id} offset=${mission.offset}/${mission.total_count}`,
    });
    await pruneFinishedMissions(db);
    return jr({ ok: true, cancelled: true, missionId: mission.id });
  }

  if (action === "broadcast_delete") {
    const { id: missionId } = body;
    if (!missionId) return jr({ ok: false, error: "missing id" });
    const mission = await db.prepare(`SELECT status FROM broadcast_missions WHERE id=?`).bind(Number(missionId)).first();
    if (!mission) return jr({ ok: false, error: "Mission یافت نشد." });
    await deleteMission(db, Number(missionId));
    await log(db, { action: "broadcast_deleted", level: "admin", detail: `missionId=${missionId}` });
    return jr({ ok: true, deleted: true, missionId: Number(missionId) });
  }

  if (action === "broadcast_run") {
    const mission = await getActiveMission(db);
    if (!mission) return jr({ ok: false, error: "هیچ Mission فعالی وجود ندارد." });
    // "دوباره روشن بشه" — if it was paused/stalled, flip it back to pending
    // first so the tick below doesn't just no-op on a paused mission.
    if (mission.status === "paused") {
      await setMissionStatus(db, mission.id, "pending");
      await log(db, { action: "broadcast_resumed", level: "admin", detail: `missionId=${mission.id} via manual run` });
    }
    try {
      await tickBroadcastMission(env, db, new ImageGen(env), Date.now());
    } catch (e) { return jr({ ok: false, error: e.message || "tick failed" }); }
    const fresh = await db.prepare(`
      SELECT id,target,status,offset,total_count,sent,failed,locked_by,created_at,updated_at
      FROM broadcast_missions WHERE id=?
    `).bind(mission.id).first();
    await log(db, { action: "broadcast_manual_run", level: "admin", detail: `missionId=${mission.id}` });
    return jr({ ok: true, mission: fresh || null });
  }

  if (action === "broadcast_history") {
    const r = await db.prepare(`
      SELECT id, target, media_type, caption, total, sent, failed, created_at
      FROM broadcasts ORDER BY id DESC LIMIT 30
    `).all();
    return jr({ ok: true, history: r.results || [] });
  }

  if (action === "broadcast_missions") {
    const r = await db.prepare(`
      SELECT id, target, status, offset, total_count, sent, failed, priority,
             locked_by, created_at, updated_at
      FROM broadcast_missions ORDER BY id DESC LIMIT 20
    `).all();
    return jr({ ok: true, missions: r.results || [] });
  }

  // ── reorder the queue: change a not-yet-finished mission's priority ────
  if (action === "broadcast_set_priority") {
    const { id, priority } = body;
    if (!id) return jr({ ok: false, error: "missing id" });
    const mission = await db.prepare("SELECT status FROM broadcast_missions WHERE id=?").bind(Number(id)).first();
    if (!mission) return jr({ ok: false, error: "mission not found" });
    if (!["pending", "paused"].includes(mission.status))
      return jr({ ok: false, error: "فقط Mission‌های در صف یا متوقف‌شده رو می‌شه اولویت‌بندی کرد." });
    await db.prepare("UPDATE broadcast_missions SET priority=?, updated_at=? WHERE id=?")
      .bind(Number(priority) || 0, new Date().toISOString(), Number(id)).run();
    await log(db, { action: "broadcast_priority_changed", level: "admin", detail: `id=${id} priority=${Number(priority)||0}` });
    return jr({ ok: true });
  }

  return jr({ ok: false, error: "unknown broadcast action" });
}


// ═══════════════════════════════════════════════════════════════
// § 4f  EXTERNAL CHAT API  (POST /api/chat)
// ═══════════════════════════════════════════════════════════════
// @FILE-SPLIT → src/admin.js (its auth keys are issued/managed from the
// admin panel — grouped there with api-keys/packages/broadcast)
// Everything behind the public /api/chat surface: handleApiChat + its own
// history/user CRUD for api_users/api_messages, consumeApiQuota. Depends on
// api-keys (same file) for auth, and gemini.js for the actual answer.
// A real "chat with the model" API for 3rd-party apps — independent of
// Telegram. Auth is the same api_keys system as the admin panel issues
// (X-API-Key / Bearer / ?api_key=, see getApiKeyFromRequest + checkAndConsumeApiKey).
//
// One api_key == one external app. That app can have many of its OWN users —
// just pass a stable `userId` (any string: your DB id, a uuid, a phone, etc.)
// and we keep a separate api_users row + isolated rolling history per
// (key, userId) pair. No userId => a shared "default" bucket for that key.
//
// Quota model — two tiers, msg/img tracked separately, both lifetime pools
// (0 = unlimited), no daily reset (keeps this fast: no per-day rows, see
// consumeApiQuota below):
//   • api_keys.msg_limit/img_limit  — the whole app's budget, set ONLY from
//     the admin panel (the developer can never raise their own key's pool).
//   • api_users.msg_limit/img_limit — each end-user's own cap, set/raised by
//     the developer THROUGH the API itself (setLimits/addLimits below) — e.g.
//     when their user buys a subscription. Every real call decrements BOTH
//     tiers at once; if either is exhausted the call is denied.
//
// Prompt resolution order (nothing hardcoded):
//   1. `systemPrompt` sent in this request
//   2. the prompt saved earlier for this same (key,userId) via {"setSystemPrompt":...}
//   3. admin panel's "apiDefaultPrompt" (Config tab)
//   4. C.API_FALLBACK_PROMPT (last-resort generic string)

async function getOrCreateApiUser(db, keyId, externalUserId) {
  const eid = String(externalUserId ?? "default").slice(0, 200);
  const now = new Date().toISOString();
  await db.prepare(`
    INSERT INTO api_users(key_id,external_user_id,created_at,last_used_at,request_count) VALUES(?,?,?,?,1)
    ON CONFLICT(key_id,external_user_id) DO UPDATE SET last_used_at=excluded.last_used_at, request_count=request_count+1
  `).bind(keyId, eid, now, now).run();
  return db.prepare(`SELECT * FROM api_users WHERE key_id=? AND external_user_id=?`).bind(keyId, eid).first();
}

// ─── consumeApiTypeQuota — atomic lifetime quota check+increment ─────────
// One UPDATE handles both the unlimited case (limit<=0 → WHERE is always
// true) and the limited case, so there's no extra read — kept deliberately
// cheap since this runs on every single chat call.
async function consumeApiTypeQuota(db, table, id, type) {
  const limCol = type === "img" ? "img_limit" : "msg_limit";
  const useCol = type === "img" ? "img_used"  : "msg_used";
  const res = await db.prepare(
    `UPDATE ${table} SET ${useCol}=${useCol}+1 WHERE id=? AND (${limCol}<=0 OR ${useCol}<${limCol})`
  ).bind(id).run();
  return (res.meta?.changes ?? 0) > 0;
}
async function refundApiTypeQuota(db, table, id, type) {
  const useCol = type === "img" ? "img_used" : "msg_used";
  await db.prepare(`UPDATE ${table} SET ${useCol}=MAX(0,${useCol}-1) WHERE id=?`).bind(id).run();
}

// ─── consumeApiQuota — the user's own cap AND the key's overall pool must
// both have room; if the key is out of quota, the user-side debit is rolled
// back so the two stay in sync. ────────────────────────────────────────────
async function consumeApiQuota(db, keyId, apiUserId, type) {
  if (!(await consumeApiTypeQuota(db, "api_users", apiUserId, type)))
    return { allowed:false, reason:"user_limit" };
  if (!(await consumeApiTypeQuota(db, "api_keys", keyId, type))) {
    await refundApiTypeQuota(db, "api_users", apiUserId, type);
    return { allowed:false, reason:"key_limit" };
  }
  return { allowed:true };
}

// ─── setApiUserLimits / addApiUserLimits — developer-managed per-user caps ──
// set = absolute (replace the ceiling); add = top-up on top of the current
// ceiling (e.g. user renews/buys a bigger package — used count is untouched
// so their remaining quota simply grows).
async function setApiUserLimits(db, apiUserId, { msgLimit, imgLimit } = {}) {
  const sets = [], binds = [];
  if (msgLimit !== undefined) { sets.push("msg_limit=?"); binds.push(Math.max(0, Number(msgLimit)||0)); }
  if (imgLimit !== undefined) { sets.push("img_limit=?"); binds.push(Math.max(0, Number(imgLimit)||0)); }
  if (!sets.length) return;
  binds.push(apiUserId);
  await db.prepare(`UPDATE api_users SET ${sets.join(",")} WHERE id=?`).bind(...binds).run();
}
async function addApiUserLimits(db, apiUserId, { msgLimit, imgLimit } = {}) {
  const sets = [], binds = [];
  if (msgLimit) { sets.push("msg_limit=msg_limit+?"); binds.push(Math.max(0, Number(msgLimit)||0)); }
  if (imgLimit) { sets.push("img_limit=img_limit+?"); binds.push(Math.max(0, Number(imgLimit)||0)); }
  if (!sets.length) return;
  binds.push(apiUserId);
  await db.prepare(`UPDATE api_users SET ${sets.join(",")} WHERE id=?`).bind(...binds).run();
}

function apiUserLimitsSnapshot(u) {
  return { msgUsed: u.msg_used||0, msgLimit: u.msg_limit||0, imgUsed: u.img_used||0, imgLimit: u.img_limit||0 };
}

// ─── getApiKeyAdminStats — full usage snapshot for the whole key ─────────
// Triggered when a caller passes userId:"admin" (see handleApiChat) — gives
// the 3rd-party app a way to check its own key's overall consumption without
// needing the admin panel.
async function getApiKeyAdminStats(db, keyId) {
  const [key, userCountRow] = await Promise.all([
    db.prepare(`SELECT msg_limit,img_limit,msg_used,img_used,active,expires_at FROM api_keys WHERE id=?`).bind(keyId).first(),
    db.prepare(`SELECT COUNT(*) AS c FROM api_users WHERE key_id=?`).bind(keyId).first(),
  ]);
  return {
    msgUsed: key?.msg_used ?? 0, msgLimit: key?.msg_limit ?? 0,
    imgUsed: key?.img_used ?? 0, imgLimit: key?.img_limit ?? 0,
    userCount: userCountRow?.c ?? 0,
    active: !!key?.active, expiresAt: key?.expires_at ?? null,
  };
}

async function setApiUserPrompt(db, apiUserId, prompt) {
  await db.prepare(`UPDATE api_users SET system_prompt=? WHERE id=?`).bind(prompt?.trim() || null, apiUserId).run();
}

async function loadApiHistory(db, apiUserId, maxItems) {
  const r = await db.prepare(
    `SELECT role,content FROM api_messages WHERE api_user_id=? ORDER BY id DESC LIMIT ?`
  ).bind(apiUserId, maxItems).all();
  return (r.results || []).reverse(); // chronological order
}

async function appendApiMessage(db, apiUserId, role, content) {
  await db.prepare(`INSERT INTO api_messages(api_user_id,role,content,created_at) VALUES(?,?,?,?)`)
    .bind(apiUserId, role, content, new Date().toISOString()).run();
}

async function trimApiHistory(db, apiUserId, keep) {
  // keep only the most recent `keep` rows for this api_user (cheap memory cap)
  await db.prepare(`
    DELETE FROM api_messages WHERE api_user_id=? AND id NOT IN (
      SELECT id FROM api_messages WHERE api_user_id=? ORDER BY id DESC LIMIT ?
    )`).bind(apiUserId, apiUserId, keep).run();
}

async function clearApiUserMemory(db, apiUserId) {
  await db.prepare(`DELETE FROM api_messages WHERE api_user_id=?`).bind(apiUserId).run();
}

async function resolveApiSystemPrompt(db, apiUser, requestPrompt) {
  if (requestPrompt?.trim()) return requestPrompt.trim();
  if (apiUser?.system_prompt?.trim()) return apiUser.system_prompt.trim();
  const gc = await getGC(db);
  if (gc.apiDefaultPrompt?.trim()) return gc.apiDefaultPrompt.trim();
  return C.API_FALLBACK_PROMPT;
}

// ─── callGeminiSimple — Gemini call decoupled from Telegram/chat memory ──
// Same key-rotation/retry machinery as callGemini, but the system prompt and
// `contents` are passed in directly instead of being resolved from a chatId.
async function callGeminiSimple(km, contents, sysPrompt, mediaType, useWebSearch=false, textOnly=false) {
  const timeout = _geminiTimeout(mediaType, useWebSearch);
  const payload = _buildGeminiPayload(contents, sysPrompt, useWebSearch, textOnly);
  const maxAttempts = useWebSearch ? Math.min(km.keys.length, 2) : km.keys.length * 2;
  const gapMs       = useWebSearch ? 400 : 1000;
  let lastError = null;
  for (let a = 0; a < maxAttempts; a++) {
    const key = km.cur(), name = km.curName();
    if (!key) { km._next(); continue; }
    const { result, err } = await _callGeminiKey(km, name, key, payload, timeout, useWebSearch);
    if (result) return result;
    lastError = err;
    await sleep(gapMs);
  }
  console.error("[Gemini/api] all keys exhausted:", lastError);
  return null;
}

// ─── CORS for the external API surface (/api/chat, /api/tts, /api/stt only —
// deliberately NOT applied to /admin or /app, which rely on same-origin
// session/password auth and shouldn't be opened to arbitrary origins).
// Gating is per api_key (see cors_enabled column + admin panel API Keys
// tab), because "one api_key == one external app" — one 3rd-party dev's
// browser integration shouldn't force CORS open (or closed) for everyone
// else's key. Preflight (OPTIONS) requests carry no API key at all, so they
// always get a permissive answer; the real gate is on the actual response —
// if a key has CORS disabled, the JSON still comes back fine for
// server-to-server callers, a browser just won't be able to read it
// cross-origin. ─────────────────────────────────────────────────────────
function _corsHeaders() {
  return {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type, Authorization, X-API-Key, x-api-key",
    "Access-Control-Max-Age": "86400",
  };
}
function withCors(resp, enabled = true) {
  if (!enabled) return resp;
  const headers = new Headers(resp.headers);
  const c = _corsHeaders();
  for (const k in c) headers.set(k, c[k]);
  return new Response(resp.body, { status: resp.status, headers });
}

// ─── handleApiChat — POST /api/chat ───────────────────────────────────────
// Body: {
//   userId?: string,            // your app's own user id — omit for a shared default user
//                                // special value "admin" => returns whole-key usage stats, no model call
//   message?: string,           // text input
//   imageBase64?, imageMime?,   // optional image input (vision)
//   audioBase64?, audioMime?,   // optional audio input (Gemini hears/understands it directly)
//   transcribeAudio?: boolean,  // also run audioBase64 through Whisper STT and
//                                // return the raw transcript alongside the reply
//   voiceReply?: boolean,       // synthesize the text reply to speech (Aura-1,
//                                // same TTS engine as the Telegram bot) and
//                                // return it as audio — no extra quota cost
//   voiceLang?: string,         // source language of the reply text for the TTS
//                                // translation step; default "auto" (English
//                                // text is sent through untouched either way)
//   systemPrompt?: string,      // one-off override for this call
//   setSystemPrompt?: string,   // persist a prompt for this userId going forward
//   resetMemory?: boolean,      // wipe this userId's history before answering
//   memory?: boolean,           // default true — set false to not use/save history
//   setLimits?: {msgLimit?,imgLimit?},  // absolute — replace this user's caps
//   addLimits?: {msgLimit?,imgLimit?},  // additive — top up this user's caps (e.g. renewal)
// }
// setLimits/addLimits/setSystemPrompt/resetMemory are account-management —
// they're applied and answered immediately, no model call, no quota spent.
// Response: { ok:true, reply, imageBase64?, imageMime?, audioBase64?, audioMime?, voiceNote?, transcript?, usage:{...} }
// Admin response: { ok:true, admin:true, usage:{ msgUsed,msgLimit,imgUsed,imgLimit,userCount } }
// CORS: every response carries Access-Control-* headers unless this key has
// cors_enabled=0 (see admin panel API Keys tab) — see the CORS block above.
async function handleApiChat(request, env, url) {
  let corsEnabled = true;
  const J = (d, s = 200) => withCors(jr(d, s), corsEnabled);

  if (request.method !== "POST") return J({ ok:false, error:"method not allowed" }, 405);
  if (!env.NIKI_DB) return J({ ok:false, error:"no db" }, 500);
  const db = env.NIKI_DB;
  await initDB(db);

  const rawKey = getApiKeyFromRequest(request, url);
  const auth = await checkAndConsumeApiKey(db, rawKey);
  corsEnabled = auth.corsEnabled !== false;
  if (!auth.ok) return J({ ok:false, error: auth.error }, auth.status);

  let body = {};
  try { body = await request.json(); } catch { return J({ ok:false, error:"invalid json body" }, 400); }

  const {
    userId: userIdIn = "default", message = "", systemPrompt = null, setSystemPrompt = null,
    imageBase64 = null, imageMime = null, audioBase64 = null, audioMime = null,
    resetMemory = false, memory = true, setLimits = null, addLimits = null,
    transcribeAudio = false, voiceReply = false, voiceLang = "auto",
  } = body;

  // ─── input validation — done BEFORE anything is written/charged ──────────
  if (userIdIn !== null && typeof userIdIn !== "string" && typeof userIdIn !== "number")
    return J({ ok:false, error:"userId must be a string or number" }, 400);
  const userId = String(userIdIn ?? "").trim() || "default";
  if (message != null && typeof message !== "string")
    return J({ ok:false, error:"message must be a string" }, 400);
  if (message && message.length > API_MAX_MESSAGE_CHARS)
    return J({ ok:false, error:`message too long (max ${API_MAX_MESSAGE_CHARS} characters)` }, 413);
  if ((imageBase64 && (typeof imageBase64 !== "string" || imageBase64.length > API_MAX_MEDIA_B64)) ||
      (audioBase64 && (typeof audioBase64 !== "string" || audioBase64.length > API_MAX_MEDIA_B64)))
    return J({ ok:false, error:"imageBase64/audioBase64 must be a base64 string of at most ~10MB" }, 413);
  if (systemPrompt != null && (typeof systemPrompt !== "string" || systemPrompt.length > API_MAX_PROMPT_CHARS))
    return J({ ok:false, error:`systemPrompt must be a string of at most ${API_MAX_PROMPT_CHARS} characters` }, 400);
  if (setSystemPrompt != null && (typeof setSystemPrompt !== "string" || setSystemPrompt.length > API_MAX_PROMPT_CHARS))
    return J({ ok:false, error:`setSystemPrompt must be a string of at most ${API_MAX_PROMPT_CHARS} characters` }, 400);

  // ─── reserved userId "admin" — key-wide usage report, doesn't touch the model ──
  if (String(userId).trim().toLowerCase() === "admin") {
    const stats = await getApiKeyAdminStats(db, auth.keyId);
    return J({ ok:true, admin:true, usage:stats });
  }

  const isManagementOnly = setSystemPrompt !== null || resetMemory || setLimits || addLimits;
  // a normal call with nothing to answer is rejected before a user row is created
  if (!isManagementOnly && !message?.trim() && !imageBase64 && !audioBase64)
    return J({ ok:false, error:"missing message/imageBase64/audioBase64" }, 400);

  const apiUser = await getOrCreateApiUser(db, auth.keyId, userId);

  // ─── account-management calls — applied immediately, no model/quota cost ──
  if (isManagementOnly) {
    if (setSystemPrompt !== null) await setApiUserPrompt(db, apiUser.id, setSystemPrompt);
    if (resetMemory) await clearApiUserMemory(db, apiUser.id);
    if (setLimits) await setApiUserLimits(db, apiUser.id, setLimits);
    if (addLimits) await addApiUserLimits(db, apiUser.id, addLimits);
    const fresh = await db.prepare(`SELECT msg_limit,img_limit,msg_used,img_used FROM api_users WHERE id=?`).bind(apiUser.id).first();
    return J({ ok:true, userId: String(userId), limits: apiUserLimitsSnapshot(fresh) });
  }

  // every real call costs one "msg" unit (covers a text-only reply or a vision/audio
  // read) — both this user's own cap and the key's overall pool must have room
  const msgQuota = await consumeApiQuota(db, auth.keyId, apiUser.id, "msg");
  if (!msgQuota.allowed)
    return J({ ok:false, error: msgQuota.reason === "user_limit" ? "user message limit reached" : "key message limit reached" }, 429);
  apiUser.msg_used = (apiUser.msg_used||0) + 1;
  // the unit is given back if the model never produced an answer
  const refundMsg = () => Promise.all([refundApiTypeQuota(db,"api_users",apiUser.id,"msg"), refundApiTypeQuota(db,"api_keys",auth.keyId,"msg")]);

  const gc = await getGC(db);
  const sysPrompt = await resolveApiSystemPrompt(db, apiUser, systemPrompt);
  const maxHist = Math.max(0, Number(gc.apiMaxHistory) || C.API_MAX_HISTORY);

  const history = memory ? await loadApiHistory(db, apiUser.id, maxHist) : [];
  const contents = history.map(h => ({ role: h.role, parts: [{ text: h.content }] }));

  const userParts = [];
  let mediaType = "text";
  if (imageBase64) { userParts.push({ inline_data: { mime_type: imageMime || "image/jpeg", data: imageBase64 } }); mediaType = "image"; }
  if (audioBase64) { userParts.push({ inline_data: { mime_type: audioMime || "audio/ogg", data: audioBase64 } }); mediaType = "audio"; }
  if (message?.trim()) userParts.push({ text: message.trim() });
  contents.push({ role: "user", parts: userParts });

  const km = await KeyManager.create(env, db);
  if (!km.keys.length) { await refundMsg(); return J({ ok:false, error:"no model keys configured" }, 500); }

  let result = null;
  try { result = await callGeminiSimple(km, contents, sysPrompt, mediaType, false); }
  catch (e) { console.error("[api/chat model]", e?.message); }
  if (!result) { await refundMsg(); return J({ ok:false, error:"model request failed" }, 502); }

  // ─── image generation (function call) — each image spends a separate "img"
  // unit; if the user/key is out of image quota that one image is skipped but
  // the text reply still goes through (same behaviour as the Telegram bot) ──
  let imageOut = null;
  const imgCall   = result.functionCalls?.find(f => f.name === "generate_image");
  const multiCall = result.functionCalls?.find(f => f.name === "generate_images");
  const imgGen = new ImageGen(env);
  if (multiCall?.args?.images?.length) {
    const reqs = multiCall.args.images.slice(0, C.HARD_CAP_MULTI_PHOTO);
    const images = [];
    for (const req of reqs) {
      const q = await consumeApiQuota(db, auth.keyId, apiUser.id, "img");
      if (!q.allowed) break;
      const r = await imgGen.generate(req.prompt);
      if (r.ok) { images.push({ imageBase64: arrayBufferToBase64(r.buffer), imageMime: r.mimeType, caption: req.caption||null }); apiUser.img_used = (apiUser.img_used||0)+1; }
      else await Promise.all([refundApiTypeQuota(db,"api_users",apiUser.id,"img"), refundApiTypeQuota(db,"api_keys",auth.keyId,"img")]);
    }
    if (images.length) imageOut = { images };
  } else if (imgCall?.args?.prompt) {
    const q = await consumeApiQuota(db, auth.keyId, apiUser.id, "img");
    if (q.allowed) {
      const r = await imgGen.generate(imgCall.args.prompt);
      if (r.ok) { imageOut = { imageBase64: arrayBufferToBase64(r.buffer), imageMime: r.mimeType }; apiUser.img_used = (apiUser.img_used||0)+1; }
      else await Promise.all([refundApiTypeQuota(db,"api_users",apiUser.id,"img"), refundApiTypeQuota(db,"api_keys",auth.keyId,"img")]);
    }
  }

  // an empty model turn is never stored (it would poison the next request's history)
  const modelTurn = result.text || (imageOut ? "[image]" : "");
  if (memory && modelTurn) {
    await appendApiMessage(db, apiUser.id, "user", message?.trim() || `[${mediaType}]`);
    await appendApiMessage(db, apiUser.id, "model", modelTurn);
    await trimApiHistory(db, apiUser.id, maxHist * 2);
  }

  // ─── transcribeAudio (optional) — the audioBase64 above already went to
  // Gemini directly (it understands audio natively), this is a separate,
  // explicit transcript via Whisper for callers who want the raw words the
  // user said, independent of/alongside the model's reply. Best-effort: a
  // failure here never blocks the actual chat reply. ───────────────────────
  let transcript = null;
  if (transcribeAudio && audioBase64 && env.AI) {
    try {
      const stt = await withTimeout(env.AI.run("@cf/openai/whisper-large-v3-turbo", { audio: audioBase64 }), 25_000);
      transcript = stt?.text?.trim() || null;
    } catch (e) { console.error("[api/chat transcribeAudio]", e.message); }
  }

  // ─── voiceReply (optional) — synthesizes the text reply to speech with the
  // same VoiceGen engine (Aura-1 → MeloTTS fallback) the Telegram bot uses.
  // Piggybacks on the "msg" unit already consumed above — no extra quota
  // cost. Best-effort: a TTS failure never blocks the text reply. ──────────
  let voiceOut = null;
  if (voiceReply && result.text?.trim()) {
    try {
      const voiceGen = new VoiceGen(env);
      const v = await voiceGen.generate(result.text, voiceLang || "auto", true);
      if (v.ok) voiceOut = { audioBase64: arrayBufferToBase64(v.buffer), audioMime: v.mimeType, voiceNote: !!v.voiceNote };
      else console.error("[api/chat voiceReply]", v.error);
    } catch (e) { console.error("[api/chat voiceReply]", e.message); }
  }

  return J({
    ok: true,
    reply: result.text || "",
    ...(imageOut ? imageOut : {}),
    ...(voiceOut ? voiceOut : {}),
    ...(transcript ? { transcript } : {}),
    usage: apiUserLimitsSnapshot(apiUser),
  });
}


// ─── handleApiTts — POST /api/tts — standalone text-to-speech ─────────────
// Body: { userId?: string, text: string, lang?: string }
// Uses the same VoiceGen engine (Aura-1 → MeloTTS fallback) as the Telegram
// bot / handleApiChat's voiceReply. `lang` is the source language of `text`
// for the pre-synthesis translation step (default "auto"; the engine only
// ever speaks English). Costs 1 "msg" quota unit from the same pool as
// /api/chat — refunded automatically if generation fails.
// Response: { ok:true, audioBase64, audioMime, voiceNote, usage:{...} }
async function handleApiTts(request, env, url) {
  let corsEnabled = true;
  const J = (d, s = 200) => withCors(jr(d, s), corsEnabled);

  if (request.method !== "POST") return J({ ok:false, error:"method not allowed" }, 405);
  if (!env.NIKI_DB) return J({ ok:false, error:"no db" }, 500);
  const db = env.NIKI_DB;
  await initDB(db);

  const rawKey = getApiKeyFromRequest(request, url);
  const auth = await checkAndConsumeApiKey(db, rawKey);
  corsEnabled = auth.corsEnabled !== false;
  if (!auth.ok) return J({ ok:false, error: auth.error }, auth.status);

  let body = {};
  try { body = await request.json(); } catch { return J({ ok:false, error:"invalid json body" }, 400); }
  const { userId: userIdIn = "default", text = "", lang = "auto" } = body;
  if (userIdIn !== null && typeof userIdIn !== "string" && typeof userIdIn !== "number")
    return J({ ok:false, error:"userId must be a string or number" }, 400);
  const userId = String(userIdIn ?? "").trim() || "default";
  if (typeof text !== "string" || !text.trim()) return J({ ok:false, error:"missing text" }, 400);
  if (text.length > 5000) return J({ ok:false, error:"text too long (max 5000 characters)" }, 413);

  const apiUser = await getOrCreateApiUser(db, auth.keyId, userId);
  const q = await consumeApiQuota(db, auth.keyId, apiUser.id, "msg");
  if (!q.allowed)
    return J({ ok:false, error: q.reason === "user_limit" ? "user message limit reached" : "key message limit reached" }, 429);
  apiUser.msg_used = (apiUser.msg_used||0) + 1;

  const voiceGen = new VoiceGen(env);
  const v = await voiceGen.generate(text, lang || "auto", true);
  if (!v.ok) {
    await Promise.all([refundApiTypeQuota(db,"api_users",apiUser.id,"msg"), refundApiTypeQuota(db,"api_keys",auth.keyId,"msg")]);
    return J({ ok:false, error: v.error || "voice generation failed" }, 502);
  }
  return J({
    ok: true,
    audioBase64: arrayBufferToBase64(v.buffer),
    audioMime: v.mimeType,
    voiceNote: !!v.voiceNote,
    usage: apiUserLimitsSnapshot(apiUser),
  });
}

// ─── handleApiStt — POST /api/stt — standalone speech-to-text ─────────────
// Body: { userId?: string, audioBase64: string, audioMime?: string }
// Same Whisper pipeline as the Mini App's stt_transcribe/pronunciation
// grading. Costs 1 "msg" quota unit from the same pool as /api/chat —
// refunded automatically if transcription fails.
// Response: { ok:true, transcript, usage:{...} }
async function handleApiStt(request, env, url) {
  let corsEnabled = true;
  const J = (d, s = 200) => withCors(jr(d, s), corsEnabled);

  if (request.method !== "POST") return J({ ok:false, error:"method not allowed" }, 405);
  if (!env.NIKI_DB) return J({ ok:false, error:"no db" }, 500);
  const db = env.NIKI_DB;
  await initDB(db);

  const rawKey = getApiKeyFromRequest(request, url);
  const auth = await checkAndConsumeApiKey(db, rawKey);
  corsEnabled = auth.corsEnabled !== false;
  if (!auth.ok) return J({ ok:false, error: auth.error }, auth.status);

  let body = {};
  try { body = await request.json(); } catch { return J({ ok:false, error:"invalid json body" }, 400); }
  const { userId: userIdIn = "default", audioBase64 = "" } = body;
  if (userIdIn !== null && typeof userIdIn !== "string" && typeof userIdIn !== "number")
    return J({ ok:false, error:"userId must be a string or number" }, 400);
  const userId = String(userIdIn ?? "").trim() || "default";
  if (!audioBase64 || typeof audioBase64 !== "string") return J({ ok:false, error:"missing audioBase64" }, 400);
  if (audioBase64.length > API_MAX_MEDIA_B64) return J({ ok:false, error:"audioBase64 too large (max ~10MB)" }, 413);
  if (!env.AI) return J({ ok:false, error:"AI binding not configured" }, 500);

  const apiUser = await getOrCreateApiUser(db, auth.keyId, userId);
  const q = await consumeApiQuota(db, auth.keyId, apiUser.id, "msg");
  if (!q.allowed)
    return J({ ok:false, error: q.reason === "user_limit" ? "user message limit reached" : "key message limit reached" }, 429);
  apiUser.msg_used = (apiUser.msg_used||0) + 1;

  try {
    const stt = await withTimeout(env.AI.run("@cf/openai/whisper-large-v3-turbo", { audio: audioBase64 }), 25_000);
    const transcript = stt?.text?.trim() || "";
    return J({ ok:true, transcript, usage: apiUserLimitsSnapshot(apiUser) });
  } catch (e) {
    await Promise.all([refundApiTypeQuota(db,"api_users",apiUser.id,"msg"), refundApiTypeQuota(db,"api_keys",auth.keyId,"msg")]);
    return J({ ok:false, error: e.message || "transcription failed" }, 502);
  }
}


// ═══════════════════════════════════════════════════════════════
// § 4b  MEMORY SYSTEM (Short-term + Long-term)
// ═══════════════════════════════════════════════════════════════
// @FILE-SPLIT → despite the header, this section actually holds four
// distinct concerns that grew together over time:
//   src/memory.js  ← archiveMsg/_trimArchive/shortTermMemorySnippet/
//                     longTermMemorySearch/_attachMemory/invalidateMemCache
//                     (the actual "memory system") PLUS getPromptMode/
//                     setPromptMode/getTempPrompt/saveTempPrompt/
//                     deleteTempPrompt/getContextualPrompt/
//                     saveContextualPrompt/_resolveBasePrompt/
//                     resolveSystemPrompt. Prompt-modes ends up here rather
//                     than admin.js on purpose: resolveSystemPrompt runs on
//                     EVERY message (not just admin-triggered ones), AND
//                     it's what the Mini App's own "settings" custom-persona
//                     feature reuses (§ 16) — putting it in admin.js would
//                     mean miniapp.js has to import from admin.js, which is
//                     a stranger dependency than miniapp.js → memory.js.
//   src/admin.js   ← makeInviteCode/getOrCreateInviteCode/processReferral/
//                     getInviteesList/grantReward/autoApplyInviteeReward
//                     (referral-program management) AND getAllUsers/
//                     getPendingGroups/getApprovedGroups/removePending/
//                     setUserLimitsAdmin (admin-panel-facing listing/
//                     editing) — both genuinely only touched via the admin
//                     panel, unlike prompt-modes above.
// Both depend on: C, kv, getGC.
// Short-term memory (loadHistory/archiveMsg) for immediate reply context,
// long-term per-user/per-chat memory for recall across sessions. Changing the
// storage format or KV keys here can make existing users' memories
// unreadable — consider migrating old data before changing the schema.

/**
 * archiveMsg — save to long-term memory with user_id
 * This function now also takes user_id, for per-user search
 */
// ─── _trimArchive — keep only the MAX_ARCHIVE most important rows ──
async function _trimArchive(db, chatId) {
  await db.prepare(`
    DELETE FROM archive WHERE chat_id=? AND id IN (
      SELECT id FROM archive WHERE chat_id=? ORDER BY importance ASC, id ASC
      LIMIT MAX(0,(SELECT COUNT(*) FROM archive WHERE chat_id=?)-?)
    )
  `).bind(chatId, chatId, chatId, C.MAX_ARCHIVE).run().catch(()=>{});
}

async function archiveMsg(db, chatId, userId, username, text, msgId, mediaType=null, importance=null) {
  try {
    const imp = importance ?? scoreImportance(text, mediaType);
    // INSERT OR IGNORE: duplicate msg_id is silently skipped (no double-writes)
    await db.prepare(`
      INSERT OR IGNORE INTO archive(chat_id,user_id,username,content,media_type,msg_id,importance,created_at)
      VALUES(?,?,?,?,?,?,?,?)
    `).bind(chatId, userId||null, username, text||"[no text]", mediaType||null, msgId||null, imp, new Date().toISOString()).run();
    await _trimArchive(db, chatId);
  } catch {}
}

/**
 * shortTermMemorySnippet — per-chat short-term memory
 * Cache: KV with a short TTL
 * Output: condensed text from the last N interactions
 */
async function shortTermMemorySnippet(env, db, chatId, maxItems=C.SHORT_MEM_ITEMS) {
  // check cache first
  const cached = await kv.getMemCache(env, "short", chatId);
  if (cached) return cached;

  const rows = await db.prepare(`
    SELECT role, username, content, created_at
    FROM history
    WHERE chat_id=?
    ORDER BY id DESC
    LIMIT ?
  `).bind(chatId, maxItems * 2).all();

  const items = (rows.results||[])
    .reverse()
    .map(r => {
      const who = r.role === "model" ? "Assistant" : `@${r.username||"user"}`; // neutral label — never leak a fixed bot name into a custom persona
      const txt = (r.content||"").slice(0, 120).replace(/\n+/g," ");
      return `${who}: ${txt}`;
    });

  let snippet = items.join("\n");
  // truncate if it exceeds the limit
  if (snippet.length > C.SHORT_MEM_MAX_CHARS) {
    snippet = snippet.slice(-C.SHORT_MEM_MAX_CHARS);
    // start from the beginning of a line
    const nl = snippet.indexOf("\n");
    if (nl > 0) snippet = snippet.slice(nl+1);
  }

  await kv.setMemCache(env, "short", chatId, snippet);
  return snippet;
}

/**
 * longTermMemorySearch — per-user per-chat long-term memory
 * Search in archive_fts with FTS5 MATCH (optimized)
 * Fallback: LIKE if FTS5 returned no results
 * Cache: KV with a short TTL (per user per chat)
 */
// ─── _ftsSearchArchive — FTS5 search with LIKE fallback (extracted helper) ──
async function _ftsSearchArchive(db, ftsQuery, words, chatId, userId, limit) {
  const results = [];

  // per-user FTS5 search
  if (userId) {
    try {
      const r = await db.prepare(`
        SELECT a.username, a.content, a.created_at
        FROM archive_fts f
        JOIN archive a ON a.id = f.rowid
        WHERE f.archive_fts MATCH ?
          AND a.chat_id = ?
          AND a.user_id = ?
        ORDER BY rank, a.id DESC
        LIMIT ?
      `).bind(ftsQuery, chatId, userId, limit).all();
      results.push(...(r.results||[]));
    } catch(e) {
      console.warn("[FTS5] user query failed, LIKE fallback:", e.message);
      for (const word of words.slice(0, 3)) {
        const r = await db.prepare(`
          SELECT username, content, created_at FROM archive
          WHERE chat_id=? AND user_id=? AND content LIKE ?
          ORDER BY id DESC LIMIT ?
        `).bind(chatId, userId, `%${word}%`, limit).all();
        results.push(...(r.results||[]));
      }
    }
  }

  // general chat FTS5 search (when per-user results are sparse)
  if (results.length < 2) {
    try {
      const r = await db.prepare(`
        SELECT a.username, a.content, a.created_at
        FROM archive_fts f
        JOIN archive a ON a.id = f.rowid
        WHERE f.archive_fts MATCH ?
          AND a.chat_id = ?
        ORDER BY rank, a.importance DESC, a.id DESC
        LIMIT ?
      `).bind(ftsQuery, chatId, limit).all();
      results.push(...(r.results||[]));
    } catch(e) {
      console.warn("[FTS5] general query failed, LIKE fallback:", e.message);
      for (const word of words.slice(0, 3)) {
        const r = await db.prepare(`
          SELECT username, content, created_at FROM archive
          WHERE chat_id=? AND content LIKE ?
          ORDER BY importance DESC, id DESC LIMIT ?
        `).bind(chatId, `%${word}%`, limit).all();
        results.push(...(r.results||[]));
      }
    }
  }

  return results;
}

// ─── _dedupeAndFormat — dedup archive rows and format as snippet ──
function _dedupeAndFormat(results, limit, maxChars) {
  const seen = new Set();
  const deduped = results.filter(r => {
    const key = (r.content||"").slice(0, 60);
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  }).slice(0, limit);

  const items = deduped.map(r => {
    const txt = (r.content||"").slice(0, 100).replace(/\n+/g, " ");
    return `@${r.username||"user"}: ${txt}`;
  });

  let snippet = items.join("\n");
  if (snippet.length > maxChars) snippet = snippet.slice(0, maxChars);
  return snippet;
}

// ─── _longTermCacheKey — query-aware cache key (fixes stale cache per message) ──
function _longTermCacheKey(userId, chatId, queryFingerprint) {
  return `mem:long:${userId}:${chatId}:${queryFingerprint}`;
}

async function longTermMemorySearch(env, db, chatId, userId, query, limit=C.LONG_MEM_ITEMS) {
  if (!query?.trim()) return "";

  const words = query.trim().split(/\s+/).slice(0, 8).filter(w => w.length > 1);
  // fingerprint: first 3 significant words, lowercased — short enough for a KV key
  const queryFingerprint = words.slice(0, 3).join("_").toLowerCase().replace(/[^a-z0-9_\u0600-\u06ff]/g, "") || "any";
  const cacheKey = _longTermCacheKey(userId, chatId, queryFingerprint);

  const cached = await kv.get(env, cacheKey, false);
  if (cached) return cached;

  if (!words.length) return "";

  const ftsQuery = words.map(w => `"${w.replace(/"/g, '""')}"`).join(" OR ");
  const results = await _ftsSearchArchive(db, ftsQuery, words, chatId, userId, limit);
  const snippet = _dedupeAndFormat(results, limit, C.LONG_MEM_MAX_CHARS);

  await kv.set(env, cacheKey, snippet, C.MEM_CACHE_TTL);
  return snippet;
}

/**
 * invalidateMemCache — invalidate the cache when a new message arrives
 * only clears short-term (long-term expires on its own via TTL)
 */
async function invalidateMemCache(env, chatId, userId=null) {
  await kv.del(env, `mem:short:${chatId}`);
  // only clear long-term when we have a userId
  if (userId) await kv.del(env, `mem:long:${userId}:${chatId}`);
}

/**
 * getMemoryStats — memory stats for a user in a chat
 */
async function getMemoryStats(db, chatId, userId) {
  const [histCnt, archiveCnt, userArchiveCnt] = await Promise.all([
    db.prepare("SELECT COUNT(*) c FROM history WHERE chat_id=?").bind(chatId).first(),
    db.prepare("SELECT COUNT(*) c FROM archive WHERE chat_id=?").bind(chatId).first(),
    userId
      ? db.prepare("SELECT COUNT(*) c FROM archive WHERE chat_id=? AND user_id=?").bind(chatId,userId).first()
      : Promise.resolve({c:0}),
  ]);
  return {
    historyCount: histCnt?.c ?? 0,
    archiveTotal: archiveCnt?.c ?? 0,
    userArchive:  userArchiveCnt?.c ?? 0,
  };
}

// ─── user_facts: structured "who is this person" memory ───────────────────
// upsertUserFact — one row per (user, fact_key); INSERT..ON CONFLICT keeps
// this idempotent and self-correcting (age going from 27→28, job changing,
// etc. just overwrites in place rather than piling up stale rows).
async function upsertUserFact(db, userId, chatId, factKey, factValue) {
  const now = new Date().toISOString();
  try {
    await db.prepare(`
      INSERT INTO user_facts(user_id,fact_key,fact_value,source_chat_id,created_at,updated_at)
      VALUES(?,?,?,?,?,?)
      ON CONFLICT(user_id,fact_key) DO UPDATE SET
        fact_value=excluded.fact_value, source_chat_id=excluded.source_chat_id, updated_at=excluded.updated_at
    `).bind(userId, factKey, factValue, chatId||null, now, now).run();
  } catch (e) { console.error("[upsertUserFact]", e.message); }
}
async function getUserFacts(db, userId) {
  const r = await db.prepare("SELECT fact_key,fact_value,updated_at FROM user_facts WHERE user_id=? ORDER BY fact_key ASC").bind(userId).all();
  return r.results || [];
}
async function deleteUserFact(db, userId, factKey) {
  await db.prepare("DELETE FROM user_facts WHERE user_id=? AND fact_key=?").bind(userId, factKey).run();
}
// userFactsSnippet — formatted for the system prompt. Cached briefly in KV
// (facts change rarely — no need to hit D1 on every single message).
async function userFactsSnippet(env, db, userId) {
  const cacheKey = `mem:facts:${userId}`;
  const cached = await kv.get(env, cacheKey, false);
  if (cached !== null && cached !== undefined) return cached;
  const facts = await getUserFacts(db, userId);
  const snippet = facts.length ? facts.map(f => `${f.fact_key}: ${f.fact_value}`).join("\n") : "";
  await kv.set(env, cacheKey, snippet, C.MEM_CACHE_TTL);
  return snippet;
}
async function invalidateUserFactsCache(env, userId) {
  await kv.del(env, `mem:facts:${userId}`);
}

// ─── extractAndStoreUserFacts — pulls durable identity facts (name, age,
// job, location, preferences, ...) out of a single message via a small,
// separate, low-cost Gemini call (NOT the main reply call — this must
// never add latency or tool-use risk to the actual conversation, so it
// always runs fire-and-forget, after the real reply is already on its way
// to the user; see the call site in _handleTelegramUpdateInner). Best
// effort only: any failure here is silently swallowed, same as archiveMsg.
// A cheap length/heuristic gate keeps this from firing (and costing a
// Gemini call) on every single "ok"/"👍"/sticker-caption style message.
function _looksFactBearing(text) {
  if (!text || text.length < 12) return false;
  // Heuristic only, not a filter for correctness — worst case a
  // fact-bearing message without any of these gets skipped this once and
  // picked up next time the same fact is mentioned; false positives just
  // cost one extra (cheap) Gemini call that returns {}.
  return /\b(من|اسمم|اسم من|سالمه|ساله|سنم|شغلم|کارم|زندگی می.?کنم|متولد|ازدواج|بچه|دانشجو|دانش.?آموز|مهندس|دکتر|my name|i am \d|i'm \d|years old|i work|i live|i study|married|my job)\b/i.test(text);
}
async function extractAndStoreUserFacts(env, db, userId, chatId, text) {
  if (!userId || !_looksFactBearing(text)) return;
  try {
    const km = await KeyManager.create(env, db);
    const key = km.cur();
    if (!key) return;
    const prompt = `Extract durable personal facts about the SPEAKER (not third parties they mention) from this one message, if any are explicitly stated. Only include: name, age, job/occupation, location/city, native or spoken languages, relationship/family status, and clear long-term preferences (favorite things, dietary restrictions, etc). Do NOT guess or infer anything not explicitly said. Reply with ONLY a compact JSON object like {"name":"...","age":"..."} using short lowercase snake_case keys, or {} if nothing qualifies — nothing else, no explanation.\n\nMessage: "${String(text).slice(0,500)}"`;
    const payload = { contents: [{ parts: [{ text: prompt }] }], generationConfig: { temperature: 0.1, maxOutputTokens: 200 } };
    const r = await fetchWithTimeout(geminiUrl(key, km.curModel()), { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) }, 12_000);
    const raw = (await r.json())?.candidates?.[0]?.content?.parts?.[0]?.text || "{}";
    const cleaned = raw.trim().replace(/^```json\s*|^```\s*|```$/g, "");
    let facts = {};
    try { facts = JSON.parse(cleaned); } catch { return; }
    if (!facts || typeof facts !== "object") return;
    const entries = Object.entries(facts).filter(([k,v]) => k && v && String(v).trim() && String(v).trim().length <= 200);
    if (!entries.length) return;
    for (const [k, v] of entries) {
      await upsertUserFact(db, userId, chatId, String(k).slice(0,40), String(v).trim());
    }
    await invalidateUserFactsCache(env, userId);
  } catch (e) { console.error("[extractAndStoreUserFacts]", e.message); }
}


async function getPromptMode(db, chatId) {
  const r = await db.prepare("SELECT mode FROM prompt_modes WHERE chat_id=?").bind(chatId).first();
  return r?.mode ?? 1;
}
async function setPromptMode(db, chatId, mode) {
  await db.prepare("INSERT INTO prompt_modes(chat_id,mode) VALUES(?,?) ON CONFLICT(chat_id) DO UPDATE SET mode=excluded.mode").bind(chatId,mode).run();
}
async function getTempPrompt(db, chatId) {
  const r = await db.prepare("SELECT custom_prompt FROM prompt_modes WHERE chat_id=?").bind(chatId).first();
  return r?.custom_prompt||null;
}
async function saveTempPrompt(db, chatId, prompt) {
  await db.prepare("INSERT INTO prompt_modes(chat_id,mode,custom_prompt) VALUES(?,3,?) ON CONFLICT(chat_id) DO UPDATE SET mode=3,custom_prompt=excluded.custom_prompt").bind(chatId,prompt).run();
}
async function deleteTempPrompt(db, chatId) {
  await db.prepare("UPDATE prompt_modes SET custom_prompt=NULL WHERE chat_id=?").bind(chatId).run();
}
async function getContextualPrompt(db, chatId) {
  const r = await db.prepare("SELECT group_prompt,private_prompt,group_prompt_1,group_prompt_2,private_prompt_1,private_prompt_2 FROM prompt_modes WHERE chat_id=?").bind(chatId).first();
  return {
    groupPrompt:r?.group_prompt||null,
    privatePrompt:r?.private_prompt||null,
    groupPrompt1:r?.group_prompt_1||null,
    groupPrompt2:r?.group_prompt_2||null,
    privatePrompt1:r?.private_prompt_1||null,
    privatePrompt2:r?.private_prompt_2||null,
  };
}
async function saveContextualPrompt(db, chatId, type, prompt) {
  const col = type==="group"?"group_prompt":"private_prompt";
  await db.prepare(`INSERT INTO prompt_modes(chat_id,mode,${col}) VALUES(?,1,?) ON CONFLICT(chat_id) DO UPDATE SET ${col}=excluded.${col}`).bind(chatId,prompt).run();
}
async function saveModePrompts(db, chatId, prompts) {
  await db.prepare(`
    INSERT INTO prompt_modes(chat_id,group_prompt_1,group_prompt_2,private_prompt_1,private_prompt_2)
    VALUES(?,?,?,?,?)
    ON CONFLICT(chat_id) DO UPDATE SET
      group_prompt_1=excluded.group_prompt_1,
      group_prompt_2=excluded.group_prompt_2,
      private_prompt_1=excluded.private_prompt_1,
      private_prompt_2=excluded.private_prompt_2
  `).bind(
    chatId,
    prompts.groupPrompt1 || null,
    prompts.groupPrompt2 || null,
    prompts.privatePrompt1 || null,
    prompts.privatePrompt2 || null,
  ).run();
}

/**
 * resolveSystemPrompt — build the final system prompt with memory
 * Memory is appended as a separate section, not inside the base prompt
 */
// ─── _languageDirective — how the AI chooses its reply language (Setup / Config → Reply language) ──
function _languageDirective(replyLang) {
  if (replyLang === "en") return "🌐 LANGUAGE: Always reply in natural, casual English, even if the user writes in another language — unless they explicitly ask for a different language or you are teaching one.";
  if (replyLang === "fa") return "🌐 LANGUAGE: Always reply in natural, casual conversational Persian (Farsi) in Persian script (می‌دونم، می‌خوام، خوبی), unless the user explicitly asks for a different language or you are teaching one.";
  return "🌐 LANGUAGE: Reply in the same language the user writes in; if it is unclear, use English. For Persian use natural, casual conversational Farsi in Persian script (می‌دونم، می‌خوام، خوبی). For every other language, sound equally natural and casual.";
}
// ─── _nameDirective — what the AI answers when someone asks "what is your name?" ──
function _nameDirective(botName) {
  const n = String(botName || "").replace(/[<>\u0000\r\n]/g, " ").trim().slice(0, 40);
  if (n) return `🪪 NAME: Your name is "${n}". Whenever anyone asks who you are or what your name is, answer that you are ${n}.`;
  return `🪪 NAME: Your default name is "Niki" (Persian: نیکی). Whenever anyone asks who you are or what your name is, say you are Niki — unless the instructions above explicitly give you a different name, in which case use that name.`;
}
// ─── _resolveBasePrompt — pick the right prompt string for this chat/mode ──
function _resolveBasePrompt(mode, ctx, gc, isPrivate, displayName, wsEnabled) {
  // Modes 4/5 are dedicated built-in personas (English teacher / programming
  // assistant) — they don't participate in the admin custom-prompt-override
  // system that modes 1/2 use, so always go straight to buildSystemPrompt.
  // Returns { base, isCustom }: isCustom=true means an admin/user-written
  // system prompt was used and must be respected as-is (no forced name).
  if (mode === 4 || mode === 5) {
    return { base: buildSystemPrompt(mode, displayName, isPrivate, wsEnabled, gc.replyLang, gc.botName), isCustom: false };
  }
  let base = "";
  if (isPrivate) {
    const local  = mode===2 ? ctx.privatePrompt2 : ctx.privatePrompt1;
    const global = mode===2 ? gc.defaultPrivatePrompt2 : gc.defaultPrivatePrompt1;
    if (local?.trim())                          base = local.trim();
    else if (mode===1 && ctx.privatePrompt?.trim()) base = ctx.privatePrompt.trim();
    else if (global?.trim())                    base = global.trim();
  } else {
    const local  = mode===2 ? ctx.groupPrompt2 : ctx.groupPrompt1;
    const global = mode===2 ? gc.defaultGroupPrompt2 : gc.defaultGroupPrompt1;
    if (local?.trim())                          base = local.trim();
    else if (mode===1 && ctx.groupPrompt?.trim())   base = ctx.groupPrompt.trim();
    else if (global?.trim())                    base = global.trim();
  }
  if (base) return { base, isCustom: true };
  return { base: buildSystemPrompt(mode, displayName, isPrivate, wsEnabled, gc.replyLang, gc.botName), isCustom: false };
}

async function resolveSystemPrompt(env, db, chatId, userId, displayName, isPrivate, lastUserMsg="", memEnabled=true, wsEnabled=false) {
  let mode = await getPromptMode(db, chatId);
  // A mode the admin switched off in the panel behaves as Mode 1
  if (mode !== 1 && ((await getGC(db)).disabledModes || []).includes(mode)) mode = 1;

  // mode 3 = one-shot temp prompt — fully custom, respect it as written (no forced botName).
  if (mode === 3) {
    const c = await getTempPrompt(db, chatId);
    if (c?.trim()) {
      const only = c.trim() + "\n\n🪪 IDENTITY: Your name and persona are defined ONLY by the instructions above. Never introduce yourself by any other name.";
      return _attachMemory(env, db, chatId, userId, only, lastUserMsg, memEnabled);
    }
    await setPromptMode(db, chatId, 1); // expired temp prompt → fall back to mode 1
  }

  const [ctx, gc] = await Promise.all([getContextualPrompt(db, chatId), getGC(db)]);
  const resolved = _resolveBasePrompt(mode, ctx, gc, isPrivate, displayName, wsEnabled);
  let basePrompt = resolved.base;
  if (mode !== 4) basePrompt += "\n\n" + _languageDirective(gc.replyLang);
  if (gc.ttsProvider !== "cloudflare") {
    // Google (Gemini TTS) speaks every language natively — lift the English-only rule.
    basePrompt = basePrompt.replace(/- LANGUAGE: the voice engine only speaks English\.[^\n]*/,
      "- LANGUAGE: the voice engine speaks ANY language natively (Persian, German, Arabic, French, Spanish, Turkish, Chinese, Japanese… everything). Put `text` in whatever language the user wants to hear — by default the language you are replying in, or the language they asked for. If the user asks for a Persian/Farsi voice (ویس فارسی، فارسی بگو), `text` MUST be written in Persian script — NEVER translate it to English, and never answer with an English voice to a Persian request. Do NOT translate to English unless the user asked for English. Your visible chat message stays as always." +
      (gc.ttsAutoStyle !== false ? "\n- TONE: you control HOW the voice sounds. Pass `style` to generate_voice with a few English words for the delivery — e.g. 'warm and cheerful', 'whispering', 'sad and slow', 'excited', 'calm storyteller', 'serious' — chosen from what the user asked for (\"با لحن شاد بگو\", \"آروم\", \"غمگین\"…) or from the emotion of the sentence itself. Change it from message to message when the mood changes; omit it only when a neutral voice is right." : "") + _voiceCharactersPromptLine());
  }

  // ── Identity rules ──────────────────────────────────────────────────
  // Custom system prompt (Config → Default private/group prompts, or per-chat):
  //   → use it as-is. Do NOT inject Bot name (e.g. "ممد بات"). If the prompt
  //     says the bot is "سارا", the bot is Sara.
  // No custom prompt (built-in persona):
  //   → inject Bot name from Config → Bot name (empty → "Niki").
  let finalPrompt;
  if (resolved.isCustom) {
    finalPrompt = basePrompt + "\n\n🪪 IDENTITY: Your name and persona are defined ONLY by the system instructions above. Never introduce yourself by any other name (ignore any conflicting name from memory or previous turns).";
  } else {
    finalPrompt = basePrompt + "\n\n" + _nameDirective(gc.botName);
  }
  return _attachMemory(env, db, chatId, userId, finalPrompt, lastUserMsg, memEnabled);
}

/**
 * _attachMemory — append memory to the system prompt
 * Short-term and long-term memory with a defined format
 */
async function _attachMemory(env, db, chatId, userId, basePrompt, lastUserMsg="", memEnabled=true) {
  if (!memEnabled) return basePrompt;
  try {
    const [shortMem, longMem, factsMem] = await Promise.all([
      shortTermMemorySnippet(env, db, chatId),
      longTermMemorySearch(env, db, chatId, userId, lastUserMsg),
      userId ? userFactsSnippet(env, db, userId) : Promise.resolve(""),
    ]);

    let memSection = "";
    if (factsMem?.trim()) {
      memSection += `\n\n🧬 اطلاعات شناخته‌شده درباره‌ی این کاربر:\n${factsMem}`;
    }
    if (longMem?.trim()) {
      memSection += `\n\n📚 حافظه بلندمدت (مکالمات قبلی مرتبط):\n${longMem}`;
    }
    if (shortMem?.trim()) {
      memSection += `\n\n🧠 حافظه کوتاه‌مدت (چند پیام اخیر):\n${shortMem}`;
    }
    if (memSection) {
      memSection += "\n\n(از این اطلاعات فقط برای پیوستگی و زمینه‌ی مکالمه استفاده کن، مستقیم نقل نکن. مهم: اگه تو این حافظه اشاره شده که قبلاً کاری انجام دادی — مثلاً صدا/عکس ساختی یا کوییزی ساختی — این فقط یه سابقه‌ست، نه یه درخواست فعلی؛ هیچ ابزاری (generate_voice، generate_image، create_quiz و…) رو صرفاً به‌خاطر یادآوری یه کار قدیمی دوباره صدا نزن؛ فقط وقتی کاربر تو همین پیام الان واقعاً دوباره همون رو خواست.)";
    }

    return (basePrompt + memSection).trim();
  } catch(e) {
    console.error("[Memory] attach failed:", e.message);
    return basePrompt;
  }
}

// ─── Invite ─────────────────────────────────────────────────────
function makeInviteCode(userId) {
  return (userId%999983).toString(36).toUpperCase() + Math.random().toString(36).slice(2,6).toUpperCase();
}
async function getOrCreateInviteCode(db, userId) {
  const r = await db.prepare("SELECT invite_code FROM users WHERE user_id=?").bind(userId).first();
  if (r?.invite_code) return r.invite_code;
  let code, tries=0;
  do {
    // after 5 deterministic attempts fall back to fully random codes to avoid hash-space collisions
    if (tries < 5) {
      code = makeInviteCode(userId);
    } else {
      code = Math.random().toString(36).slice(2,10).toUpperCase();
    }
    const ex = await db.prepare("SELECT user_id FROM users WHERE invite_code=?").bind(code).first();
    if (!ex) break;
    tries++;
  } while(tries < 15);
  try {
    await db.prepare("UPDATE users SET invite_code=? WHERE user_id=?").bind(code,userId).run();
  } catch(e) {
    // UNIQUE constraint: another concurrent request already set a code — just return theirs
    const fresh = await db.prepare("SELECT invite_code FROM users WHERE user_id=?").bind(userId).first();
    if (fresh?.invite_code) return fresh.invite_code;
  }
  return code;
}
async function processReferral(env, db, newUserId, newUsername, code) {
  if (!code) return null;
  if (((await getGC(db)).disabledPrivate || []).includes("feature:invitereward")) return null;
  const ref = await db.prepare("SELECT * FROM users WHERE invite_code=?").bind(code.toUpperCase()).first();
  if (!ref || ref.user_id === newUserId) return null;
  // Atomic claim: WHERE referred_by IS NULL makes this a single conditional
  // write instead of check-then-act, so two /start ref_CODE calls racing for
  // the same new user (duplicate webhook delivery, a resent update, etc.)
  // can't both see "not yet referred" and both grant the reward. Only the
  // call whose UPDATE actually changed a row proceeds to reward the referrer.
  const claim = await db.prepare("UPDATE users SET referred_by=? WHERE user_id=? AND referred_by IS NULL")
    .bind(ref.user_id, newUserId).run();
  if (!claim?.meta?.changes) return null;
  const gc = await getGC(db);
  if (gc.inviteRewardMsg>0||gc.inviteRewardImg>0||gc.inviteRewardVoice>0) {
    const note = `دعوت @${norm(newUsername)}`;
    await db.batch([
      db.prepare(`UPDATE users SET bonus_msg=bonus_msg+?,bonus_img=bonus_img+?,bonus_voice=bonus_voice+?,remaining_msg=remaining_msg+?,remaining_img=remaining_img+?,remaining_voice=remaining_voice+?,invite_count=invite_count+1,notes=CASE WHEN notes='' THEN ? ELSE notes||' | '||? END WHERE user_id=?`
      ).bind(gc.inviteRewardMsg,gc.inviteRewardImg,gc.inviteRewardVoice,gc.inviteRewardMsg,gc.inviteRewardImg,gc.inviteRewardVoice,note,note,ref.user_id),
      db.prepare("INSERT INTO invites(inviter_id,inviter_name,invitee_id,invitee_name,reward_msg,reward_img,reward_voice,invite_type,created_at) VALUES(?,?,?,?,?,?,?,'link',?)"
      ).bind(ref.user_id,ref.username||"",newUserId,norm(newUsername),gc.inviteRewardMsg,gc.inviteRewardImg,gc.inviteRewardVoice,new Date().toISOString()),
    ]);
    await kv.delLimits(env, ref.user_id);
    return { referrerId:ref.user_id, rewardMsg:gc.inviteRewardMsg, rewardImg:gc.inviteRewardImg, rewardVoice:gc.inviteRewardVoice, referrerName:ref.username };
  }
  return null;
}

async function getInviteesList(db, inviterId) {
  const r = await db.prepare(`
    SELECT invitee_id,invitee_name,reward_msg,reward_img,reward_voice,created_at
    FROM invites
    WHERE inviter_id=? AND invite_type='link' AND invitee_id IS NOT NULL
    ORDER BY id DESC
  `).bind(inviterId).all();
  return r.results||[];
}

async function getAllUsers(db) {
  const r = await db.prepare("SELECT * FROM users ORDER BY user_id").all();
  return r.results||[];
}
async function getPendingGroups(db) {
  const r = await db.prepare("SELECT * FROM groups WHERE pending=1 AND approved=0").all();
  return r.results||[];
}
async function getApprovedGroups(db) {
  const r = await db.prepare(`
    SELECT g.*,p.group_prompt_1,p.group_prompt_2
    FROM groups g
    LEFT JOIN prompt_modes p ON p.chat_id=g.chat_id
    WHERE g.approved=1
  `).all();
  return r.results||[];
}
async function removePending(db, chatId) {
  await db.prepare("UPDATE groups SET pending=0 WHERE chat_id=?").bind(chatId).run();
}
async function grantReward(env, db, userId, bonusMsg, bonusImg, note, inviterName) {
  await db.batch([
    db.prepare(`UPDATE users SET bonus_msg=bonus_msg+?,bonus_img=bonus_img+?,remaining_msg=remaining_msg+?,remaining_img=remaining_img+?,notes=CASE WHEN notes='' THEN ? ELSE notes||' | '||? END WHERE user_id=?`
    ).bind(bonusMsg,bonusImg,bonusMsg,bonusImg,note||"",note||"",userId),
    db.prepare("INSERT INTO invites(inviter_id,inviter_name,reward_msg,reward_img,invite_type,created_at) VALUES(?,?,?,?,'manual',?)"
    ).bind(userId,inviterName||"",bonusMsg,bonusImg,new Date().toISOString()),
  ]);
  await kv.delLimits(env, userId);
}
async function autoApplyInviteeReward(env, db, pending) {
  if (!pending?.requested_by_user_id) return;
  const gc = await getGC(db);
  if (gc.inviteeRewardMsg<=0 && gc.inviteeRewardImg<=0 && gc.inviteeRewardVoice<=0) return;
  const note = `جایزه ثبت گروه: ${pending.group_name||pending.chat_id}`;
  await db.batch([
    db.prepare(`UPDATE users SET bonus_msg=bonus_msg+?,bonus_img=bonus_img+?,bonus_voice=bonus_voice+?,remaining_msg=remaining_msg+?,remaining_img=remaining_img+?,remaining_voice=remaining_voice+?,notes=CASE WHEN notes='' THEN ? ELSE notes||' | '||? END,invite_count=invite_count+1 WHERE user_id=?`
    ).bind(gc.inviteeRewardMsg,gc.inviteeRewardImg,gc.inviteeRewardVoice,gc.inviteeRewardMsg,gc.inviteeRewardImg,gc.inviteeRewardVoice,note,note,pending.requested_by_user_id),
    db.prepare("INSERT INTO invites(inviter_id,inviter_name,chat_id,group_name,reward_msg,reward_img,reward_voice,invite_type,created_at) VALUES(?,?,?,?,?,?,?,'group_register',?)"
    ).bind(pending.requested_by_user_id,pending.requested_by||"",pending.chat_id,pending.group_name||"",gc.inviteeRewardMsg,gc.inviteeRewardImg,gc.inviteeRewardVoice,new Date().toISOString()),
  ]);
  await kv.delLimits(env, pending.requested_by_user_id);
}
async function setUserLimitsAdmin(env, db, userId, lim) {
  const cur = await getUserLimits(env, db, userId);
  const msgLimit    = lim.msgLimit !== undefined ? lim.msgLimit : cur.msgLimit;
  const imgLimit    = lim.imgLimit !== undefined ? lim.imgLimit : cur.imgLimit;
  const voiceLimit  = lim.voiceLimit !== undefined ? lim.voiceLimit : cur.voiceLimit;
  const dailyMsg    = lim.dailyMsgLimit !== undefined ? lim.dailyMsgLimit : cur.dailyMsgLimit;
  const dailyImg    = lim.dailyImgLimit !== undefined ? lim.dailyImgLimit : cur.dailyImgLimit;
  const dailyVoice  = lim.dailyVoiceLimit !== undefined ? lim.dailyVoiceLimit : cur.dailyVoiceLimit;
  const bonusMsg    = lim.bonusMsg !== undefined ? lim.bonusMsg : cur.bonusMsg;
  const bonusImg    = lim.bonusImg !== undefined ? lim.bonusImg : cur.bonusImg;
  const bonusVoice  = lim.bonusVoice !== undefined ? lim.bonusVoice : cur.bonusVoice;
  const remainingMsg = msgLimit + bonusMsg;
  const remainingImg = imgLimit + bonusImg;
  const remainingVoice = voiceLimit + bonusVoice;
  await db.prepare(`
    UPDATE users SET
      msg_limit=?,img_limit=?,voice_limit=?,daily_msg_limit=?,daily_img_limit=?,daily_voice_limit=?,
      bonus_msg=?,bonus_img=?,bonus_voice=?,remaining_msg=?,remaining_img=?,remaining_voice=?
    WHERE user_id=?
  `).bind(msgLimit,imgLimit,voiceLimit,dailyMsg,dailyImg,dailyVoice,bonusMsg,bonusImg,bonusVoice,remainingMsg,remainingImg,remainingVoice,userId).run();
  await kv.delLimits(env, userId);
}

// ═══════════════════════════════════════════════════════════════
// § 5  PERMISSIONS
// ═══════════════════════════════════════════════════════════════
// @FILE-SPLIT → src/config.js (grouped with § 2/§ 3 as "generic helpers")
// getPermLevel/checkAdminForTool. Tiny, self-contained (only needs C + norm,
// both already in config.js per the new plan).
// Levels: USER(0) < ADMIN(1) < LEADER(2) < SUPER(3).
// SUPER always comes from SUPER_ADMIN_IDS / the panel superIds and cannot be overridden.
// Any change to this function affects every isAdmin/isLeader/isSuper check
// across the whole bot — modify with care.
async function getPermLevel(db, userId, username, chatId) {
  const u = norm(username);
  await getGC(db).catch(() => {}); // refreshes the extra super-admin IDs
  if (isSuperId(userId)) return C.PERM.SUPER;
  // Private chats have no admin system: only super admins get elevated rights there.
  if (chatId > 0) return C.PERM.USER;
  if (!u) return C.PERM.USER;
  // a single query instead of two separate ones (getLeader + getAdmins) — fewer round-trips to D1
  const row = await db.prepare("SELECT is_leader FROM admins WHERE chat_id=? AND username=?").bind(chatId, u).first();
  if (!row) return C.PERM.USER;
  return row.is_leader ? C.PERM.LEADER : C.PERM.ADMIN;
}

// ─── checkAdminForTool — admin check independent of the model ────────────
// Every admin tool (delete_message, pin_message, etc.) must pass through
// this function before executing. This is a defense layer independent of the model:
// even if the model mistakenly calls the tool for a regular user,
// it gets blocked here and logged.
async function checkAdminForTool(db, userId, username, chatId) {
  const perm = await getPermLevel(db, userId, username, chatId);
  return perm >= C.PERM.ADMIN;
}

// ═══════════════════════════════════════════════════════════════
// § 6  TELEGRAM HELPERS
// ═══════════════════════════════════════════════════════════════
// @FILE-SPLIT → src/webhook.js (merged with § 14 — one file for "everything
// that talks to Telegram", both incoming webhook and outgoing Bot API calls)
// tgUrl/geminiUrl/sendTyping/react/deleteMsg/pinMsg/unpinMsg/unpinAllMsgs/
// _sendChunk/sendMsg — every raw Telegram Bot API call goes through here.
// Depends on: fetchWithTimeout/sleep (config.js). image-gen.js, admin.js,
// and miniapp.js all import from here to actually send anything — keep it
// near the top of this file so it's easy to find inside the bigger webhook.js.
// All HTTP calls to the Telegram Bot API go through here. They must all
// use fetchWithTimeout (not a raw fetch) so a slow Telegram
// endpoint can't leave the whole Worker execution hanging.

const tgUrl    = (env, m) => {
  return `https://api.telegram.org/bot${env.TELEGRAM_BOT_TOKEN}/${m}`;
};
const geminiUrl = (key, model)  => `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${key}`;

async function sendTyping(env, chatId, action="typing") {
  try { await fetchWithTimeout(tgUrl(env,"sendChatAction"),{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({chat_id:chatId,action})}); } catch {}
}

async function react(env, chatId, msgId, emoji) {
  if (env && env.__noReact) return; // admin panel: auto reactions switched off for this chat type
  // Previously this cleared the reaction (`reaction:[]`), slept 300ms, THEN
  // set the real one — two full network round-trips and a third of a
  // second of pure dead time on every single reaction, for no functional
  // benefit: setMessageReaction already REPLACES whatever reaction was
  // there in one call. Worse, that clear-then-set window is exactly what
  // made a reaction look like it "shows up then disappears a few seconds
  // later" whenever this ran more than once close together (e.g. a slow
  // webhook ack causing Telegram to redeliver the same update — see the
  // ctx.waitUntil fix in fetch() below, which was the other half of that
  // same bug). One direct call removes both problems at once.
  try {
    await fetchWithTimeout(tgUrl(env,"setMessageReaction"), {
      method:"POST", headers:{"Content-Type":"application/json"},
      body: JSON.stringify({chat_id:chatId, message_id:msgId, reaction:[{type:"emoji",emoji}]}),
    });
  } catch {}
}

// ─── sendInvoice — sends a Telegram Stars payment invoice ─────────────────
// currency "XTR" = Telegram Stars: no decimal subunits, so amount IS the
// star count directly (unlike real currencies where amount is in the
// smallest unit, e.g. cents). provider_token is left empty — Stars payments
// don't use an external payment provider, Telegram settles them itself.
async function sendInvoice(env, chatId, { title, description, payload, starAmount }) {
  try {
    const r = await fetchWithTimeout(tgUrl(env,"sendInvoice"), {
      method:"POST", headers:{"Content-Type":"application/json"},
      body: JSON.stringify({
        chat_id: chatId,
        title: String(title||"").slice(0,32),
        description: String(description||"").slice(0,255),
        payload: String(payload||"").slice(0,128),
        currency: "XTR",
        prices: [{ label: String(title||"").slice(0,32), amount: Math.max(1, Math.round(Number(starAmount)||1)) }],
        provider_token: "",
      }),
    });
    const j = await r.json();
    // Telegram puts the real reason in `description` on failure (e.g.
    // "Bad Request: PAYMENT_PROVIDER_INVALID" if Stars/Payments isn't
    // enabled for this bot yet via BotFather) — this was previously
    // discarded entirely, so a failed invoice just silently did nothing
    // with zero clue why.
    if (!j.ok) console.error("[sendInvoice] Telegram rejected it:", j.error_code, j.description);
    return j;
  } catch (e) { console.error("[sendInvoice]", e.message); return { ok:false, description: e.message }; }
}
// ─── answerPreCheckoutQuery — MUST be answered within 10s of Telegram
// sending pre_checkout_query, or the payment is auto-cancelled client-side.
// Only place to actually re-validate the purchase (package still exists/
// active, price hasn't changed) before Telegram lets the charge go through.
async function answerPreCheckoutQuery(env, preCheckoutQueryId, ok, errorMessage=null) {
  try {
    await fetchWithTimeout(tgUrl(env,"answerPreCheckoutQuery"), {
      method:"POST", headers:{"Content-Type":"application/json"},
      body: JSON.stringify({ pre_checkout_query_id: preCheckoutQueryId, ok, ...(errorMessage?{error_message:errorMessage}:{}) }),
    });
  } catch {}
}

// ─── scheduleMessageDeletion / sweepPendingMessageDeletions ───────────────
// Generic "delete this message N seconds from now" queue backed by D1 (see
// pending_msg_deletions table) instead of an in-memory setTimeout, since a
// Worker isolate can be recycled long before 2 minutes pass. Swept once a
// minute by the cron trigger, and opportunistically on every webhook so it
// still fires close to on-time even if no cron trigger is configured.
async function scheduleMessageDeletion(db, chatId, messageId, delaySeconds) {
  try {
    const deleteAt = new Date(Date.now() + Math.max(1, delaySeconds) * 1000).toISOString();
    await db.prepare(
      "INSERT INTO pending_msg_deletions(chat_id,message_id,delete_at,created_at) VALUES(?,?,?,?)"
    ).bind(chatId, messageId, deleteAt, new Date().toISOString()).run();
  } catch (e) { console.error("[scheduleMessageDeletion]", e.message); }
}
async function sweepPendingMessageDeletions(env, db) {
  let due;
  try {
    due = await db.prepare(
      "SELECT id,chat_id,message_id FROM pending_msg_deletions WHERE delete_at<=? LIMIT 50"
    ).bind(new Date().toISOString()).all();
  } catch (e) { console.error("[sweepPendingMessageDeletions] query", e.message); return; }
  const rows = due?.results || [];
  if (!rows.length) return;
  for (const row of rows) {
    try {
      await fetchWithTimeout(tgUrl(env,"deleteMessage"), {
        method:"POST", headers:{"Content-Type":"application/json"},
        body: JSON.stringify({ chat_id: row.chat_id, message_id: row.message_id }),
      });
    } catch {}
    // Row is removed either way — if the delete call failed (message already
    // gone, chat blocked the bot, etc.) retrying it forever wouldn't help.
    try { await db.prepare("DELETE FROM pending_msg_deletions WHERE id=?").bind(row.id).run(); } catch {}
  }
}


// ─── answerCallbackQuery — dismiss an inline-button tap's loading spinner ──
// Telegram shows a spinner on a tapped inline button until this is called
// (or ~30s pass, whichever first) — always call it, even on a no-op/denied
// tap, so the button doesn't look stuck. `text`+`showAlert` optionally pop a
// small toast/alert to the user (e.g. a permission-denied notice).
async function answerCallbackQuery(env, callbackQueryId, text=null, showAlert=false) {
  try {
    const r = await fetchWithTimeout(tgUrl(env,"answerCallbackQuery"), {
      method:"POST", headers:{"Content-Type":"application/json"},
      body: JSON.stringify({ callback_query_id: callbackQueryId, ...(text?{text}:{}) , show_alert: showAlert }),
    });
    // Was previously a bare catch{} with zero trace on failure — a button
    // tap whose callback never gets answered looks EXACTLY like "I tap it
    // and nothing happens" client-side (Telegram just stops the spinner
    // with no popup), and there was no way to tell from the logs whether
    // the handler ran, threw, or the Telegram call itself failed.
    if (!r.ok) {
      const body = await r.text().catch(()=> "");
      console.error("[answerCallbackQuery] Telegram rejected it:", r.status, body);
    }
  } catch (e) {
    console.error("[answerCallbackQuery]", e.message);
  }
}

// ─── editMessageText — update an existing message's text/keyboard in place ──
// Used to turn a "pick a mode" button message into its own confirmation
// (e.g. after /mode's inline keyboard is tapped) instead of leaving the
// stale keyboard up and sending a separate new message. replyMarkup=null
// removes the keyboard; omit it to leave the keyboard untouched.
async function editMessageText(env, chatId, msgId, text, replyMarkup=undefined) {
  try {
    const r = await fetchWithTimeout(tgUrl(env,"editMessageText"), {
      method:"POST", headers:{"Content-Type":"application/json"},
      body: JSON.stringify({
        chat_id: chatId, message_id: msgId, text, parse_mode: "HTML",
        ...(replyMarkup !== undefined ? { reply_markup: replyMarkup } : {}),
      }),
    });
    if (!r.ok) {
      const body = await r.text().catch(()=> "");
      console.error("[editMessageText] Telegram rejected it:", r.status, body);
    }
  } catch (e) {
    console.error("[editMessageText]", e.message);
  }
}

// ─── mode picker (used by both /mode with no args AND the inline buttons) ──
const MODE_LABELS = {1:"خود نیکی 🎭",2:"تحلیلی 🧠",3:"سفارشی ✏️",4:"آموزش انگلیسی 🇬🇧",5:"برنامه‌نویسی 💻"};
const MODE_EMOJI  = {1:"🎭",2:"🧠",3:"✏️",4:"🇬🇧",5:"💻"};
function _modeKeyboard(off = []) {
  const rows = [
    [1, { text: "🎭 خود نیکی",        callback_data: "mode:1" }],
    [3, { text: "✏️ پرامپت سفارشی",   callback_data: "mode:3" }],
    [5, { text: "💻 برنامه‌نویسی",     callback_data: "mode:5" }],
    [4, { text: "🇬🇧 آموزش انگلیسی",  callback_data: "mode:4" }],
  ];
  return { inline_keyboard: rows.filter(([m]) => !off.includes(m)).map(([, b]) => [b]) };
}
async function sendModePickerMsg(env, chatId, replyTo, db = null) {
  try {
    const off = db ? ((await getGC(db)).disabledModes || []) : [];
    await fetchWithTimeout(tgUrl(env,"sendMessage"), {
      method:"POST", headers:{"Content-Type":"application/json"},
      body: JSON.stringify({
        chat_id: chatId, reply_to_message_id: replyTo, parse_mode: "HTML",
        text: "🎛️ کدوم مود رو می‌خوای؟",
        reply_markup: _modeKeyboard(off),
      }),
    });
  } catch {}
}

// ─── /lang picker — lets a user pick their own chat's fixed-message
// language (help/limits/errors, see I18N/t()) without the admin panel ────
function _langKeyboard() {
  return { inline_keyboard: [
    [{ text: "🇮🇷 فارسی", callback_data: "lang:fa" }],
    [{ text: "🇬🇧 English", callback_data: "lang:en" }],
  ] };
}
async function sendLangPickerMsg(env, chatId, replyTo) {
  try {
    await fetchWithTimeout(tgUrl(env,"sendMessage"), {
      method:"POST", headers:{"Content-Type":"application/json"},
      body: JSON.stringify({
        chat_id: chatId, reply_to_message_id: replyTo, parse_mode: "HTML",
        text: "🌐 زبان پیام‌های ثابت ربات (راهنما، لیمیت، خطاها) رو انتخاب کن:\n🌐 Choose the language for the bot's fixed messages (help, limits, errors):",
        reply_markup: _langKeyboard(),
      }),
    });
  } catch {}
}
// _applyLang — the ONE place that writes chat_config.lang, shared by the
// /lang text command and the "lang:xx" inline-button callback, same pattern
// as _applyMode/mode:N above.
async function _applyLang(db, chatId, langCode) {
  await setChatConfig(db, chatId, { lang: langCode });
  return langCode === "fa"
    ? "🌐 زبان پیام‌های ثابت ربات فارسی شد."
    : "🌐 Bot's fixed messages are now in English.";
}

// ─── _applyMode — the ONE place that actually switches a chat's persona ──
// Shared by the /mode text command and the "mode:N" inline-button callback
// so both paths behave identically (same DB writes, same history-clear,
// same confirmation copy) — see the callback_query branch in
// _handleTelegramUpdateInner for the button side.
// scope is only meaningful for mode 3 (custom) — see setAwaitPrompt.
async function _applyMode(env, db, chatId, userId, m, scope="custom") {
  if (((await getGC(db)).disabledModes || []).includes(m)) {
    return { emoji: "🚫", text: `🚫 Mode <b>${m}</b> (${MODE_LABELS[m]}) توسط ادمین غیرفعال شده.` };
  }
  if (m === 3) {
    await setPromptMode(db, chatId, 3);
    await setAwaitPrompt(env, db, chatId, userId, scope || "custom");
    await clearHistory(db, chatId);
    return { emoji: MODE_EMOJI[3], text: `✏️ <b>Mode 3 — Custom</b>\nPrompt رو بفرست. لغو: <b>cancel</b>` };
  }
  await setPromptMode(db, chatId, m);
  await deleteTempPrompt(db, chatId);
  await clearHistory(db, chatId);
  return { emoji: MODE_EMOJI[m], text: `✅ Mode <b>${m}</b> (${MODE_LABELS[m]}) فعال شد.` };
}



// ─── deleteMsg — honors Telegram's flood-control retry_after ──────────────
// Root cause of "any chat I told to پاکسازی کن now just errors, others are
// fine": bulkDeleteMessages (behind cleanup_chat and delete_last_messages)
// fires up to MAX_BULK_DELETE=30 deleteMessage calls at ONE chat with only
// ~60ms between them (~16/sec). Telegram's per-chat flood limit is much
// lower than that — once exceeded, Telegram returns 429 with a retry_after
// window for THAT chat_id specifically. The old code ignored 429 entirely
// and kept firing the rest of the loop at the same pace, which can make
// Telegram extend the penalty. Every *other* API call to that same chat
// (including the bot's normal replies right after) then also gets 429'd
// until the window passes — which looks exactly like "this account is
// broken" while unrelated chats (different rate-limit bucket) work fine.
async function deleteMsg(env, chatId, msgId, _retried=false) {
  try {
    const res = await fetchWithTimeout(tgUrl(env,"deleteMessage"),
      {method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({chat_id:chatId,message_id:msgId})});
    if (res.status === 429 && !_retried) {
      const d = await res.json().catch(()=>({}));
      const retryAfter = Math.min(Number(d?.parameters?.retry_after) || 1, 10); // cap the wait, don't stall the whole request
      await sleep(retryAfter * 1000);
      return deleteMsg(env, chatId, msgId, true);
    }
    return res.ok;
  } catch { return false; }
}

async function pinMsg(env, chatId, msgId, disableNotif=false) {
  try {
    const res = await fetchWithTimeout(
      tgUrl(env, "pinChatMessage"),
      {method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({chat_id:chatId,message_id:msgId,disable_notification:disableNotif})}
    );
    const d = await res.json();
    return res.ok ? {ok:true} : {ok:false, error: d.description || `HTTP ${res.status}`};
  } catch(e) { return {ok:false, error: e.message}; }
}

async function unpinMsg(env, chatId, msgId=null) {
  try {
    const body = {chat_id: chatId};
    if (msgId) body.message_id = msgId;
    const res = await fetchWithTimeout(
      tgUrl(env, "unpinChatMessage"),
      {method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)}
    );
    const d = await res.json();
    return res.ok ? {ok:true} : {ok:false, error: d.description || `HTTP ${res.status}`};
  } catch(e) { return {ok:false, error: e.message}; }
}

async function unpinAllMsgs(env, chatId) {
  try {
    const res = await fetchWithTimeout(
      tgUrl(env, "unpinAllChatMessages"),
      {method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({chat_id:chatId})}
    );
    const d = await res.json();
    return res.ok ? {ok:true} : {ok:false, error: d.description || `HTTP ${res.status}`};
  } catch(e) { return {ok:false, error: e.message}; }
}

// ─── _sendChunk — send one text chunk to Telegram ───────────────
// Returns the Telegram message_id of the sent chunk (or null on failure) so
// callers can record it in history — this is what lets cleanup/bulk-delete
// later find and remove the bot's *own* messages, not just the user's.
async function _sendChunk(env, chatId, text, replyTo) {
  const payload = {chat_id: chatId, text, parse_mode: "HTML"};
  if (replyTo) payload.reply_to_message_id = replyTo;
  try {
    const res = await fetchWithTimeout(
      tgUrl(env, "sendMessage"),
      {method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify(payload)}
    );
    const d = await res.json().catch(() => ({}));
    return d?.result?.message_id ?? null;
  } catch(e) { console.error("[sendMsg]", e.message); return null; }
}

/**
 * Sends text to a chat (auto-splitting into multiple Telegram messages if it
 * exceeds the length limit) and returns the message_id of the FIRST chunk —
 * the representative id to record in `history` for this AI turn so it can
 * later be found/deleted by delete_last_messages / cleanup_chat.
 *
 * @returns {Promise<number|null>} message_id of the first sent chunk, or null
 */
async function sendMsg(env, db, chatId, text, replyTo=null) {
  if (!text?.trim()) return null;
  const chunks = splitMsg(text.trim());
  let firstMsgId = null;
  for (let i = 0; i < chunks.length; i++) {
    const mid = await _sendChunk(env, chatId, chunks[i], i===0 ? replyTo : null);
    if (i === 0) firstMsgId = mid;
    if (i < chunks.length - 1) await sleep(500);
  }
  return firstMsgId;
}

// ─── arrayBufferToBase64 — stack-safe chunk-by-chunk conversion ──
// btoa(String.fromCharCode(...largeArray)) throws "Maximum call stack size exceeded"
// for files > ~1 MB because spread operator puts every byte on the call stack.
// Chunked approach avoids this entirely.
function arrayBufferToBase64(buf) {
  const bytes = new Uint8Array(buf);
  const CHUNK = 8192;
  let b64 = "";
  for (let i = 0; i < bytes.length; i += CHUNK) {
    b64 += String.fromCharCode(...bytes.subarray(i, i + CHUNK));
  }
  return btoa(b64);
}

// ─── resolveFileMaxSize — centralise per-type size limits ────────
function resolveFileMaxSize(fileType) {
  if (fileType === "gif")   return C.MAX_GIF;
  if (fileType === "audio") return 20 * 1024 * 1024;
  return C.MAX_MEDIA;
}

async function downloadFile(env, fileId, fileType="audio") {
  try {
    const info = await (await fetchWithTimeout(tgUrl(env,`getFile?file_id=${fileId}`))).json();
    if (!info.ok) return null;
    const {file_path, file_size} = info.result;
    if (file_size > resolveFileMaxSize(fileType)) return null;
    const res = await fetchWithTimeout(
      `https://api.telegram.org/file/bot${env.TELEGRAM_BOT_TOKEN}/${file_path}`,
      {}, 20_000
    );
    if (!res.ok) return null;
    const buf = await res.arrayBuffer();
    return { base64: arrayBufferToBase64(buf), mimeType: resolveMime(file_path, fileType), size: buf.byteLength };
  } catch(e) { console.error("[downloadFile]", e.message); return null; }
}

// ═══════════════════════════════════════════════════════════════
// § 7  GEMINI API
// ═══════════════════════════════════════════════════════════════
// @FILE-SPLIT → src/gemini.js
// getBotConfig, gemini_keys CRUD, KeyManager class, testGeminiKeys,
// _geminiTimeout/_buildGeminiPayload/_parseGeminiParts/_callGeminiKey, and
// callGemini itself (further below). Depends on: C, fetchWithTimeout/sleep,
// buildGeminiTools (config.js). Also used directly by the external
// /api/chat handler (§ 4f, now part of admin.js) via callGeminiSimple, and
// by the Mini App (§ 16) — so this one has many importers; keep its own
// dependency surface minimal.
//
// Manages multiple Gemini keys (KeyManager) + the actual model call with
// function calling. Has a real timeout (AbortController) so one slow key
// doesn't leave the rest of the request hanging. The retry/rotation logic is
// sensitive — before changing it, make sure km.fail/km.ok are still called correctly.


let _botCfgCache = null, _botCfgCacheAt = 0;
// getBotUsername — the bot's @username, resolved from (1) the panel setting,
// (2) the username saved by the setup wizard, (3) Telegram's getMe (cached 24h).
// Every t.me deep link (quiz share, app button) is built from this — a wrong or
// missing username is what made shared links open the wrong bot / nothing.
async function getBotUsername(env, db) {
  try {
    const gc = await getGC(db);
    if (gc.botUsername) return String(gc.botUsername).replace(/^@/, "");
    const bc = await getBotConfig(db);
    if (bc.robotUsername) return String(bc.robotUsername).replace(/^@/, "");
    const cached = await kv.get(env, "bot:username");
    if (cached) return cached;
    if (env.TELEGRAM_BOT_TOKEN) {
      const r = await fetchWithTimeout(`https://api.telegram.org/bot${env.TELEGRAM_BOT_TOKEN}/getMe`, {}, 8000);
      const d = await r.json();
      if (d.ok && d.result?.username) { await kv.set(env, "bot:username", d.result.username, 86400); return d.result.username; }
    }
  } catch {}
  return "";
}

async function getBotConfig(db) {
  if (_botCfgCache && (Date.now() - _botCfgCacheAt) < 60_000) return _botCfgCache;
  const r = await db.prepare("SELECT value FROM global_config WHERE key=?").bind('bot_config').first();
  let cfg = { robotUsername: null, primaryToken: "" };
  if (r) { try { cfg = { ...cfg, ...JSON.parse(r.value) }; } catch {} }
  _botCfgCache = cfg;
  _botCfgCacheAt = Date.now();
  return cfg;
}
// setBotConfig — merges a partial patch into the stored bot_config row and
// busts the in-memory cache immediately so the very next request (this one
// included, further down the same fetch()) sees the change with no 60s lag.
// Used by the admin panel's "Telegram bot token" field: an admin-set
// primaryToken here takes priority over the TELEGRAM_BOT_TOKEN Worker secret
// everywhere env.TELEGRAM_BOT_TOKEN is read (see the override at the top of
// fetch()/scheduled()) — saving an empty string clears the override and
// falls back to the secret.
async function setBotConfig(db, patch) {
  const cur = await getBotConfig(db);
  const merged = { ...cur, ...patch };
  await db.prepare("INSERT OR REPLACE INTO global_config(key,value) VALUES(?,?)").bind('bot_config', JSON.stringify(merged)).run();
  _botCfgCache = null;
  return merged;
}

// ─── gemini_keys CRUD — extra Gemini keys managed from the admin panel ───
// `model`: optional per-key pin (e.g. "gemini-3.6-flash"). NULL/"" means
// "use C.GEMINI_MODEL" (the global default) — see KeyManager.curModel().
async function listGeminiKeys(db) {
  const r = await db.prepare(`SELECT id,label,api_key,active,model,created_at FROM gemini_keys ORDER BY id DESC`).all();
  return r.results || [];
}
async function getActiveGeminiKeys(db) {
  const r = await db.prepare(`SELECT id,label,api_key,model FROM gemini_keys WHERE active=1`).all();
  return r.results || [];
}
async function addGeminiKey(db, label, apiKey, model = null) {
  await db.prepare(`INSERT INTO gemini_keys(label,api_key,active,model,created_at) VALUES(?,?,1,?,?)`)
    .bind(label || "", apiKey, (model || "").trim() || null, new Date().toISOString()).run();
}
async function setGeminiKeyActive(db, id, active) {
  await db.prepare(`UPDATE gemini_keys SET active=? WHERE id=?`).bind(active ? 1 : 0, id).run();
}
async function setGeminiKeyModel(db, id, model) {
  await db.prepare(`UPDATE gemini_keys SET model=? WHERE id=?`).bind((model || "").trim() || null, id).run();
}
async function deleteGeminiKey(db, id) {
  await db.prepare(`DELETE FROM gemini_keys WHERE id=?`).bind(id).run();
}
function maskGeminiKey(k) {
  if (!k) return "";
  return k.length <= 8 ? "•".repeat(k.length) : `${k.slice(0,4)}${"•".repeat(6)}${k.slice(-4)}`;
}

class KeyManager {
  // dbKeys: rows from gemini_keys (getActiveGeminiKeys) — admin-added keys,
  // merged in alongside the env/Worker-secret keys (C.API_KEYS). Both pools
  // are tried the same way; nothing in the rest of the file needs to know
  // which source a given key came from.
  constructor(env, dbKeys = []) {
    this.keys = [];
    this.idx  = 0;
    for (const n of C.API_KEYS) {
      const v = env[n]?.trim();
      if (!v) continue;
      // Optional per-key model pin for Worker-secret keys: e.g. alongside
      // GEMINI_API_KEY_1 you can set GEMINI_API_KEY_1_MODEL="gemini-3.6-flash"
      // as a second Worker secret/var. Unset → falls back to C.GEMINI_MODEL,
      // same as before this existed.
      const modelOverride = env[`${n}_MODEL`]?.trim() || null;
      this.keys.push({name:n,value:v,model:modelOverride,failures:0,totalReq:0,active:true});
    }
    for (const row of dbKeys) {
      const v = row.api_key?.trim();
      if (v) this.keys.push({name:`db:${row.id}${row.label?":"+row.label:""}`,value:v,model:row.model||null,failures:0,totalReq:0,active:true});
    }
  }
  // create — convenience factory that also loads admin-panel keys from D1.
  // Prefer this over `new KeyManager(env)` wherever a db handle is available,
  // so panel-added keys are actually used, not just stored.
  static async create(env, db) {
    let dbKeys = [];
    try { dbKeys = await getActiveGeminiKeys(db); } catch (e) { console.error("[KeyManager.create]", e.message); }
    return new KeyManager(env, dbKeys);
  }
  cur()     { if(!this.keys.length)return null; const k=this.keys[this.idx]; k.totalReq++; return k.value; }
  curName() { return this.keys[this.idx]?.name??null; }
  // curModel — the model the CURRENT key should be called with: its own pin
  // if it has one, otherwise the global default. Every call site that used
  // to hardcode C.GEMINI_MODEL right after km.cur()/km.curName() should use
  // this instead, so per-key model pins actually take effect.
  curModel(){ return this.keys[this.idx]?.model || C.GEMINI_MODEL; }
  modelFor(name){ return this.keys.find(x=>x.name===name)?.model || C.GEMINI_MODEL; }
  fail(name){ const k=this.keys.find(x=>x.name===name); if(!k)return; k.failures++; if(k.failures>=3)k.active=false; this._next(); }
  ok(name)  { const k=this.keys.find(x=>x.name===name); if(k){k.failures=0;k.active=true;} }
  _next()   { const n=this.keys.length; for(let i=1;i<=n;i++){const j=(this.idx+i)%n; if(this.keys[j].active){this.idx=j;return;}} this.keys.forEach(k=>{k.active=true;k.failures=0;}); this.idx=(this.idx+1)%n; }
  activeCount() { return this.keys.filter(k=>k.active).length; }
  statusLines() { return this.keys.map((k,i)=>`${k.active?"✅":"❌"} ${k.name} [${k.model||C.GEMINI_MODEL}]: req=${k.totalReq} fail=${k.failures}${i===this.idx?" ← current":""}`).join("\n"); }
}

// ─── testGeminiKeys — real live-fire check against every given key ────────
// Shared by /testai (Telegram command) and the admin panel's "تست همه" —
// one implementation, so the two never drift apart. Runs all keys in
// parallel with a short timeout; a 429 here means the key's own quota is
// exhausted (see the KV cooldown in _callGeminiAttempts for how normal
// traffic reacts to that), not that anything is misconfigured.
async function testGeminiKeys(keys) {
  const payload = {contents:[{parts:[{text:"Reply one word: connected"}]}],generationConfig:{temperature:0.1,maxOutputTokens:10}};
  return Promise.all(keys.map(async k=>{
    // Each key is tested against ITS OWN pinned model (k.model), falling
    // back to the global default only if the key has no pin — this is what
    // makes "test each key separately" actually mean something once keys
    // can be assigned different models.
    const model = k.model || C.GEMINI_MODEL;
    try {
      const r=await fetchWithTimeout(geminiUrl(k.value,model),{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)},10_000);
      const b=await r.text(); const ok=r.ok;
      const reply=ok?JSON.parse(b)?.candidates?.[0]?.content?.parts?.[0]?.text||"—":null;
      return {name:k.name,model,ok,status:r.status,reply,error:ok?null:b.slice(0,150)};
    } catch(e){return{name:k.name,model,ok:false,status:0,reply:null,error:e.message};}
  }));
}

// ─── _geminiTimeout — resolve timeout based on media type ────────
// useWebSearch overrides everything else with a much shorter ceiling — see
// GEMINI_TIMEOUT_SEARCH for why.
function _geminiTimeout(mediaType, useWebSearch=false) {
  if (useWebSearch) return C.GEMINI_TIMEOUT_SEARCH;
  if (mediaType === "video") return 90_000;
  if (mediaType === "audio") return 45_000;
  return C.GEMINI_TIMEOUT;
}

// ─── _buildGeminiPayload — assemble the full request body ─────────
// textOnly=true strips tools/toolConfig entirely, forcing the model to
// write an actual text reply with no function-call escape hatch available.
function _buildGeminiPayload(contents, sysPrompt, useWebSearch, textOnly=false, skill=undefined, maxTokensOverride=null, isPrivate=false, offTools=null) {
  const tools = textOnly ? undefined : buildGeminiTools(useWebSearch, skill, isPrivate, offTools);
  // functionCallingConfig only makes sense when functionDeclarations are
  // present — sending it alongside a googleSearch-only tools array causes
  // a 400 InvalidArgument on some Gemini versions.
  const toolConfig = (useWebSearch || textOnly) ? undefined : { functionCallingConfig: { mode: "AUTO" } };
  const payload = {
    contents,
    ...(tools ? { tools } : {}),
    systemInstruction: { parts: [{ text: sysPrompt }] },
    generationConfig: {
      temperature: 0.9, topP: 0.95, topK: 40,
      maxOutputTokens: maxTokensOverride || C.MAX_TOKENS,
      responseModalities: ["TEXT"],
      // ─── thinkingConfig ────────────────────────────────────────
      // gemini-2.5-flash has "thinking" ON by default (dynamic budget,
      // i.e. the model decides how many tokens to spend reasoning before
      // writing the real answer/function-call) — and those thinking
      // tokens are drawn from the SAME maxOutputTokens pool as the final
      // reply. With 9 function declarations + a long system prompt, the
      // model can burn the entire budget "thinking" and hit MAX_TOKENS
      // before ever emitting text or a functionCall. The response comes
      // back with res.ok===true (the API call itself succeeded — hence
      // "my API works") but parts contains only `thought:true` chunks,
      // which _parseGeminiParts filters out, so every key looks like it
      // failed identically → total failure on every attempt, not a
      // key/quota problem. Capping the thinking budget fixes this.
      thinkingConfig: { thinkingBudget: C.GEMINI_THINKING_BUDGET },
    },
  };
  if (toolConfig) payload.toolConfig = toolConfig;
  return payload;
}

// ─── _parseGeminiParts — extract text + function calls from response ──
//
// gemini-2.5-flash may return parts with `thought: true` (the model's
// internal reasoning trace) alongside the real text/function-call parts.
// These MUST be filtered out — they're not meant to be shown to the user
// and including them in textPart detection causes the parser to either
// pick up raw chain-of-thought text as the reply, or skip the real text
// entirely and return null (which the caller treats as total failure).
//
// Web-search responses come back with a normal text part (the model's
// synthesised answer) plus a `groundingMetadata` field at the candidate
// level — we don't need to do anything special to extract the text;
// the regular `parts.find(p => p.text)` already finds it. The search
// grounding sources are ignored here (Telegram UX doesn't support
// inline citations anyway).
function _parseGeminiParts(parts) {
  // filter out thought/reasoning parts — they are internal to the model
  const realParts = parts.filter(p => !p.thought);
  const fcParts   = realParts.filter(p => p.functionCall);
  const textPart  = realParts.find(p => typeof p.text === "string" && p.text.trim());
  if (!fcParts.length && !textPart) return null;
  return {
    text: textPart?.text || "",
    functionCalls: fcParts.map(p => ({ name: p.functionCall.name, args: p.functionCall.args || {} })),
  };
}

// ─── _callGeminiKey — single attempt with one API key, with retries ──
async function _callGeminiKey(km, name, key, payload, timeout, useWebSearch=false) {
  const maxR  = useWebSearch ? C.MAX_RETRIES_SEARCH : C.MAX_RETRIES;
  const rMs   = useWebSearch ? C.RETRY_MS_SEARCH    : C.RETRY_MS;
  let pl = payload, leaned = false;
  for (let r = 1; r <= maxR; r++) {
    try {
      const res  = await fetchWithTimeout(
        geminiUrl(key, km.modelFor(name)),
        { method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify(pl) },
        timeout
      );
      const body = await res.text();

      if (!res.ok) {
        if (res.status === 429)                          { km.fail(name); return { err:"rate_limited", status:429 }; }
        if ([500,503].includes(res.status) && r<maxR)     { await sleep(rMs*r); continue; }
        // Search requests are the picky ones: some model/tool combos answer 400 when extra
        // generationConfig fields (thinkingConfig, topK, …) ride along with googleSearch.
        // Retry once, same key, with a lean config before giving up.
        if (res.status === 400 && useWebSearch && !leaned) {
          pl = { contents: payload.contents, tools: payload.tools, systemInstruction: payload.systemInstruction,
                 generationConfig: { maxOutputTokens: payload.generationConfig?.maxOutputTokens } };
          leaned = true; r--; continue;
        }
        // keep the API's own error message (key redacted) so Admin → Logs shows the REAL cause
        const why = String(body).replace(/AIza[0-9A-Za-z_-]{20,}/g, "AIza…").replace(/\s+/g, " ").slice(0, 300);
        km.fail(name); return { err:`HTTP ${res.status}: ${why}`, status: res.status };
      }

      let parsed;
      try { parsed = JSON.parse(body); } catch { km.fail(name); return { err:"json_parse" }; }

      const candidate = parsed?.candidates?.[0];
      const parts = candidate?.content?.parts;
      if (!parts?.length) {
        const reason = candidate?.finishReason || "unknown";
        km.fail(name);
        return { err: `empty_parts:${reason}` };
      }

      const result = _parseGeminiParts(parts);
      if (!result)       { km.fail(name); return { err:"no_usable_part" }; }
      // MAX_TOKENS can be hit AFTER some real text already came through —
      // e.g. the model writes an intro sentence, then runs out of budget
      // right as it's about to open a code fence. That's a genuinely
      // truncated answer, not a successful one, but it was previously
      // indistinguishable from a normal complete reply (parts is non-empty
      // either way) — this is likely why "give me code" sometimes came back
      // as just an intro with no code at all. Flagging it here lets the
      // caller retry with more room instead of silently accepting a cut-off
      // answer.
      if (candidate?.finishReason === "MAX_TOKENS") result.truncated = true;

      km.ok(name);
      return { result };
    } catch(e) {
      if (e.message === "timeout" && r < maxR) { await sleep(rMs * r); continue; }
      km.fail(name); return { err: e.message };
    }
  }
  return { err:"max_retries" };
}

/**
 * callGemini — call Gemini with full Function Calling support
 * Output: { text, functionCalls } or null on total failure
 *
 * When useWebSearch is true, the whole attempt loop runs on a much tighter
 * budget (see GEMINI_TIMEOUT_SEARCH) — if it still can't get an answer in
 * time, we don't give up outright: we immediately retry once WITHOUT search
 * on the normal, more generous budget, so the user gets a real (if
 * search-less) answer instead of a hard failure.
 */
async function callGemini(env, db, contents, mediaType, km, chatId, userId, displayName, isPrivate, lastUserMsg="", useWebSearch=false, memEnabled=true, extraSystemNote="", skill=undefined, forceOffTools=null) {
  const result = await _callGeminiAttempts(env, db, contents, mediaType, km, chatId, userId, displayName, isPrivate, lastUserMsg, useWebSearch, memEnabled, extraSystemNote, skill, forceOffTools);
  if (result) return result;
  if (useWebSearch) {
    console.warn("[Gemini] search-augmented call failed — falling back to a non-search answer");
    return _callGeminiAttempts(env, db, contents, mediaType, km, chatId, userId, displayName, isPrivate, lastUserMsg, false, memEnabled, extraSystemNote, skill, forceOffTools);
  }
  return null;
}

// ─── Gemini key priority + quota cooldown (single KV blob) ────────────────
// Two goals, one mechanism:
//   1. "Least recently used first" — spreads load evenly across however many
//      keys are configured, so no single key gets hammered while others sit
//      idle (which is itself a good way to trip per-key rate limits).
//   2. Bounded, O(1) KV traffic no matter how many keys exist. A pool of 100
//      keys must never mean 100 sequential KV reads, or trying all 100
//      sequentially over HTTP, before the Worker gives up. All key metadata
//      (last-used timestamp + quota-cooldown expiry) lives in ONE KV record,
//      fetched with a single GET and written back with a single SET per
//      call — cheap no matter how many live HTTP attempts follow.
const GEMINI_META_KV_KEY       = "gemini_key_meta";
const GEMINI_COOLDOWN_MS       = 90_000; // how long a 429'd key is skipped
// Used to be hard-capped (4, then 8) regardless of pool size — with N keys
// configured and free-tier per-key RPM limits, giving up after only a few
// meant a handful of unlucky 429s could fail the whole request even though
// plenty of other, possibly-fine keys were never touched. Non-search calls
// now try every non-cooling-down key (see _callGeminiAttempts below) instead
// of stopping at a fixed count — this constant only still applies to
// web-search calls, which intentionally stay tight since they're on a short
// timeout budget and fall back to a full, uncapped non-search retry anyway.
const MAX_GEMINI_LIVE_ATTEMPTS_SEARCH = 2;

async function _loadGeminiMeta(env) {
  return (await kv.get(env, GEMINI_META_KV_KEY, true)) || {};
}
async function _saveGeminiMeta(env, meta) {
  // best-effort — a lost update just means slightly worse priority ordering
  // next time, never a correctness problem. 6h TTL so a stale/orphaned
  // record (e.g. after keys are removed from the panel) self-heals.
  await kv.set(env, GEMINI_META_KV_KEY, meta, 6 * 3600);
}
// _prioritizeGeminiKeys — least-recently-used first, quota-cooling-down keys
// dropped entirely. Pure in-memory sort over an already-loaded `meta` blob —
// never touches the network itself.
function _prioritizeGeminiKeys(keys, meta) {
  const now = Date.now();
  return keys
    .filter(k => !(meta[k.name]?.cooldownUntil > now))
    .sort((a, b) => (meta[a.name]?.lastUsed || 0) - (meta[b.name]?.lastUsed || 0));
}
// NOTE (rotation change): live HTTP attempts for normal (non-search) calls are
// no longer capped at a fixed number — every non-cooling-down key is tried,
// in least-recently-used order, until one succeeds or the pool is exhausted
// ("keep going until a working key is found" instead of giving up after a
// fixed number). Two things naturally bound this so it can't run away:
//   1. Pool size — you only try as many keys as are actually configured (env
//      secrets + panel-added), so it scales with your own key count.
//   2. Cloudflare Workers' own subrequest and wall-clock execution limits
//      still apply regardless of what this code does.
// Web-search calls keep their own tight cap (below) since they're already on
// a short timeout budget and callGemini() falls back to a non-search retry
// (which gets the full, uncapped pool) if search-augmented attempts fail.

async function _callGeminiAttempts(env, db, contents, mediaType, km, chatId, userId, displayName, isPrivate, lastUserMsg, useWebSearch, memEnabled, extraSystemNote="", skill=undefined, forceOffTools=null) {
  // Admin panel switches (private / group menus): drop switched-off tools and web search.
  let offTools = null;
  try {
    const _gcSw = await getGC(db);
    offTools = disabledToolNames(_gcSw, isPrivate);
    if (useWebSearch && (isPrivate ? _gcSw.disabledPrivate : _gcSw.disabledGroup).includes("feature:websearch")) useWebSearch = false;
  } catch {}
  if (forceOffTools && forceOffTools.size) offTools = new Set([...(offTools || []), ...forceOffTools]);
  const timeout   = _geminiTimeout(mediaType, useWebSearch);
  let sysPrompt = await resolveSystemPrompt(env, db, chatId, userId, displayName, isPrivate, lastUserMsg, memEnabled, useWebSearch);
  // extraSystemNote is how the Mini App's per-thread "skills" (§ 16 —
  // professional programmer / language tutor) layer their own instructions
  // on top of Niki's normal persona for ONE specific call, without touching
  // the account-level prompt_modes system (which stays chat-wide, not
  // per-thread). Telegram's own flow never passes this — it's always "".
  if (extraSystemNote) sysPrompt = `${sysPrompt}\n\n${extraSystemNote}`;
  const payload   = _buildGeminiPayload(contents, sysPrompt, useWebSearch, false, skill, null, isPrivate, offTools);

  // Single KV read for ALL keys' priority/cooldown state — one round-trip
  // regardless of whether there are 10 keys or 100.
  const meta    = await _loadGeminiMeta(env);
  const ordered = _prioritizeGeminiKeys(km.keys, meta);

  // Non-search calls: no artificial cap — walk the full LRU-ordered,
  // non-cooling-down key list until one succeeds or the pool runs out.
  // Search calls keep a tight cap since they're on a short timeout budget
  // and get a full uncapped retry (without search) if they all fail anyway.
  const cap         = useWebSearch ? Math.min(MAX_GEMINI_LIVE_ATTEMPTS_SEARCH, ordered.length) : ordered.length;
  const attemptList = ordered.slice(0, cap);
  const gapMs        = useWebSearch ? 400 : 500;

  let lastError = null;
  let dirty = false;

  for (let a = 0; a < attemptList.length; a++) {
    const { name, value: key } = attemptList[a];
    meta[name] = meta[name] || {};
    meta[name].lastUsed = Date.now();
    dirty = true;

    const { result, err, status } = await _callGeminiKey(km, name, key, payload, timeout, useWebSearch);
    if (result) {
      km.ok(name);
      await _saveGeminiMeta(env, meta);
      if (result.truncated) {
        // One extra attempt with a much bigger ceiling — cheap insurance
        // against the "intro sentence, then nothing" failure mode (see the
        // truncated flag's origin in _callGeminiKey). Same key, since it
        // just proved itself working a moment ago. If this retry ALSO comes
        // back truncated (a genuinely huge answer, or a runaway thinking
        // trace), the bigger of the two is still strictly better than the
        // original — never worth blocking the reply on a second retry.
        const biggerPayload = _buildGeminiPayload(contents, sysPrompt, useWebSearch, false, skill, C.MAX_TOKENS * 3, isPrivate, offTools);
        const retry = await _callGeminiKey(km, name, key, biggerPayload, timeout, useWebSearch);
        if (retry.result) {
          log(db, { chatId, userId, action:"gemini_truncation_retry", level:"info", detail:`key=${name} retryTruncated=${!!retry.result.truncated}` }).catch(()=>{});
          return retry.result;
        }
      }
      return result;
    }
    km.fail(name);
    lastError = err;
    if (status === 429) meta[name].cooldownUntil = Date.now() + GEMINI_COOLDOWN_MS;
    else if (a < attemptList.length - 1) await sleep(gapMs); // no point sleeping after a 429 or after the last attempt
  }

  if (dirty) await _saveGeminiMeta(env, meta);
  const noLiveAttempts = !ordered.length;
  if (noLiveAttempts) console.error("[Gemini] every key is in quota cooldown — skipped all HTTP calls");
  console.error(`[Gemini] exhausted ${attemptList.length}/${km.keys.length} keys tried:`, lastError);
  // Persist the reason to bot_logs (not just console.error, which is only
  // visible via `wrangler tail` and is easy to miss in production) so the
  // admin panel's log viewer shows WHY replies are failing — e.g.
  // "empty_parts:MAX_TOKENS" repeated across every key means a thinking-
  // budget/token-starvation problem (same for every key, unfixable by
  // rotating keys), while "HTTP 401/403" means an actually-bad key, and
  // "rate_limited" means real quota exhaustion. Best-effort: never let a
  // logging failure mask the original error.
  log(db, {
    chatId, userId,
    action: "gemini_exhausted",
    level: noLiveAttempts ? "warn" : "error",
    detail: noLiveAttempts
      ? "all keys in 429 cooldown — skipped all HTTP calls"
      : `tried ${attemptList.length}/${km.keys.length} keys, last error: ${lastError}`,
  }).catch(()=>{});
  return null;
}

// ═══════════════════════════════════════════════════════════════
// § 8  IMAGE GENERATOR (Flux via Workers AI)
// ═══════════════════════════════════════════════════════════════
// @FILE-SPLIT → src/image-gen.js
// ImageGen class + handleImage/handleMultiImage/_runImageCallAlongside.
// Depends on: C, withTimeout, fetchWithTimeout/tgUrl/react/sendMsg and
// consumeGroupLimit/consumeUserLimit — all now in webhook.js.
// generate() doesn't have an unlimited duration — it's bounded with withTimeout because
// env.AI.run is a binding (not a raw fetch, so AbortController doesn't
// work directly). sendPhoto/sendMediaGroup still use fetchWithTimeout
// for Telegram. Do not tamper with HARD_CAP_MULTI_PHOTO.

class ImageGen {
  constructor(env) { this.env = env; }
  async generate(prompt) {
    if (!this.env.AI) return {ok:false, error:"AI binding not configured"};
    const p = prompt.includes("anime") ? prompt : `${prompt}, anime style, high quality, detailed`;
    try {
      const r = await withTimeout(
        this.env.AI.run(C.FLUX_MODEL,{prompt:p,steps:C.FLUX_STEPS}), // flux-1-schnell rejects width/height/seed (error 5006)
        20_000
      );
      if (!r?.image) throw new Error("no image data");
      const bin=atob(r.image), bytes=new Uint8Array(bin.length);
      for(let i=0;i<bin.length;i++) bytes[i]=bin.charCodeAt(i);
      return {ok:true, buffer:bytes.buffer, mimeType:"image/png", ext:"png"};
    } catch(e) { return {ok:false, error:e.message}; }
  }
  async sendPhoto(env, chatId, buffer, mimeType, ext, caption, replyTo) {
    const form = new FormData();
    form.append("chat_id",String(chatId));
    form.append("photo",new Blob([buffer],{type:mimeType}),`niki.${ext}`);
    if (caption) { form.append("caption",caption); form.append("parse_mode","HTML"); }
    if (replyTo) form.append("reply_to_message_id",String(replyTo));
    try {
      const res = await fetchWithTimeout(tgUrl(env,"sendPhoto"),{method:"POST",body:form}, 20_000);
      if (res.status === 429) {
        const d = await res.json().catch(() => ({}));
        const retryAfter = d?.parameters?.retry_after ?? 1;
        return {ok:false, error:`rate limited (retry_after=${retryAfter}s)`, rateLimited:true, retryAfter};
      }
      const d   = await res.json();
      return res.ok ? {ok:true} : {ok:false, error:d.description||`HTTP ${res.status}`};
    } catch(e) { return {ok:false, error:e.message}; }
  }

  // send multiple photos as a media group (album)
  async sendMediaGroup(env, chatId, photos, replyTo) {
    if (!photos?.length) return {ok:false, error:"no photos"};
    if (photos.length === 1) {
      return this.sendPhoto(env, chatId, photos[0].buffer, photos[0].mimeType, photos[0].ext, photos[0].caption, replyTo);
    }
    const form = new FormData();
    form.append("chat_id", String(chatId));
    if (replyTo) form.append("reply_to_message_id", String(replyTo));
    const media = [];
    photos.forEach((p, i) => {
      const attachName = `photo${i}`;
      form.append(attachName, new Blob([p.buffer], {type: p.mimeType}), `niki${i}.${p.ext}`);
      const item = { type: "photo", media: `attach://${attachName}` };
      if (p.caption) { item.caption = p.caption; item.parse_mode = "HTML"; }
      media.push(item);
    });
    form.append("media", JSON.stringify(media));
    try {
      const res = await fetchWithTimeout(tgUrl(env, "sendMediaGroup"), {method:"POST", body:form}, 20_000);
      const d   = await res.json();
      return res.ok ? {ok:true} : {ok:false, error:d.description||`HTTP ${res.status}`};
    } catch(e) { return {ok:false, error:e.message}; }
  }
}
async function handleImage(env, db, chatId, msgId, prompt, imgGen, caption=null) {
  const r = await imgGen.generate(prompt);
  if (r.ok) {
    const cap = (caption||`🎨 "${prompt.slice(0,80)}"`).replace(/<prompt>[\s\S]*?<\/prompt>/gi,"").trim()||"✨";
    const s   = await imgGen.sendPhoto(env,chatId,r.buffer,r.mimeType,r.ext,cap,msgId);
    await react(env,chatId,msgId, s.ok?"✅":"❌");
    if (!s.ok) await sendMsg(env,db,chatId,`❌ ارسال تصویر ناموفق: ${s.error}`,msgId);
  } else {
    await react(env,chatId,msgId,"❌");
    await sendMsg(env,db,chatId,`❌ ${r.error}`,msgId);
  }
}

// ─── handleMultiImage: generate and send multiple images in parallel ───
async function handleMultiImage(env, db, chatId, msgId, requests, imgGen) {
  if (!requests?.length) return;
  // generate all images in parallel
  const results = await Promise.all(
    requests.map(req => imgGen.generate(req.prompt).then(r => ({...r, caption: req.caption||null, prompt: req.prompt})))
  );
  const successes = results.filter(r => r.ok);
  if (!successes.length) {
    await react(env,chatId,msgId,"❌");
    await sendMsg(env,db,chatId,`❌ تولید تصویر ناموفق بود.`,msgId);
    return;
  }
  const photos = successes.map((r, i) => ({
    buffer:  r.buffer,
    mimeType: r.mimeType,
    ext:     r.ext,
    caption: r.caption || (i===0 ? `🎨 ${successes.length} تصویر` : null),
  }));
  const s = await imgGen.sendMediaGroup(env, chatId, photos, msgId);
  await react(env,chatId,msgId, s.ok?"✅":"❌");
  if (!s.ok) await sendMsg(env,db,chatId,`❌ ارسال آلبوم ناموفق: ${s.error}`,msgId);
}

// ═══════════════════════════════════════════════════════════════
// § 8b  VOICE GENERATOR (TTS via Workers AI — @cf/myshell-ai/melotts)
// ═══════════════════════════════════════════════════════════════
// @FILE-SPLIT → src/image-gen.js (grouped with § 8 as "Workers AI media
// generation" — a separate voice-gen.js would be reasonable too, but this
// keeps ImageGen/VoiceGen, the two "generate media via env.AI" classes,
// next to each other)
//
// Engine strategy: Aura-1 (Asteria voice) is ALWAYS the primary engine now.
// It bills on Cloudflare's real Neuron-based pricing at a much higher rate
// per character than MeloTTS, but it's the only one that can output Opus in
// an OGG container directly — a real Telegram voice note (sendVoice, round
// bubble) — and simplicity/reliability won out over the cost saving here.
// @cf/myshell-ai/melotts is kept ONLY as an automatic fallback for when
// Aura-1 itself fails (quota, transient upstream error, binding issue) so a
// voice reply still goes out rather than failing outright — it only
// returns MP3, so that fallback case goes out via sendAudio (a regular
// playable audio-file bubble, not a round voice note); there's no cheap way
// to transcode MP3→OGG/Opus inside a Cloudflare Worker (that needs a real
// audio codec, not available in this runtime without a full WASM
// decoder+encoder pipeline), so the fallback just stays a plain audio
// bubble instead of faking a voice note.
// Both engines are English-only in practice (Aura-1 always was; MeloTTS's
// other languages — fr/de/es/zh/ja/ko — are no longer used here on
// purpose, so the whole voice pipeline has one consistent contract: always
// speak English). Anything else the model or user wrote gets translated to
// English before synthesis — both by instruction (generate_voice's tool
// description / the system prompt's 🔊 VOICE MESSAGES section) AND, as a
// safety net, in code below via translateToEnglish() in case the model
// forgets to translate first.
const VOICE_MODEL = "@cf/myshell-ai/melotts";
const AURA_MODEL = "@cf/deepgram/aura-1";
const AURA_SPEAKER = "asteria";
// Kept only as a reference of what MeloTTS is technically capable of if this
// project ever wants native-language pronunciation back (e.g. for the
// language-tutor skill teaching fr/de/es/zh/ja/ko words) — NOT used by the
// current pipeline, which is intentionally English-only end to end.
const MELOTTS_SUPPORTED_LANGS = ["en", "fr", "de", "es", "zh", "ja", "ko"];

// ─── mp3 duration estimation ───────────────────────────────────────────
// sendAudio was never passed a `duration`, and Telegram doesn't always
// probe the file itself to compute one — the raw bytes MeloTTS returns
// don't carry a reliable container-level duration tag the way a properly
// muxed file would, so the bubble showed "0:00". This walks the MPEG frame
// header (skipping any ID3v2 tag first) to get the true bitrate/sample
// rate, then derives duration from the remaining byte count. Assumes CBR,
// which is what MeloTTS/Workers AI returns.
function _mp3FrameInfo(view, offset) {
  const BITRATES_V1L3 = [0, 32, 40, 48, 56, 64, 80, 96, 112, 128, 160, 192, 224, 256, 320];
  const SAMPLE_RATES_MPEG1 = [44100, 48000, 32000];
  if (offset + 4 > view.byteLength) return null;
  const b1 = view.getUint8(offset), b2 = view.getUint8(offset + 1);
  if (b1 !== 0xFF || (b2 & 0xE0) !== 0xE0) return null; // no sync word
  const versionBits = (b2 >> 3) & 0x3; // 3 = MPEG1
  const layerBits = (b2 >> 1) & 0x3;   // 1 = Layer III
  if (versionBits !== 3 || layerBits !== 1) return null;
  const b3 = view.getUint8(offset + 2);
  const bitrateIdx = (b3 >> 4) & 0xF;
  const sampleRateIdx = (b3 >> 2) & 0x3;
  if (bitrateIdx === 0 || bitrateIdx === 15 || sampleRateIdx === 3) return null;
  return { bitrate: BITRATES_V1L3[bitrateIdx] * 1000, sampleRate: SAMPLE_RATES_MPEG1[sampleRateIdx] };
}
function estimateMp3DurationSeconds(buffer) {
  try {
    const view = new DataView(buffer);
    let offset = 0;
    if (view.byteLength > 10 && view.getUint8(0) === 0x49 && view.getUint8(1) === 0x44 && view.getUint8(2) === 0x33) {
      const sz = ((view.getUint8(6) & 0x7f) << 21) | ((view.getUint8(7) & 0x7f) << 14) |
                 ((view.getUint8(8) & 0x7f) << 7) | (view.getUint8(9) & 0x7f);
      offset = 10 + sz;
    }
    for (let i = offset; i < Math.min(offset + 4096, view.byteLength - 4); i++) {
      const info = _mp3FrameInfo(view, i);
      if (info) {
        const audioBytes = view.byteLength - i;
        return Math.max(1, Math.round((audioBytes * 8) / info.bitrate));
      }
    }
  } catch (e) { /* fall through to the estimate below */ }
  // Fallback: frame-header parsing can miss (VBR, an unusual header layout,
  // or Workers AI wrapping the bytes slightly differently than expected).
  // Rather than leaving duration unset — which is exactly what produced the
  // "0:00" bubble in the first place — assume a typical speech-MP3 bitrate
  // (~64kbps) and estimate from raw byte size. Not exact, but always gives
  // Telegram SOME non-zero number to display instead of none at all.
  try {
    const bytes = buffer?.byteLength || 0;
    if (bytes > 0) return Math.max(1, Math.round((bytes * 8) / 64000));
  } catch (e) { /* ignore */ }
  return null;
}

// ─── translateToEnglish — safety net, not the primary translation path ────
// The model is instructed (tool description + system prompt) to translate
// non-English text to English itself before ever calling generate_voice.
// This is a defensive second layer for when it forgets: a cheap heuristic
// skips the call entirely for text that's already plain ASCII (the common
// case), and only reaches for a real translation model otherwise. Never
// throws — on any failure it just returns the original text, so a
// translation hiccup degrades to "spoken in the wrong language" rather than
// killing the whole voice reply.
async function translateToEnglish(env, text, sourceLang) {
  const s = String(text || "");
  if (!s.trim()) return s;
  if (/^[\x00-\x7F]*$/.test(s)) return s; // already plain ASCII — treat as English
  if (!env.AI) return s;
  try {
    const r = await withTimeout(
      env.AI.run("@cf/meta/m2m100-1.2b", {
        text: s,
        source_lang: sourceLang || "auto",
        target_lang: "english",
      }),
      10_000
    );
    return r?.translated_text || s;
  } catch (e) {
    console.error("[translateToEnglish]", e.message || e);
    return s; // degrade gracefully — speak the original rather than fail
  }
}

// ─── Gemini TTS (gemini-3.8-flash-tts) ────────────────────────────────────
// Default engine for every voice reply (Telegram, Mini App, public /api/tts).
// Cloudflare (Aura-1 / MeloTTS, below) remains selectable in the admin panel
// and is also the automatic fallback when every Gemini key fails.
// Voices: [name, gender, short character]. Default = a young woman (Leda).
const GEMINI_TTS_DEFAULT_MODEL = "gemini-3.8-flash-tts";
const GEMINI_LIVE_DEFAULT_MODEL = "gemini-3.8-live";
const GEMINI_TTS_DEFAULT_VOICE = "Leda";
const GEMINI_TTS_VOICES = [
  ["Leda","F","Youthful"],["Zephyr","F","Bright"],["Kore","F","Firm"],["Aoede","F","Breezy"],
  ["Callirrhoe","F","Easy-going"],["Autonoe","F","Bright"],["Despina","F","Smooth"],["Erinome","F","Clear"],
  ["Laomedeia","F","Upbeat"],["Achernar","F","Soft"],["Gacrux","F","Mature"],["Pulcherrima","F","Forward"],
  ["Vindemiatrix","F","Gentle"],["Sulafat","F","Warm"],
  ["Puck","M","Upbeat"],["Charon","M","Informative"],["Fenrir","M","Excitable"],["Orus","M","Firm"],
  ["Enceladus","M","Breathy"],["Iapetus","M","Clear"],["Umbriel","M","Easy-going"],["Algieba","M","Smooth"],
  ["Algenib","M","Gravelly"],["Rasalgethi","M","Informative"],["Alnilam","M","Firm"],["Schedar","M","Even"],
  ["Achird","M","Friendly"],["Zubenelgenubi","M","Casual"],["Sadachbia","M","Lively"],["Sadaltager","M","Knowledgeable"],
];
const GEMINI_TTS_VOICE_NAMES = GEMINI_TTS_VOICES.map(v => v[0]);
const GEMINI_TTS_META_KV_KEY = "gemini_tts_key_meta"; // separate from chat meta: TTS quota is per-model

// Wrap raw 16-bit mono PCM into a WAV container.
function _pcmToWav(pcm, sampleRate = 24000) {
  const n = pcm.byteLength, buf = new ArrayBuffer(44 + n), v = new DataView(buf);
  const w = (o, str) => { for (let i = 0; i < str.length; i++) v.setUint8(o + i, str.charCodeAt(i)); };
  w(0, "RIFF"); v.setUint32(4, 36 + n, true); w(8, "WAVE"); w(12, "fmt "); v.setUint32(16, 16, true);
  v.setUint16(20, 1, true); v.setUint16(22, 1, true); v.setUint32(24, sampleRate, true);
  v.setUint32(28, sampleRate * 2, true); v.setUint16(32, 2, true); v.setUint16(34, 16, true);
  w(36, "data"); v.setUint32(40, n, true); new Uint8Array(buf, 44).set(new Uint8Array(pcm));
  return buf;
}
function wavDurationSeconds(buffer) {
  try {
    const v = new DataView(buffer);
    if (v.byteLength < 44 || v.getUint32(0) !== 0x52494646) return null;
    const byteRate = v.getUint32(28, true);
    return byteRate ? Math.max(1, Math.round((v.byteLength - 44) / byteRate)) : null;
  } catch { return null; }
}
function _b64ToBuf(b64) {
  const bin = atob(b64), u8 = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);
  return u8.buffer;
}

let _ttsVariantIdx = 0;
// One Gemini TTS call with ONE key. Tries the classic request shape first and
// falls back to the shapes documented for the 3.8 family if the API answers 400.
async function _geminiTtsCall(key, model, voice, style, text) {
  const mk = (shape, withStyle) => {
    const part = { text };
    if (withStyle && style) part.speech_metadata = { style };
    return {
      contents: [{ role: "user", parts: [part] }],
      generationConfig: {
        responseModalities: ["AUDIO"],
        speechConfig: { voiceConfig: shape === "prebuilt" ? { prebuiltVoiceConfig: { voiceName: voice } } : { voice } },
      },
    };
  };
  const all = [["prebuilt", true], ["plain", true], ["prebuilt", false]];
  // start with the variant that worked last time in this isolate (saves a wasted 400 per call)
  const variants = _ttsVariantIdx > 0 ? [all[_ttsVariantIdx], ...all.filter((_, i) => i !== _ttsVariantIdx)] : all;
  let last = { status: 0, error: "no attempt" };
  for (const [shape, withStyle] of variants) {
    if (!style && shape === "prebuilt" && !withStyle) continue;
    let res;
    try {
      res = await fetchWithTimeout(
        `https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(model)}:generateContent`,
        { method: "POST", headers: { "Content-Type": "application/json", "x-goog-api-key": key }, body: JSON.stringify(mk(shape, withStyle)) },
        30_000
      );
    } catch (e) { return { status: 0, error: e.message || "network error" }; }
    if (res.ok) {
      _ttsVariantIdx = all.findIndex(v => v[0] === shape && v[1] === withStyle);
      const d = await res.json().catch(() => null);
      const part = d?.candidates?.[0]?.content?.parts?.find(p => p.inlineData?.data);
      if (!part) return { status: 502, error: "no audio in response" + (d?.candidates?.[0]?.finishReason ? ":" + d.candidates[0].finishReason : "") };
      let buf = _b64ToBuf(part.inlineData.data);
      const head = new Uint8Array(buf, 0, Math.min(4, buf.byteLength));
      const isWav = head.length === 4 && String.fromCharCode(...head) === "RIFF";
      if (!isWav) {
        const rate = Number(/rate=(\d+)/.exec(part.inlineData.mimeType || "")?.[1]) || 24000;
        buf = _pcmToWav(buf, rate); // raw L16 PCM → playable WAV
      }
      if (!buf.byteLength) return { status: 502, error: "empty audio" };
      return { ok: true, buffer: buf };
    }
    const errText = (await res.text().catch(() => "")).slice(0, 200);
    last = { status: res.status, error: `HTTP ${res.status} ${errText}` };
    if (res.status !== 400) return last; // only a 400 can mean "wrong request shape" — try the next variant
  }
  return last;
}

// Rotating-key Gemini TTS. Least-recently-used key first; a 429 puts that key
// on a short cooldown and the next key is tried immediately.
async function geminiTtsGenerate(env, db, text, { model, voice, style } = {}) {
  let dbKeys = [];
  try { dbKeys = await getActiveGeminiKeys(db); } catch {}
  const km = new KeyManager(env, dbKeys);
  if (!km.keys.length) return { ok: false, error: "no Gemini API key configured" };
  const meta = (await kv.get(env, GEMINI_TTS_META_KV_KEY, true)) || {};
  const now = Date.now();
  const ordered = km.keys.filter(k => !(meta[k.name]?.cooldownUntil > now))
    .sort((a, b) => (meta[a.name]?.lastUsed || 0) - (meta[b.name]?.lastUsed || 0));
  if (!ordered.length) return { ok: false, error: "all Gemini keys are rate-limited for TTS (cooldown)" };
  const mdl = model || GEMINI_TTS_DEFAULT_MODEL, vc = voice || GEMINI_TTS_DEFAULT_VOICE;
  let lastErr = "failed", dirty = false;
  for (let i = 0; i < ordered.length && i < 8; i++) {
    const k = ordered[i];
    meta[k.name] = meta[k.name] || {}; meta[k.name].lastUsed = Date.now(); dirty = true;
    const r = await _geminiTtsCall(k.value, mdl, vc, style, text);
    if (r.ok) {
      await kv.set(env, GEMINI_TTS_META_KV_KEY, meta, 6 * 3600).catch(() => {});
      return { ok: true, buffer: r.buffer, mimeType: "audio/wav", ext: "wav", voiceNote: false, engine: "gemini" };
    }
    lastErr = `${k.name}: ${r.error}`;
    if (r.status === 429) meta[k.name].cooldownUntil = Date.now() + 60_000;
    else if (r.status === 401 || r.status === 403) meta[k.name].cooldownUntil = Date.now() + 10 * 60_000;
    // 4xx on the request itself (bad model name) will fail on every key — stop early
    else if (r.status === 404) break;
  }
  if (dirty) await kv.set(env, GEMINI_TTS_META_KV_KEY, meta, 6 * 3600).catch(() => {});
  return { ok: false, error: lastErr };
}

class VoiceGen {
  constructor(env) { this.env = env; }

  // Public entry point. `preferAura` (default true) controls which engine
  // goes first, with the other one as an automatic fallback if the first
  // fails — never a hard requirement, so a voice reply never gets lost
  // entirely just because one engine had a bad moment.
  //  - preferAura=true  (Telegram default): Aura-1 first — real OGG/Opus,
  //    sent as a proper round voice-note bubble. Falls back to MeloTTS
  //    (MP3, regular audio bubble) only if Aura-1 errors out.
  //  - preferAura=false (Mini App default): MeloTTS first — cheap, and the
  //    Mini App just plays back a data URL in a plain <audio> tag, so the
  //    OGG-voice-note format Aura-1 buys doesn't matter there; no reason to
  //    pay Aura-1's higher per-character rate for routine in-app replies.
  //    Falls back to Aura-1 only if MeloTTS errors out.
  async generate(text, lang = "en", preferAura = true, style = "", character = "") {
    const prompt0 = String(text || "").trim().slice(0, 600); // keep audio short — this is a chat reply, not an audiobook
    if (!prompt0) return { ok: false, error: "empty text" };
    // Admin-selected engine (Config → Voice). Google = Gemini TTS: speaks the text in
    // its own language (no translate-to-English step), rotates between Gemini keys,
    // and falls through to the Cloudflare engines below if every key fails.
    try {
      const db = this.env.NIKI_DB;
      const gc = db ? await getGC(db) : null;
      if (gc && gc.ttsProvider !== "cloudflare") {
        const modelStyle = gc.ttsAutoStyle !== false ? String(style || "").replace(/[<>\[\]{}\u0000\n\r]/g, " ").replace(/\s+/g, " ").trim().slice(0, 120) : "";
        const ch = resolveVoiceCharacter(character) || resolveVoiceCharacter(gc.ttsCharacter);
        const g = await geminiTtsGenerate(this.env, db, prompt0, { model: gc.ttsModel, voice: ch ? ch.voice : gc.ttsVoice, style: ch ? [ch.style, modelStyle].filter(Boolean).join("; ") : (modelStyle || gc.ttsStyle) });
        if (g.ok) return g;
        console.error("[VoiceGen] Gemini TTS failed:", g.error);
        // The Cloudflare engines only speak English (non-English text would be translated and come
        // out in the WRONG language), so for Persian/other text report the failure instead.
        if (gc.ttsFallback === false) return { ok: false, error: "Gemini TTS: " + String(g.error).slice(0, 160) };
        console.error("[VoiceGen] fallback to Cloudflare enabled");
      }
    } catch (e) { console.error("[VoiceGen] provider switch:", e.message || e); }
    const prompt = lang && lang !== "en" ? await translateToEnglish(this.env, prompt0, lang) : prompt0;

    const [firstFn, secondFn, firstName] = preferAura
      ? [this._generateAura.bind(this), this._generateMelotts.bind(this), "Aura-1"]
      : [this._generateMelotts.bind(this), this._generateAura.bind(this), "MeloTTS"];

    const firstResult = await firstFn(prompt);
    if (firstResult.ok) return firstResult;
    console.error(`[VoiceGen] ${firstName} failed, falling back:`, firstResult.error);
    return secondFn(prompt);
  }

  async _generateMelotts(prompt) {
    if (!this.env.AI) return { ok: false, error: "AI binding not configured" };
    // Cloudflare Workers AI has a known, intermittent "3043: Internal server
    // error" that fires randomly on various models (confirmed on Cloudflare's
    // own community forum, unrelated to request content) — a plain retry
    // succeeds most of the time. Two attempts total, no backoff needed since
    // this isn't a rate-limit, just transient upstream flakiness.
    let lastErr = null;
    for (let attempt = 0; attempt < 2; attempt++) {
      try {
        // returnRawResponse gives back the raw MP3 bytes directly as an
        // HTTP Response body, same pattern as the image models — no base64
        // decoding step needed.
        const resp = await withTimeout(
          this.env.AI.run(VOICE_MODEL, { prompt, lang: "en" }, { returnRawResponse: true }),
          20_000
        );
        if (!resp || resp.ok === false) throw new Error(`TTS HTTP ${resp?.status || "?"}`);
        const buffer = await resp.arrayBuffer();
        if (!buffer || buffer.byteLength === 0) throw new Error("empty audio response");
        const mimeType = resp.headers?.get?.("content-type") || "audio/mpeg";
        return { ok: true, buffer, mimeType, ext: "mp3", voiceNote: false };
      } catch (e) {
        lastErr = e;
        if (attempt === 0) await sleep(400);
      }
    }
    return { ok: false, error: lastErr?.message || "voice generation failed" };
  }

  async _generateAura(prompt) {
    if (!this.env.AI) return { ok: false, error: "AI binding not configured" };
    let lastErr = null;
    for (let attempt = 0; attempt < 2; attempt++) {
      try {
        // encoding:'opus' + container:'ogg' together are what produce a
        // standalone, valid Ogg/Opus file — opus WITHOUT an explicit ogg
        // container comes back as raw, unmuxed opus frames that Telegram
        // (and most players) can't open, which is the classic cause of a
        // "voice message" that shows up as 0 seconds / won't play.
        const resp = await withTimeout(
          this.env.AI.run(AURA_MODEL, {
            text: prompt,
            speaker: AURA_SPEAKER,
            encoding: "opus",
            container: "ogg",
          }, { returnRawResponse: true }),
          20_000
        );
        if (!resp || resp.ok === false) throw new Error(`Aura-1 HTTP ${resp?.status || "?"}`);
        const buffer = await resp.arrayBuffer();
        if (!buffer || buffer.byteLength === 0) throw new Error("empty audio response");
        return { ok: true, buffer, mimeType: "audio/ogg", ext: "ogg", voiceNote: true };
      } catch (e) {
        lastErr = e;
        if (attempt === 0) await sleep(400);
      }
    }
    return { ok: false, error: lastErr?.message || "Aura-1 generation failed" };
  }

  // sendAudio — MeloTTS only outputs MP3 (no OGG/Opus), so this shows as a
  // regular playable audio-file bubble rather than Telegram's round "voice
  // note" bubble (sendVoice requires OGG/Opus specifically).
  async sendAudio(env, chatId, buffer, mimeType, ext, caption, replyTo) {
    const form = new FormData();
    form.append("chat_id", String(chatId));
    form.append("audio", new Blob([buffer], {type:mimeType}), `niki.${ext}`);
    form.append("title", (_gcCache && _gcCache.botName) || "Niki");
    // Without an explicit duration, Telegram was showing "0:00" on the
    // audio bubble — it doesn't reliably probe the actual file for this.
    const durationSec = ext === "mp3" ? estimateMp3DurationSeconds(buffer) : ext === "wav" ? wavDurationSeconds(buffer) : null;
    if (durationSec) form.append("duration", String(durationSec));
    if (caption) { form.append("caption", caption); form.append("parse_mode", "HTML"); }
    if (replyTo) form.append("reply_to_message_id", String(replyTo));
    try {
      const res = await fetchWithTimeout(tgUrl(env,"sendAudio"), {method:"POST", body:form}, 20_000);
      if (res.status === 429) {
        const d = await res.json().catch(() => ({}));
        const retryAfter = d?.parameters?.retry_after ?? 1;
        return {ok:false, error:`rate limited (retry_after=${retryAfter}s)`, rateLimited:true, retryAfter};
      }
      const d = await res.json();
      return res.ok ? {ok:true} : {ok:false, error:d.description||`HTTP ${res.status}`};
    } catch(e) { return {ok:false, error:e.message}; }
  }

  // sendVoice — the real round "voice note" bubble. Requires a valid
  // OGG/Opus file, which only the Aura-1 path (above) currently produces.
  async sendVoice(env, chatId, buffer, caption, replyTo, mime = "audio/ogg", ext = "ogg") {
    const form = new FormData();
    form.append("chat_id", String(chatId));
    form.append("voice", new Blob([buffer], {type:mime}), `niki.${ext}`);
    if (caption) { form.append("caption", caption); form.append("parse_mode", "HTML"); }
    if (replyTo) form.append("reply_to_message_id", String(replyTo));
    try {
      const res = await fetchWithTimeout(tgUrl(env,"sendVoice"), {method:"POST", body:form}, 20_000);
      if (res.status === 429) {
        const d = await res.json().catch(() => ({}));
        const retryAfter = d?.parameters?.retry_after ?? 1;
        return {ok:false, error:`rate limited (retry_after=${retryAfter}s)`, rateLimited:true, retryAfter};
      }
      const d = await res.json();
      return res.ok ? {ok:true} : {ok:false, error:d.description||`HTTP ${res.status}`};
    } catch(e) { return {ok:false, error:e.message}; }
  }
}
// ─── _sanitizeVoiceText — defensive cleanup before speaking anything ──────
// The tool description tells the model never to wrap the spoken text in
// bracketed annotations ("[speak happily]", "[Translation]") or labels
// ("English:"), but instructions alone aren't 100% reliable — when the
// model slips, MeloTTS reads the brackets/labels themselves aloud as
// garbled text. This strips them as a safety net regardless of what the
// prompt achieves on its own.
function _sanitizeVoiceText(text) {
  let t = String(text || "").trim();
  t = t.replace(/\[[^\]]{0,80}\]/g, " ").replace(/\s+/g, " ").trim();
  t = t.replace(/^(english|translation|ترجمه|متن انگلیسی)\s*:\s*/i, "").trim();
  return t;
}
async function handleVoice(env, db, chatId, msgId, text, voiceGen, caption=null, lang="en", style="", character="") {
  const r = await voiceGen.generate(text, lang, true, style, character);
  if (r.ok) {
    // r.voiceNote tells us which engine actually ran (Aura-1 → real OGG/Opus
    // voice note; MeloTTS fallback → regular MP3 audio bubble) — this only
    // differs from the normal Aura-1 path if Aura-1 failed and we silently
    // fell back to the cheap engine.
    const s = r.voiceNote
      ? await voiceGen.sendVoice(env, chatId, r.buffer, caption||null, msgId)
      : await voiceGen.sendAudio(env, chatId, r.buffer, r.mimeType, r.ext, caption||null, msgId);
    await react(env,chatId,msgId, s.ok?"🔊":"❌");
    if (!s.ok) await sendMsg(env,db,chatId,`❌ ارسال صدا ناموفق: ${s.error}`,msgId);
  } else {
    console.error("[VoiceGen]", r.error);
    await react(env,chatId,msgId,"❌");
    // r.error is often a raw Cloudflare error code (e.g. "3043: Internal
    // server error") which means nothing to an end user and, worse, looks
    // like OUR bug when it's really a transient upstream failure — already
    // retried once inside VoiceGen.generate. Show something actionable
    // instead; the real error is still logged above for debugging.
    if (String(r.error || "").startsWith("Gemini TTS")) log(db, { chatId, userId: chatId, action: "tts_failed", level: "error", detail: String(r.error).slice(0, 300) }).catch(()=>{});
    await sendMsg(env,db,chatId,String(r.error || "").startsWith("Gemini TTS")
      ? "❌ ساخت ویس با گوگل الان جواب نداد (احتمالاً لیمیت کلیدها یا نام مدل صدا) — چند لحظه بعد دوباره امتحان کن. دلیل دقیق تو لاگ‌های پنل ادمین ثبت شد."
      : "❌ سرویس تولید صدا الان جواب نداد (مشکل موقتیه، احتمالاً از سمت کلادفلر) — یه بار دیگه امتحان کن.",msgId);
  }
}

// ─── _runImageCallAlongside — let an admin action ALSO generate the image ──
// the model asked for in the SAME turn, instead of the two being mutually
// exclusive just because delete/pin/unpin/.../quiz each `return` as soon as
// their own action is done (see the dispatch chain in
// _handleTelegramUpdateInner). Handles its own limit-checking exactly like
// the standalone generate_image/generate_images branches do; the caller
// only needs to push this into the SAME `tasks` array it's already
// Promise.all-ing its own action with, so "pin this AND make me a picture"
// actually does both, concurrently, instead of only whichever function
// call happened to be checked first.
async function _runImageCallAlongside(env, db, chatId, msgId, userId, userName, isPriv, imageCall, imagesCall, imgGen) {
  if (!imageCall && !imagesCall) return;
  try {
    if (imageCall?.args?.prompt) {
      const imgPrompt = String(imageCall.args.prompt).trim();
      if (!imgPrompt || !env.AI) return;
      if (!isPriv) {
        const gl = await consumeGroupLimit(env,db,chatId,"img");
        if (!gl.allowed) return;
      }
      const iuc = await consumeUserLimit(env,db,userId,userName,"img",chatId);
      if (!iuc.allowed) return;
      await appendHistory(db,chatId,{user:"AI",text:`[درخواست تولید تصویر: ${imgPrompt.slice(0,80)}]`,ts:new Date().toISOString()});
      await sendTyping(env,chatId,"upload_photo");
      await handleImage(env,db,chatId,msgId,imgPrompt,imgGen,imageCall.args?.caption?.trim()||null);
    } else if (imagesCall?.args?.images?.length) {
      const gc = await getGC(db);
      const multiEnabled = isPriv ? gc.multiPhotoPrivate : gc.multiPhotoGroup;
      const maxPhotos = Math.min(gc.maxMultiPhoto || C.MAX_MULTI_PHOTO, C.HARD_CAP_MULTI_PHOTO);
      let rawRequests = imagesCall.args.images.filter(r => r?.prompt?.trim());
      rawRequests = multiEnabled ? rawRequests.slice(0, maxPhotos) : rawRequests.slice(0, 1);
      if (!rawRequests.length || !env.AI) return;
      const allowedRequests = [];
      for (const req of rawRequests) {
        if (!isPriv) {
          const gl = await consumeGroupLimit(env,db,chatId,"img");
          if (!gl.allowed) break;
        }
        const iuc = await consumeUserLimit(env,db,userId,userName,"img",chatId);
        if (!iuc.allowed) break;
        allowedRequests.push(req);
      }
      if (!allowedRequests.length) return;
      await appendHistory(db,chatId,{user:"AI",text:`[تولید ${allowedRequests.length} تصویر]`,ts:new Date().toISOString()});
      await sendTyping(env,chatId,"upload_photo");
      if (allowedRequests.length === 1) {
        await handleImage(env,db,chatId,msgId,allowedRequests[0].prompt,imgGen,allowedRequests[0].caption||null);
      } else {
        await handleMultiImage(env,db,chatId,msgId,allowedRequests,imgGen);
      }
    }
  } catch (e) {
    console.error("[_runImageCallAlongside]", e?.message || e);
  }
}

// ═══════════════════════════════════════════════════════════════
// § 9  REACTIONS
// ═══════════════════════════════════════════════════════════════
// @FILE-SPLIT → src/config.js
// REACTIONS/REACTION_FALLBACK_REPLIES/_KNOWN_TOOL_NAMES/
// _stripLeakedFunctionSyntax/reactionForMedia/reactionForText. Only needs
// `rand`, already in config.js per the new plan.

const REACTIONS = [
  [/(😂|🤣|خنده|باحال|مضحک|ههه)/i,         ["😂","🤣","😆","😄"]],
  [/(\?|سوال|چطور|چرا|کی|کجا|چی)/i,         ["🤔","❓","💭","🧐"]],
  [/(واو|عجب|شکه|حیرت|جدی)/i,               ["🤯","😲","😮","👀"]],
  [/(❤|عشق|دوستت|محبت|ناز|زیبا)/i,          ["❤️","💕","🥰","😍"]],
  [/(😢|😭|غم|ناراحت|گریه)/i,               ["😢","😭","🥺","😔"]],
  [/(😡|عصبانی|اعصاب|خشم)/i,                ["😡","🤬","👿","💢"]],
  [/(مرسی|ممنون|دستت درد نکنه|تشکر)/i,      ["🙏","💝","🤗","😊"]],
  [/(کد|پایتون|برنامه|کدنویسی|دیباگ)/i,     ["💻","👩‍💻","🐍","🔧"]],
  [/(گیم|بازی|گیمر|استیم)/i,                ["🎮","👾","🕹️","🎯"]],
  [/(ربات|هوش مصنوعی|ai|gemini)/i,          ["🤖","🧠","⚡","🔮"]],
  [/(عکس|تصویر|photo|picture)/i,            ["📸","🖼️","👀","🔍"]],
  [/(صدا|وویس|voice|آهنگ|موزیک)/i,          ["🎤","🎧","👂","🎵"]],
  [/(ویدیو|video|فیلم)/i,                    ["🎬","📹","👀","🎥"]],
];

// ─── _stripLeakedFunctionSyntax — defense in depth ─────────────────────────
// Even with a tuned thinking budget, the model can occasionally write a
// function call out as literal text instead of issuing a real structured
// functionCall part — e.g. "react_to_message(emoji='😂')باشه باشه فهمیدم!"
// — which then gets sent to the user verbatim since it's non-empty text.
// Strip a known-tool-name(...) fragment if one leaks into the text.
//
// NOTE on the {0,4000} cap: this used to be {0,300}, which was fine for
// short-arg tools like react_to_message(emoji='😂') but silently failed to
// match — and therefore let the WHOLE leaked call through verbatim — for
// generate_image(prompt='...', caption='...'), since a detailed English
// image prompt + Persian caption routinely runs 350–500+ chars on its own,
// past the old cap. [^)]{0,300} requires a closing ')' within 300 chars or
// the match fails entirely; it doesn't "match what it can" and stop. Raised
// generously since the class already excludes ')' itself, so this stays
// cheap (no catastrophic backtracking risk) regardless of the cap size.
const _KNOWN_TOOL_NAMES = ["react_to_message","delete_message","pin_message","unpin_message","unpin_all_messages","delete_last_messages","cleanup_chat","generate_image","generate_images"];
function _stripLeakedFunctionSyntax(text) {
  if (!text) return text;
  let out = text;
  for (const name of _KNOWN_TOOL_NAMES) {
    // e.g. `react_to_message(emoji='😂')` or `react_to_message({"emoji":"😂"})`
    const re = new RegExp(`${name}\\s*\\([^)]{0,4000}\\)\\s*`, "g");
    out = out.replace(re, "");
  }
  return out.trim();
}

function reactionForMedia(mediaType) {
  return {audio:"🎤",gif:"🌀",image:"📸",video:"🎬"}[mediaType]||"👀";
}
// ─── _extractKnownEmoji — pull out a Telegram-reaction-eligible emoji the
// model itself already wrote in its reply text, if any. Longest variants
// checked first (e.g. "❤️‍🔥" before plain "❤️") so a multi-codepoint emoji
// isn't mistaken for a shorter one it happens to contain; ties on position
// go to the longer match since it's checked first and the comparison is
// strict "<". This is the primary signal for automatic reactions — only
// when the model's text has none of these do we fall back to the
// keyword/topic-based REACTIONS pool below.
const _REACTION_EMOJI_SORTED = [...REACTION_EMOJIS].sort((a,b)=>b.length-a.length);
function _extractKnownEmoji(text) {
  if (!text) return null;
  let best = null, bestIdx = Infinity;
  for (const ch of _REACTION_EMOJI_SORTED) {
    const idx = text.indexOf(ch);
    if (idx !== -1 && idx < bestIdx) { bestIdx = idx; best = ch; }
  }
  return best;
}
function reactionForText(text) {
  if (!text?.trim()) return "💬";
  const literal = _extractKnownEmoji(text);
  if (literal) return literal;
  for (const [pat, pool] of REACTIONS) if (pat.test(text)) return rand(pool);
  const w = text.split(/\s+/).length;
  if (w>50) return "📖";
  if (w>8)  return rand(["😊","🙂","👌","💬","✨","🌟"]);
  return rand(["👍","👌","✨","😊","🙂","👀"]);
}

// ─── Reactions come from the USER's message, never from the AI's reply ──────
// Rule-based: mirror an emoji the user wrote (rude ones excluded), else keyword/topic
// match on the user's text, else neutral. An explicit request ("ریاکشن 🔥 بزن",
// "react with fire") always wins.
const _REACTION_REQUEST_RE = /(ری[\s\u200c]?اکشن|ریکشن|react(?:ion)?)/i;
const _AUTO_REACT_BLOCK = new Set(["🖕","💩","🤮","🤬","👎","🤡","😈","💋"]);
const _REACTION_WORDS = [
  [/(دیس[\s\u200c]?لایک|dislike|thumbs?\s?down)/i, "👎"],
  [/(لایک|\blike\b|thumbs?\s?up)/i, "👍"],
  [/(قلب|\bheart\b|\blove\b)/i, "❤️"],
  [/(آتیش|آتش|\bfire\b)/i, "🔥"],
  [/(تشویق|کف[\s\u200c]?زدن|\bclap\b)/i, "👏"],
  [/(خنده|\blaugh\b|\blol\b)/i, "🤣"],
  [/(گریه|\bcry\b)/i, "😭"],
  [/(تعجب|شوکه|\bwow\b)/i, "🤯"],
  [/(تبریک|جشن|\bparty\b|congrat)/i, "🎉"],
  [/(عالی|\b100\b|perfect)/i, "💯"],
  [/(اوکی|\bok(ay)?\b)/i, "👌"],
];
function _explicitReactionEmoji(text) {
  const t = String(text || "");
  if (!_REACTION_REQUEST_RE.test(t)) return null;
  const lit = _extractKnownEmoji(t);
  if (lit) return lit;
  for (const [re, em] of _REACTION_WORDS) if (re.test(t)) return em;
  return null;
}
function reactionForUserText(text) {
  const t = String(text || "").trim();
  if (!t) return "💬";
  const lit = _extractKnownEmoji(t);
  if (lit && !_AUTO_REACT_BLOCK.has(lit)) return lit;
  for (const [pat, pool] of REACTIONS) if (pat.test(t)) return rand(pool);
  const w = t.split(/\s+/).length;
  if (w > 50) return "📖";
  if (w > 8)  return rand(["😊","🙂","👌","💬","✨","🌟"]);
  return rand(["👍","👌","✨","😊","🙂","👀"]);
}

// ═══════════════════════════════════════════════════════════════
// § 10  SYSTEM PROMPT
// ═══════════════════════════════════════════════════════════════
// @FILE-SPLIT → src/config.js
// buildSystemPrompt only — Niki's whole persona text. Zero code deps (pure
// string template), but note it's substantively CONTENT, not logic — worth
// keeping as its own clearly-marked section within config.js so it's easy
// to find and hand to a non-developer to edit without touching anything else.

// ─── _codeRules — shared hard rule for how code must be written/sent ──────
// Used by every mode so the "claimed code but didn't include it" failure
// mode can't happen regardless of which persona is active.
const _codeRules = `
- FORMATTING: CODE IS ALWAYS A HARD EXCEPTION TO ANY "SHORT/CASUAL MESSAGE"
  STYLE RULE ELSEWHERE IN THIS PROMPT: if the user asks for code, a script,
  a program, or a snippet, write the COMPLETE, ACTUAL, WORKING code every
  single time, no matter how long it is. Wrap it in a fenced block with the
  language name, e.g. \`\`\`python\\nprint("hi")\\n\`\`\` — for a short inline
  command or variable name use single backticks, e.g. \`pip install requests\`.
  ABSOLUTELY FORBIDDEN: saying "I wrote it", "here's the code", "بیا
  نوشتمش", "کدشو زدم", or any similar claim UNLESS the actual \`\`\`fenced
  code\`\`\` is included in that exact same message. Never promise code and
  send it "later" or in a separate message — the code must be in THIS
  message, right now, in full. If you don't include the real code, don't
  claim you wrote any.`;

// ─── _toolsBlock — shared tool-usage rules (images/voice/reactions/mini app) ──
// These Gemini function-tools are always declared regardless of persona/mode,
// so every mode needs to know how/when to use them — one shared block instead
// of copy-pasted per mode so a future tool-behavior fix only happens once.
function _toolsBlock(personaName) {
  return `
📸 IMAGES FROM USER — CRITICAL:
- When user sends a photo/image, YOU CAN SEE IT. React naturally to what you see.
- If user sends photo WITHOUT writing "${personaName}", they're STILL talking to you. Reply.
- In later messages, if user refers to "the photo/عکس", remember you saw it.
- Past messages with [📸 عکس] mean a photo was sent earlier — remember it.

🎨 IMAGE GENERATION — CRITICAL RULES:
- You have a "generate_image" function/tool available. USE IT whenever user asks for any image/photo/picture/drawing.
- Farsi triggers: عکس، تصویر، بکش، طراحی کن، نقاشی، یه عکس، برام عکس
- When image is requested: call generate_image() with a detailed English prompt. Do NOT describe the image in text instead.
- For MULTIPLE images (e.g. "چند عکس بده", "3 عکس", "a few pictures", "2 different images"): call generate_images() with an array of DIFFERENT prompts. Max 4. Each prompt should be unique — don't repeat.
- If user says "یه عکس" or asks for ONE image, always use generate_image() (single).
- prompt must be detailed (style, colors, mood, lighting, composition).
- caption should be a short, warm sentence in your reply language.

😀 EMOJI REACTIONS — HANDLED BY THE SYSTEM, NOT BY YOU:
- There is no reaction tool/function — never try to call one for this.
- The reaction on the user's message is picked by the system from the USER's own message text, never from your reply. Emojis in your reply do not become reactions, so just write naturally.
- If the user explicitly asks for a specific reaction (e.g. "react with 🔥"), the system applies it for you — you may briefly acknowledge it in text, nothing more.

🔊 VOICE MESSAGES — ONLY WHEN EXPLICITLY ASKED:
- You have a "generate_voice" function/tool that turns text into a spoken audio message. Use it ONLY when the user clearly asks to hear something spoken — Farsi: صدا، ویس، بگو، با صدا، صوتی بفرست؛ English: say it, voice message, read this out loud. Also use it for pronunciation practice (e.g. teaching a word in the language-tutor skill).
- Keep the spoken text short (1-3 sentences, or a single word/phrase for pronunciation) — it's a chat voice note, not a narration.
- LANGUAGE: the voice engine only speaks English. Always translate the text to natural English first and put that in \`text\`. Your visible chat message can stay in the original language as always; only the audio itself changes language.
- CRITICAL — \`text\` must be ONLY the words to actually speak. Never wrap it in brackets or labels like "[speak happily]", "[Translation]", or "English:" — the engine reads those literally out loud as garbled noise. Just the plain sentence, nothing else.
- ALWAYS write a real text reply in the same turn as generate_voice — never let the voice message be your entire response with no accompanying text (same rule as reactions: audio is an extra layer, not a replacement for actually replying).
- Teaching/demonstrating more than one word or sentence at once? Call generate_voice ONCE PER ITEM (separate calls), not one call with everything mashed together — otherwise the user hears one confusing run-on clip and can't tell which word was which.
- Don't default to voice for every message — it's opt-in per request, same as image generation.

📱 MINI APP — YOU HAVE A GRAPHICAL WEB APP INSIDE TELEGRAM:
- ${personaName} has a proper Telegram Mini App (a graphical, ChatGPT-style app that opens right inside Telegram — not a browser). It shows this same chat, a quiz section, and the user's usage stats, in a visual interface. Users open it with the "🧊 اپ ${personaName} / ${personaName} App" button (from /app, /start, or the chat's menu button).
- If the user asks things like "این اپ چیه؟", "مینی اپ چی داره؟", "میشه گرافیکی ببینمت؟", "do you have an app?", "what's the mini app" — explain briefly, warmly, in their own language, and mention the /app command/button opens it. Don't over-explain technical details (Telegram, WebView, etc.) — just describe what they'll see (chat + quizzes + stats).
- The Mini App ONLY opens from inside the Telegram app itself (mobile or desktop) — it cannot be opened from a regular browser. That's expected behavior, not a bug — if a user says it didn't open in their browser, tell them to tap the button inside Telegram instead.
- create_quiz (below) is what populates the Mini App's quiz section — when you build a quiz, remind the user it opens inside that same app.

🛠️ TROUBLESHOOTING — WHEN THE USER SAYS SOMETHING "ISN'T WORKING":
Users sometimes report a real platform limitation, not a bug — recognize these and give an honest, useful answer instead of just apologizing vaguely or making something up:
- "ویس نمیاد / صدا کار نمیکنه" (voice generation not working / no sound): voice is a feature the bot admin can turn on/off and cap per user/day from the admin panel — if it's off or the quota's hit, no amount of retrying fixes it from your side. Tell them honestly it might be disabled or their voice quota's used up for now, and to ask the bot's admin to check/raise it — don't just say "دوباره امتحان کن" as if it were a random glitch.
- A long reply arrived as several separate messages, or a code block got cut off mid-way: Telegram caps a single message at ~4096 characters — anything longer is auto-split into consecutive messages by the bot itself. That's expected, not an error.
- A sent photo/voice/video seems to have been ignored (you got no reaction to it at all): occasionally a file download from Telegram's side fails (network hiccup) — the honest answer is "simply resend it," not to guess wildly at other causes.
- "این عکس/دستور کار نکرد" for group-only moderation actions (delete/pin/unpin a message, cleanup): these need YOU (the bot) to actually have admin rights with the matching permission in that specific group — if they fail, the real fix is the group's human admin needs to promote the bot with that permission, not a bot-side bug.
- "امروز جواب نمیده" / a feature that worked before suddenly stopped for one user specifically: every feature (messages, images, voice) has a daily/total quota per user and per group — check if they've simply hit today's limit (mention /limits if it exists, or that the admin can raise it) before assuming anything else is wrong.
- The Mini App only opens from inside the real Telegram app (see above) — "it won't open in my browser" is expected, not a bug.
- If none of the above matches what they're describing, say so honestly — don't invent a technical explanation you're not sure about; suggest they try again, resend, or mention it to the bot's admin.`;
}

// ─── PUBLIC_PROMPT_TEXT — the default system prompts for modes 1 and 2 ──────
// Plain, generic text so anyone can edit it. Modes: 1 = friendly, 2 = deeper/analytical.
const PUBLIC_PROMPT_TEXT = {
  group: {
    1: "You are Niki, a friendly and helpful AI assistant in a Telegram group. Treat every member equally and keep replies short and clear.",
    2: "You are Niki, a thoughtful AI assistant in a Telegram group. Give clear, well-reasoned answers and explain your thinking when it helps. Treat every member equally.",
  },
  private: {
    1: "You are Niki, a friendly and helpful AI assistant in a private Telegram chat. Be warm, natural and to the point.",
    2: "You are Niki, a thoughtful AI assistant in a private Telegram chat. Give clear, well-reasoned answers and go deeper when the topic needs it.",
  },
};

function buildSystemPrompt(mode, displayName, isPrivate, webSearchEnabled=false, replyLang="auto", botName="") {
  const nameHint = displayName ? `\n\n🏷️ THE USER'S NAME: Call them "${displayName}" naturally sometimes.` : "";
  const wsHint = webSearchEnabled ? `

🌐 WEB SEARCH — ACTIVE:
- You have web_search enabled. USE IT when the user asks about: prices (gold, currencies, crypto, stocks — قیمت طلا، دلار), news (اخبار), weather (آب‌وهوا), sports results, current events, or anything time-sensitive.
- Also use it when the user says things like: "search for", "look it up", "check online", سرچ کن، جستجو کن، برو ببین.
- After searching, summarize the result naturally in your normal reply language (see the LANGUAGE rule) — don't paste raw data or long URLs.
- If search returns no result, say so honestly.` : "";

  // ── MODE 4 — English teaching ────────────────────────────────────────
  // A dedicated tutor persona, not the casual-teen persona used by 1/2.
  if (mode === 4) {
    const body = `
🎯 CORE RULES:
- You are a patient, encouraging English teacher.
${replyLang === "fa"
  ? `- The student's native language is Farsi. Default to bilingual replies: explain in simple English, then a short Farsi
  clarification when a concept, grammar rule, or word might be unclear —
  keep the Farsi part brief, it's a safety net, not the main content.`
  : `- Explain in clear, simple English. If the student writes in another language, add a very short clarification in
  THEIR language when a concept, grammar rule or word might be unclear — keep it brief, it's a safety net, not the main content.`}
- Actively correct the student's English mistakes: quote the wrong part,
  give the correct version, and a one-line reason (grammar rule, common
  usage, etc). Do this gently — praise what's right before correcting what's wrong.
- Adapt to the student's level as it becomes clear from their messages
  (beginner/intermediate/advanced) — don't overwhelm a beginner with jargon.
- Proactively teach: introduce a new useful word, idiom, or grammar point
  naturally in context every so often, not as a robotic list.
- Use generate_voice (see tools below) when the student asks to hear
  pronunciation, or when teaching a new word/phrase — hearing it matters.
- FORMATTING: plain conversational text is fine for explanations; use a
  fenced code block ONLY for structured drills/tables if genuinely useful.${_codeRules}
- Be warm and human, not a rigid textbook.${nameHint}${wsHint}
${_toolsBlock("این ربات")}`.trim();
    return isPrivate
      ? `You are an English-teaching assistant in a private Telegram chat.\n\n${body}`
      : `You are an English-teaching assistant in a Telegram group chat.\n\n${body}`;
  }

  // ── MODE 5 — Programming ─────────────────────────────────────────────
  // A dedicated coding-assistant persona: precise, technical, no roleplay.
  if (mode === 5) {
    const body = `
🎯 CORE RULES:
- You are a precise, knowledgeable programming assistant. No roleplay
  persona, no flirting, no "mood" acting — be direct, technical, and useful,
  like a senior developer helping a colleague.
- Answer in the same language the user writes in (Farsi or English);
  explanations can be Farsi, but the CODE ITSELF stays in real code syntax
  (never translate variable/function names into Farsi).
- Always explain briefly WHAT the code does and WHY, not just paste it —
  a short explanation before or after the code block, not a huge essay.
- If the user's request is ambiguous (language/framework/version unclear),
  make a reasonable assumption, state it in one line, and proceed — don't
  block on clarifying questions unless truly necessary.
- When fixing/reviewing code the user pasted, point out the specific bug
  or issue clearly before giving the corrected version.${_codeRules}
- Be honest about tradeoffs, edge cases, or when you're not fully sure —
  don't invent APIs or behavior you're not confident about.${nameHint}${wsHint}
${_toolsBlock("این ربات")}`.trim();
    return isPrivate
      ? `You are a programming assistant in a private Telegram chat.\n\n${body}`
      : `You are a programming assistant in a Telegram group chat.\n\n${body}`;
  }

  // ── MODES 1/2 — Niki, the public default assistant ──────────────────
  // Neutral on purpose. Admins/users override it from the panel
  // (Config → Default prompts) or per chat; edit PUBLIC_PROMPT_TEXT to change the default.
  const base = `
🎯 CORE RULES:
- Be friendly, clear and helpful. Keep replies short unless the user asks for detail.
- Write ONLY your message — no action descriptions in parentheses.
- Be honest: if you don't know something, say so.${_codeRules}${nameHint}${wsHint}
${_toolsBlock(_triggerLabel())}

IMAGE RULES: Nothing explicit. Call the image function EVERY time the user asks for an image.`.trim();

  // Use configured botName in the opening "You are X" line when set; otherwise keep "Niki".
  // Empty botName still works — falls back to "Niki".
  const bn = String(botName || "").replace(/[<>\u0000\r\n]/g, " ").trim().slice(0, 40) || "Niki";
  let role = PUBLIC_PROMPT_TEXT[isPrivate ? "private" : "group"][mode === 2 ? 2 : 1];
  if (bn !== "Niki") role = role.replace(/\bNiki\b/g, bn);
  return `${role}\n\n${base}`;
}

// ═══════════════════════════════════════════════════════════════
// § 11  REPLY DECISION
// ═══════════════════════════════════════════════════════════════
// @FILE-SPLIT → src/webhook.js — NOT config.js despite what the master
// plan comment at the top of the file says. shouldReply reads the F.*
// flags (chat-config, § 4c) which live in webhook.js per the new plan;
// putting this tiny function in config.js would mean config.js has to
// import from webhook.js, which is backwards (webhook.js is supposed to be
// the one importing everything else, nothing imports from it). One
// function, used only from _handleTelegramUpdateInner — just keep it right
// there in webhook.js.

async function shouldReply(env, db, chatId, rawText, isPrivate, hasMedia=false, opts={}) {
  // independent lookups run together (getGC also keeps the configurable trigger words in sync)
  const [_sil, _aon] = await Promise.all([
    F.silent(env, db, chatId),
    (isPrivate || opts.noAlways) ? false : F.alwaysOn(env, db, chatId),
    getGC(db).catch(() => null),
  ]);
  if (_sil) return false;
  if (isPrivate) return true;
  const aon = _aon;
  if (aon) return true;
  // photo/voice/video — reply even without the niki trigger
  if (hasMedia && !opts.noMediaReply) return true;
  return C.TRIGGER.test(rawText);
}

