function dmFriendlyError(err){
  const e=(err||'').toLowerCase();
  if(e.includes('blocked')) return '❌ ارسال نشد — کاربر ربات رو بلاک کرده';
  if(e.includes('chat not found')||e.includes('user not found')) return '❌ ارسال نشد — این کاربر هنوز با ربات چت نکرده (chat not found)';
  if(e.includes('bot was kicked')||e.includes('kicked')) return '❌ ارسال نشد — ربات از این چت حذف/کیک شده';
  if(e.includes('deactivated')) return '❌ ارسال نشد — این اکانت تلگرام دیگه فعال نیست';
  return '❌ ارسال نشد — '+(err||'خطای نامشخص');
}
