function ddEnhance(sel){
  if(sel._dd)return;sel._dd=1;
  const wrap=document.createElement('div');wrap.className='dd-wrap';
  const btn=document.createElement('button');btn.type='button';btn.className='dd-btn';
  btn.innerHTML='<span class="dd-cur"></span><svg class="dd-arrow" viewBox="0 0 10 6"><path d="M0 0l5 6 5-6z" fill="currentColor"/></svg>';
  const panel=document.createElement('div');panel.className='dd-panel';
  const cur=btn.querySelector('.dd-cur');
  function label(o){return o.getAttribute('data-d')?o.textContent+' · '+o.getAttribute('data-d'):o.textContent;}
  function sync(){const o=sel.options[sel.selectedIndex];cur.textContent=o?label(o):'';panel.querySelectorAll('.dd-opt').forEach(function(e){e.classList.toggle('sel',e.getAttribute('data-v')===sel.value);});}
  function addOpt(o){
    const d=document.createElement('div');d.className='dd-opt';d.setAttribute('data-v',o.value);
    const dd=o.getAttribute('data-d');
    d.innerHTML='<span class="dd-ck">✓</span><span class="dd-n"></span>'+(dd?'<span class="dd-d"></span>':'');
    d.querySelector('.dd-n').textContent=dd?o.textContent:o.textContent;
    if(dd)d.querySelector('.dd-d').textContent=dd;
    d.addEventListener('click',function(){sel.value=o.value;sync();wrap.classList.remove('open');sel.dispatchEvent(new Event('change'));});
    panel.appendChild(d);
  }
  Array.from(sel.children).forEach(function(ch){
    if(ch.tagName==='OPTGROUP'){const g=document.createElement('div');g.className='dd-grp';g.textContent=ch.label;panel.appendChild(g);Array.from(ch.children).forEach(addOpt);}
    else addOpt(ch);
  });
  btn.addEventListener('click',function(e){e.stopPropagation();const was=wrap.classList.contains('open');document.querySelectorAll('.dd-wrap.open').forEach(function(w){w.classList.remove('open');});if(!was){wrap.classList.add('open');const s=panel.querySelector('.dd-opt.sel');if(s)panel.scrollTop=Math.max(0,s.offsetTop-80);}});
  panel.addEventListener('click',function(e){e.stopPropagation();});
  wrap.appendChild(btn);wrap.appendChild(panel);sel.parentNode.insertBefore(wrap,sel.nextSibling);sync();
}
document.addEventListener('click',function(){document.querySelectorAll('.dd-wrap.open').forEach(function(w){w.classList.remove('open');});});
document.addEventListener('keydown',function(e){if(e.key==='Escape')document.querySelectorAll('.dd-wrap.open').forEach(function(w){w.classList.remove('open');});});
function ddInitAll(){document.querySelectorAll('select.dd').forEach(ddEnhance);}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',ddInitAll);else ddInitAll();
