async function saveConfig(sec){
  let b={};
  if(sec==='defaults')b={defaultMsgLimit:+document.getElementById('cf-defaultMsgLimit').value,defaultImgLimit:+document.getElementById('cf-defaultImgLimit').value,defaultVoiceLimit:+document.getElementById('cf-defaultVoiceLimit').value,defaultDailyMsgLimit:+document.getElementById('cf-defaultDailyMsgLimit').value,defaultDailyImgLimit:+document.getElementById('cf-defaultDailyImgLimit').value,defaultDailyVoiceLimit:+document.getElementById('cf-defaultDailyVoiceLimit').value};
  else if(sec==='groupDefaults')b={defaultGroupMsgLimit:+document.getElementById('cf-defaultGroupMsgLimit').value,defaultGroupImgLimit:+document.getElementById('cf-defaultGroupImgLimit').value,defaultGroupVoiceLimit:+document.getElementById('cf-defaultGroupVoiceLimit').value,defaultGroupDailyMsg:+document.getElementById('cf-defaultGroupDailyMsg').value,defaultGroupDailyImg:+document.getElementById('cf-defaultGroupDailyImg').value,defaultGroupDailyVoice:+document.getElementById('cf-defaultGroupDailyVoice').value};
  else if(sec==='groupPrompts')b={defaultGroupPrompt1:document.getElementById('cf-defaultGroupPrompt1').value,defaultGroupPrompt2:document.getElementById('cf-defaultGroupPrompt2').value};
  else if(sec==='privatePrompts')b={defaultPrivatePrompt1:document.getElementById('cf-defaultPrivatePrompt1').value,defaultPrivatePrompt2:document.getElementById('cf-defaultPrivatePrompt2').value};
  else if(sec==='apiPrompt')b={apiDefaultPrompt:document.getElementById('cf-apiDefaultPrompt').value,apiMaxHistory:+document.getElementById('cf-apiMaxHistory').value};
  else if(sec==='welcome')b={welcomeMsgLimit:+document.getElementById('cf-welcomeMsgLimit').value,welcomeImgLimit:+document.getElementById('cf-welcomeImgLimit').value,welcomeVoiceLimit:+document.getElementById('cf-welcomeVoiceLimit').value};
  else if(sec==='swpriv'||sec==='swgrp'){var kd=sec==='swpriv'?'priv':'grp';var off=[];document.querySelectorAll('.sw-'+kd).forEach(function(c){if(!c.checked)off.push(c.getAttribute('data-key'));});b=sec==='swpriv'?{disabledPrivate:off}:{disabledGroup:off};}
  else if(sec==='dailyCaps'){var dc={private:{},group:{}};['private','group'].forEach(function(tp){['msg','img','voice'].forEach(function(k){dc[tp][k]=+document.getElementById('cap-'+tp+'-'+k).value||0;});});b={dailyCaps:dc};}
  else if(sec==='welcomeTexts')b={welcomeEnabled:document.getElementById('welcomeEnabled').checked,welcomeTextPrivate:welcomeVal('welcomeTextPrivate'),welcomeTextGroup:welcomeVal('welcomeTextGroup')};
  else if(sec==='maintenance')b={maintenanceMode:document.getElementById('maintenanceMode').checked,maintenanceText:document.getElementById('maintenanceText').value};
  else if(sec==='miniApp'){b={};MINI_KEYS.forEach(function(k){b[k]=document.getElementById('cf-'+k).checked;});}
  else if(sec==='promptModes'){var pm=[];document.querySelectorAll('.pm-chk').forEach(function(c){if(!c.checked)pm.push(+c.getAttribute('data-mode'));});b={disabledModes:pm};}
  else if(sec==='voice')b={voiceEnabled:document.getElementById('cf-voiceEnabled').value==='1'};
  else if(sec==='invite')b={inviteRewardMsg:+document.getElementById('cf-inviteRewardMsg').value,inviteRewardImg:+document.getElementById('cf-inviteRewardImg').value,inviteRewardVoice:+document.getElementById('cf-inviteRewardVoice').value,inviteeRewardMsg:+document.getElementById('cf-inviteeRewardMsg').value,inviteeRewardImg:+document.getElementById('cf-inviteeRewardImg').value,inviteeRewardVoice:+document.getElementById('cf-inviteeRewardVoice').value};
  else if(sec==='defaultModel')b={defaultModel:document.getElementById('cf-defaultModel').value.trim()};
  else if(sec==='tts')b={ttsProvider:document.getElementById('cf-ttsProvider').value,ttsModel:document.getElementById('cf-ttsModel').value.trim(),ttsVoice:document.getElementById('cf-ttsVoice').value,ttsCharacter:document.getElementById('cf-ttsCharacter').value,ttsStyle:document.getElementById('cf-ttsStyle').value.trim(),liveEnabled:document.getElementById('cf-liveEnabled').checked,ttsFallback:document.getElementById('cf-ttsFallback').checked,ttsAutoStyle:document.getElementById('cf-ttsAutoStyle').checked,liveModel:document.getElementById('cf-liveModel').value.trim(),liveVoice:document.getElementById('cf-liveVoice').value};
  else if(sec==='botName')b={botName:document.getElementById('cf-botName').value.trim()};
  else if(sec==='trigger')b={triggerWords:document.getElementById('cf-triggerWords').value.trim()};
  else if(sec==='botUsername'){
    let v=document.getElementById('cf-botUsername').value.trim();
    if(v.startsWith('@'))v=v.slice(1);
    b={botUsername:v};
  }
  else if(sec==='superIds'){
    const ids=document.getElementById('cf-superIds').value.split(/[\s,;]+/).map(x=>x.trim()).filter(Boolean);
    if(ids.some(x=>!/^\d{1,15}$/.test(x))){toast('⚠️ Only numeric chat IDs are allowed','err');return;}
    b={superIds:ids};
  }
  else if(sec==='primaryToken'){
    b={primaryToken:document.getElementById('cf-primaryToken').value.trim()};
  }
  else if(sec==='password'){
    const v=document.getElementById('cf-adminPanelPassword').value;
    if(!v){toast('⚠️ To change the password, enter a new value (use the dedicated button to disable it)','err');return;}
    b={adminPanelPassword:v};
  }
  else if(sec==='multiPhoto')b={maxMultiPhoto:+document.getElementById('cf-maxMultiPhoto').value,multiPhotoPrivate:document.getElementById('cf-multiPhotoPrivate').checked,multiPhotoGroup:document.getElementById('cf-multiPhotoGroup').checked};
  else if(sec==='globalFeatures')b={
    globalWebSearch:document.getElementById('cf-globalWebSearch').checked,
    globalImportanceScore:document.getElementById('cf-globalImportanceScore').checked,
    globalMemoryEnabled:document.getElementById('cf-globalMemoryEnabled').checked,
    globalSearchLimit:+document.getElementById('cf-globalSearchLimit').value,
    globalGrpSearchLimit:+document.getElementById('cf-globalGrpSearchLimit').value,
    defaultLang:document.getElementById('cf-defaultLang').value,
    replyLang:document.getElementById('cf-replyLang').value,
  };
  const r=await api('save_global_config',{section:sec,...b});
  if(r.ok){toast('✅ Saved','ok');if(sec==='password'||sec==='primaryToken')setTimeout(reloadHere,1200);}else toast('❌ '+r.error,'err');
}

// ─── helpers ────────────────────────────────────────────────────
const pv=v=>v===null?'null':v?'true':'false';
const psel=(v,id)=>{const el=document.getElementById(id);if(el)el.value=v===null?'null':v?'true':'false';};
const gsel=id=>{const v=document.getElementById(id).value;return v==='null'?null:v==='true';};

// ─── per-chat features tab ───────────────────────────────────────
async function loadChatFeat(){
  const cid=document.getElementById('fc-cid').value.trim();
  if(!cid){toast('⚠️ Enter a Chat ID','err');return;}
  const r=await api('get_chat_config',{chatId:cid});
  if(!r.ok){toast('❌ '+r.error,'err');return;}
  const cfg=r.config;
  psel(cfg.webSearch,'fc-ws');
  psel(cfg.importanceScoring,'fc-imp');
  psel(cfg.memoryEnabled,'fc-mem');
  document.getElementById('fc-sl').value=cfg.searchLimit??'';
  document.getElementById('fc-lang').value=cfg.lang??'null';
  document.getElementById('fc-title').textContent='Chat: '+cid;
  document.getElementById('fc-panel').style.display='block';
}
async function saveChatFeat(){
  const cid=document.getElementById('fc-cid').value.trim();
  if(!cid){toast('⚠️ Enter a Chat ID','err');return;}
  const slVal=document.getElementById('fc-sl').value.trim();
  const langVal=document.getElementById('fc-lang').value;
  const r=await api('set_chat_config',{chatId:cid,webSearch:gsel('fc-ws'),importanceScoring:gsel('fc-imp'),memoryEnabled:gsel('fc-mem'),searchLimit:slVal===''?null:Number(slVal),lang:langVal==='null'?null:langVal});
  if(r.ok)toast('✅ Saved','ok');else toast('❌ '+r.error,'err');
}

