  var callState = { open:false, playingAudio:null, suggestAudio:null, freeTalk:false,
    lang: (function(){ try{ return localStorage.getItem('nikiCallLang')||'English'; }catch(e){ return 'English'; } })() };
  var callOverlay     = document.getElementById('callMode');
  var callStatusEl    = document.getElementById('callStatus');
  var callTranscriptEl= document.getElementById('callTranscript');
  var callChipsEl     = document.getElementById('callChips');
